INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26686, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他恰如其分的完成了任务。", "corrected_sentence": "他恰如其分地完成了任务。", "error_description": "错误在状语标记：“恰如其分”作状语时要用“地”，不能用“的”。应说“他恰如其分地完成了任务”，不能说“他恰如其分的完成了任务”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f663f642-d9f3-44a7-bcfa-db27a8ed1eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26686, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他做事做恰如其分。", "corrected_sentence": "他做事做得恰如其分。", "error_description": "补语标记“得”漏掉了：说明动作做得怎样，要用“动词＋得＋补语”，应说“做得恰如其分”，不能说“做恰如其分”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f663f642-d9f3-44a7-bcfa-db27a8ed1eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26688, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最穷", "is_correct": true, "explanation": "正确：“富”与“穷”相对，“最富”的反义是“最穷”，都指钱财的多少。"}, {"text": "清澈", "is_correct": false, "explanation": "无关：“清澈”形容水或眼神清亮，与钱财多少没有反义关系。"}, {"text": "狭窄", "is_correct": false, "explanation": "无关：“狭窄”指空间小，与钱财多少没有反义关系。"}, {"text": "坚硬", "is_correct": false, "explanation": "无关：“坚硬”形容物体质地，与钱财多少没有反义关系。"}], "correct_answer": "最穷", "explanations": {"最穷": "正确：“富”与“穷”相对，“最富”的反义是“最穷”，都指钱财的多少。", "清澈": "无关：“清澈”形容水或眼神清亮，与钱财多少没有反义关系。", "狭窄": "无关：“狭窄”指空间小，与钱财多少没有反义关系。", "坚硬": "无关：“坚硬”形容物体质地，与钱财多少没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f663f642-d9f3-44a7-bcfa-db27a8ed1eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26688, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最穷", "is_correct": true, "explanation": "正确：“富”与“穷”相对，“最富”的反义是“最穷”，都指钱财的多少。"}, {"text": "轻盈", "is_correct": false, "explanation": "无关：“轻盈”形容重量轻或动作灵巧，与钱财多少没有反义关系。"}, {"text": "辽阔", "is_correct": false, "explanation": "无关：“辽阔”形容地域广大，与钱财多少没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "无关：“明亮”形容光线或颜色，与钱财多少没有反义关系。"}], "correct_answer": "最穷", "explanations": {"最穷": "正确：“富”与“穷”相对，“最富”的反义是“最穷”，都指钱财的多少。", "轻盈": "无关：“轻盈”形容重量轻或动作灵巧，与钱财多少没有反义关系。", "辽阔": "无关：“辽阔”形容地域广大，与钱财多少没有反义关系。", "明亮": "无关：“明亮”形容光线或颜色，与钱财多少没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f663f642-d9f3-44a7-bcfa-db27a8ed1eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26688, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "最有钱的意思。", "primary_collocate": null, "pronunciation": "zuì fù", "ipa": "tsweɪ̯˥˩ fu˥˩", "syllable_count": 2, "sentences": [{"text": "他是我们这个城市最富的人。", "target_word": "最富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁是世界上最富的人？", "target_word": "最富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子里最富的一家养了很多牛。", "target_word": "最富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的钱比谁都多，是镇上最富的人。", "target_word": "最富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前他是最富的人，现在生活很简单。", "target_word": "最富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杂志每年都会公布全国最富的人。", "target_word": "最富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我们班，他家最富，常常请大家吃饭。", "target_word": "最富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最富的人不一定最快乐。", "target_word": "最富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老人曾是这座岛上最富的商人。", "target_word": "最富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她哥哥开了很多公司，是最富的人。", "target_word": "最富", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "最富的", "label": "定语形式"}], "register": "中性", "sense_fingerprint": "最富：钱财最多，最有钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b44a80eb-78df-43d2-b3b5-0ae745060986') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26688, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "最富", "is_correct": true, "explanation": "正确：“最富”修饰“人”，表示钱财最多，与“城市里的人”搭配。"}, {"text": "最潮湿", "is_correct": false, "explanation": "语义：“潮湿”形容环境，不能用来形容人的钱财。"}, {"text": "最干燥", "is_correct": false, "explanation": "语义：“干燥”形容空气或物体，与人的钱财无关。"}, {"text": "最滚烫", "is_correct": false, "explanation": "搭配：“滚烫”多用于温度或液体，“最滚烫的人”不通。"}], "explanations": {"最富": "正确：“最富”修饰“人”，表示钱财最多，与“城市里的人”搭配。", "最潮湿": "语义：“潮湿”形容环境，不能用来形容人的钱财。", "最干燥": "语义：“干燥”形容空气或物体，与人的钱财无关。", "最滚烫": "搭配：“滚烫”多用于温度或液体，“最滚烫的人”不通。"}, "sentence_index": 0, "correct_answer": "最富"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这栋房子是镇上最富的。", "explanation": "这里应该用〈豪华〉。最富指人或家庭钱财多，不用来形容房子。"}, {"text": "他的感情最富，常常为朋友流泪。", "explanation": "这里表示感情丰富，应该用〈丰富〉。最富只指钱财多。"}, {"text": "这块地的土质最富，适合种庄稼。", "explanation": "这里说土地肥沃，应该用〈肥沃〉。最富只指钱财多。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f663f642-d9f3-44a7-bcfa-db27a8ed1eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26688, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最富", "is_correct": true, "explanation": "正确：“最富”作谓语，说明“他家”钱财最多，与“在我们班”的语境搭配。"}, {"text": "最辣", "is_correct": false, "explanation": "语义：“辣”形容味道，不能用来形容一家人的钱财。"}, {"text": "最软", "is_correct": false, "explanation": "搭配：“软”多用于质地，“他家最软”不通。"}, {"text": "最咸", "is_correct": false, "explanation": "语义：“咸”形容味道，与家庭的钱财无关。"}], "explanations": {"最富": "正确：“最富”作谓语，说明“他家”钱财最多，与“在我们班”的语境搭配。", "最辣": "语义：“辣”形容味道，不能用来形容一家人的钱财。", "最软": "搭配：“软”多用于质地，“他家最软”不通。", "最咸": "语义：“咸”形容味道，与家庭的钱财无关。"}, "sentence_index": 6, "correct_answer": "最富"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个城市的工业最富，发展得很快。", "explanation": "这里应该用〈发达〉。最富只指钱财多，说工业发展要用〈发达〉。"}, {"text": "他的知识最富，什么都懂。", "explanation": "这里应该用〈渊博〉。最富只指钱财多，不用来形容知识的丰富。"}, {"text": "他的时间最富，每天都能去玩。", "explanation": "这里应该用〈充裕〉。最富只指钱财多，不用来形容时间的多少。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f663f642-d9f3-44a7-bcfa-db27a8ed1eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26688, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他家在村里更最富，买了三辆车。", "corrected_sentence": "他家在村里最富，买了三辆车。", "error_description": "比较级与最高级叠用：“更”是比较级，“最”是最高级，“最富”已表示最高程度，应删掉“更”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f663f642-d9f3-44a7-bcfa-db27a8ed1eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26688, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条街上最富是李叔叔一家。", "corrected_sentence": "这条街上最富的是李叔叔一家。", "error_description": "“最富”作主语或修饰后面的名词时要加“的”，应说“最富的是李叔叔一家”，漏掉“的”就不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f663f642-d9f3-44a7-bcfa-db27a8ed1eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
