INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26690, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "很肯定地说。", "primary_collocate": null, "pronunciation": "duàn yán", "ipa": "tuan˥˩ jɛn˧˥", "syllable_count": 2, "sentences": [{"text": "我敢断言，这件事不是他做的。", "target_word": "断言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察断言，那个人说了假话。", "target_word": "断言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁也不能断言明年的天气会怎么样。", "target_word": "断言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他断言这家店的菜是全城最好的。", "target_word": "断言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她断言自己一定能考上大学。", "target_word": "断言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家断言，这座山以前是海。", "target_word": "断言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友断言我会喜欢这本书。", "target_word": "断言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别急着断言，先看看结果吧。", "target_word": "断言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他断言了这场比赛的结果，后来却错了。", "target_word": "断言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不敢断言这个消息是真的。", "target_word": "断言", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "断言了", "label": "体标"}, {"form": "断言过", "label": "体标"}], "register": "书面", "sense_fingerprint": "毫不怀疑地肯定说出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc273de9-6dff-4982-aa1e-b39faa6f353a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26690, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "断言", "is_correct": true, "explanation": "正确。“我敢断言”：断言指很肯定地说出判断，与“敢”搭配自然。"}, {"text": "忽略", "is_correct": false, "explanation": "语义：“忽略”与“敢断言”的肯定语气相悖。"}, {"text": "嘲笑", "is_correct": false, "explanation": "配价：“嘲笑”需要以人为对象，不接“这件事不是他做的”这样的判断句。"}, {"text": "请教", "is_correct": false, "explanation": "搭配：“请教”针对问题或知识，不接肯定的判断。"}], "explanations": {"断言": "正确。“我敢断言”：断言指很肯定地说出判断，与“敢”搭配自然。", "忽略": "语义：“忽略”与“敢断言”的肯定语气相悖。", "嘲笑": "配价：“嘲笑”需要以人为对象，不接“这件事不是他做的”这样的判断句。", "请教": "搭配：“请教”针对问题或知识，不接肯定的判断。"}, "sentence_index": 0, "correct_answer": "断言"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我只能断言他的心思。", "explanation": "这里应该用〈猜测〉。断言表示很肯定，不能用于对他人心思这类没有把握的推测。"}, {"text": "他断言也许会赢。", "explanation": "这里应该用〈估计〉。断言表示很肯定，不能与“也许”这种不确定的语气同用。"}, {"text": "老师断言我早点休息。", "explanation": "这里应该用〈建议〉。断言用于肯定地说出判断，不用于提出要求或建议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17764293-4c0b-4945-83f3-d72c3766871b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26690, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "断言", "is_correct": true, "explanation": "正确。“朋友断言我会喜欢这本书”：断言指肯定地作出判断。"}, {"text": "退还", "is_correct": false, "explanation": "搭配：“退还”指把物品还回去，不接“会喜欢这本书”这样的判断。"}, {"text": "赞扬", "is_correct": false, "explanation": "配价：“赞扬”需要以人或行为为对象，不接判断句。"}, {"text": "催促", "is_correct": false, "explanation": "语义：“催促”是要求对方行动，与“断言”的陈述性判断不符。"}], "explanations": {"断言": "正确。“朋友断言我会喜欢这本书”：断言指肯定地作出判断。", "退还": "搭配：“退还”指把物品还回去，不接“会喜欢这本书”这样的判断。", "赞扬": "配价：“赞扬”需要以人或行为为对象，不接判断句。", "催促": "语义：“催促”是要求对方行动，与“断言”的陈述性判断不符。"}, "sentence_index": 6, "correct_answer": "断言"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我断言这个消息是不是真的。", "explanation": "这里应该用〈打听〉。断言不接“是不是”这类疑问形式，表达的是肯定的判断。"}, {"text": "公司断言了新的规定。", "explanation": "这里应该用〈宣布〉。断言表示作出判断，不能接“规定”这类要执行的事项。"}, {"text": "我断言你的帮助。", "explanation": "这里应该用〈感谢〉。断言指肯定地说出判断，不用于表达感谢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17764293-4c0b-4945-83f3-d72c3766871b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26690, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈断言着这次我一定能及格。", "corrected_sentence": "妈妈断言这次我一定能及格。", "error_description": "错误：“断言着”。“着”表示持续状态，与“断言”这种一次性的判断不合，应去掉“着”，说“断言”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17764293-4c0b-4945-83f3-d72c3766871b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26690, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从来没有断言了自己一定会赢。", "corrected_sentence": "他从来没有断言过自己一定会赢。", "error_description": "错误：“没有断言了”，应为“没有断言过”。用“没有”否定过去的经历要用体标“过”，不能用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17764293-4c0b-4945-83f3-d72c3766871b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
