INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26691, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "东西活着的力量，能让动物和植物长大。", "primary_collocate": null, "pronunciation": "shēng mìng lì", "ipa": "ʂɤŋ˥ miŋ˥˩ li˥˩", "syllable_count": 3, "sentences": [{"text": "种子里有生命力，浇水后就会发芽。", "target_word": "生命力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵老树断了，春天又长出新叶，生命力真强。", "target_word": "生命力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟的生命力很弱，需要人好好照顾。", "target_word": "生命力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仙人掌在沙漠里也能活，生命力很强。", "target_word": "生命力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些鱼的生命力强，换了水也不会死。", "target_word": "生命力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫刚出生时，生命力还很弱。", "target_word": "生命力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "竹子的生命力很强，一年能长很高。", "target_word": "生命力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有水和阳光，花的生命力会慢慢消失。", "target_word": "生命力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪还没化，小花就开了，生命力真强。", "target_word": "生命力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说这只小狗的生命力很强，会好起来的。", "target_word": "生命力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "生命力：动植物活着、生长的力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b44a80eb-78df-43d2-b3b5-0ae745060986') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26691, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生命力", "is_correct": true, "explanation": "正确。“种子里有生命力”指种子蕴含的生长力量，与后句发芽相合。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气是人的性情，种子没有脾气，句子不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：体重专指人或动物的重量，种子应说“重量”，不能说“体重”。"}, {"text": "人情味", "is_correct": false, "explanation": "语义：人情味指人际交往中的温情，用来形容种子不合逻辑。"}], "explanations": {"生命力": "正确。“种子里有生命力”指种子蕴含的生长力量，与后句发芽相合。", "脾气": "语义：脾气是人的性情，种子没有脾气，句子不通。", "体重": "搭配：体重专指人或动物的重量，种子应说“重量”，不能说“体重”。", "人情味": "语义：人情味指人际交往中的温情，用来形容种子不合逻辑。"}, "sentence_index": 0, "correct_answer": "生命力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只乌龟的生命力很长，能活一百多岁。", "explanation": "这里应该用〈寿命〉。生命力指生存、发展的力量，说活了多少年要用寿命。"}, {"text": "这匹马生命力很好，能拉动一辆很重的车。", "explanation": "这里应该用〈力气〉。拉动重物靠的是力气，生命力指生存、发展的力量，不指用力的能力。"}, {"text": "这只小猫的生命力很强，能在夜里看清老鼠。", "explanation": "这里应该用〈视力〉。能在夜里看清东西靠的是视力，生命力指生存、发展的力量，不指看的能力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f663f642-d9f3-44a7-bcfa-db27a8ed1eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26691, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生命力", "is_correct": true, "explanation": "正确。“竹子的生命力很强”指竹子生长的力量强，与后句长得快相合。"}, {"text": "幽默感", "is_correct": false, "explanation": "语义：幽默感是人的性格特征，竹子不具备这种性质，句子不通。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：“很强”形容生存能力，寿命应说“长”或“短”，不说“寿命很强”。"}, {"text": "同情心", "is_correct": false, "explanation": "语义：同情心属于有感情的人，竹子没有这种性质。"}], "explanations": {"生命力": "正确。“竹子的生命力很强”指竹子生长的力量强，与后句长得快相合。", "幽默感": "语义：幽默感是人的性格特征，竹子不具备这种性质，句子不通。", "寿命": "搭配：“很强”形容生存能力，寿命应说“长”或“短”，不说“寿命很强”。", "同情心": "语义：同情心属于有感情的人，竹子没有这种性质。"}, "sentence_index": 6, "correct_answer": "生命力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只小狗的生命力很强，学东西特别快。", "explanation": "这里应该用〈智力〉。学东西快靠的是智力，生命力指生存、发展的力量，不指认识和学习的能力。"}, {"text": "这只小狗的生命力很好，一有声音就竖起耳朵。", "explanation": "这里应该用〈听力〉。能否听到声音靠的是听力，生命力不能用来说听觉。"}, {"text": "这只小狗的生命力很好，一顿能吃两碗饭。", "explanation": "这里应该用〈食欲〉。想吃东西、胃口好指的是食欲，生命力不指这种感受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f663f642-d9f3-44a7-bcfa-db27a8ed1eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26691, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这株小麦的生命力强很，即使被踩倒也能重新长起来。", "corrected_sentence": "这株小麦的生命力很强，即使被踩倒也能重新长起来。", "error_description": "程度副词位置错误：“很”应放在形容词“强”前，说“生命力很强”，不能放在“强”后，说“生命力强很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f663f642-d9f3-44a7-bcfa-db27a8ed1eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26691, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这丛竹子有一只很强的生命力，雨后长得特别快。", "corrected_sentence": "这丛竹子有一股很强的生命力，雨后长得特别快。", "error_description": "量词错误：“生命力”前应用“股”或“种”，不能用“只”（“只”多用于动物或成对之物）。正确说法是“一股很强的生命力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f663f642-d9f3-44a7-bcfa-db27a8ed1eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
