INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26694, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种有叶片的玩具，风吹时会转动。", "primary_collocate": null, "pronunciation": "fēng chē", "ipa": "fɤŋ˥ ʈʂʰɤ˥", "syllable_count": 2, "sentences": [{"text": "孩子手里拿着一个红风车。", "target_word": "风车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一吹，风车就转起来了。", "target_word": "风车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹跑得很快，风车转个不停。", "target_word": "风车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园门口有人卖风车。", "target_word": "风车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我小时候最爱玩风车。", "target_word": "风车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把风车插在花盆里。", "target_word": "风车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风车上有四片彩色的叶子。", "target_word": "风车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有风，风车不会转。", "target_word": "风车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶给小弟做了一个纸风车。", "target_word": "风车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风车在院子里慢慢转着。", "target_word": "风车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个风车", "label": "量词"}, {"form": "纸风车", "label": "复合"}, {"form": "風車", "label": "繁体"}], "register": "中性", "sense_fingerprint": "风吹就转的叶片玩具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fb7fbe2-03dc-4c00-8c7e-e16f093b9f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26694, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱体积大，孩子不能用手拿着。"}, {"text": "风车", "is_correct": true, "explanation": "正确：有叶片、风吹会转动的玩具，符合语境。"}, {"text": "黑板", "is_correct": false, "explanation": "体貌：黑板本身是黑色的，与“红”的颜色不符。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不能拿在手里。"}], "explanations": {"冰箱": "语义：冰箱体积大，孩子不能用手拿着。", "风车": "正确：有叶片、风吹会转动的玩具，符合语境。", "黑板": "体貌：黑板本身是黑色的，与“红”的颜色不符。", "房子": "语义：房子不能拿在手里。"}, "sentence_index": 0, "correct_answer": "风车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "屋檐下挂着风车，风一吹就叮当响。", "explanation": "这里应该用〈风铃〉。风铃挂在屋檐下，风一吹会发出声音；风车是靠叶片转动的玩具，不会发出响声。"}, {"text": "洗完澡，我用风车把头发吹干了。", "explanation": "这里应该用〈吹风机〉。吹风机通电吹出热风；风车是靠风吹转动的玩具，不能吹干头发。"}, {"text": "夏天太热了，我打开风车对着脸吹。", "explanation": "这里应该用〈风扇〉。风扇靠电机带动叶片送风；风车是靠风吹转动的玩具，不能用来送风。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '523bc86b-7d76-4cbe-bed4-12eddf214c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26694, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手机", "is_correct": false, "explanation": "语义：手机上不会长出叶子。"}, {"text": "墨水", "is_correct": false, "explanation": "体貌：墨水是液体，不能附着四片彩色的叶子。"}, {"text": "风车", "is_correct": true, "explanation": "正确：有叶片、风吹会转动的玩具，叶片上可以有彩色图案，符合语境。"}, {"text": "天空", "is_correct": false, "explanation": "语义：叶子不会挂在天空上。"}], "explanations": {"手机": "语义：手机上不会长出叶子。", "墨水": "体貌：墨水是液体，不能附着四片彩色的叶子。", "风车": "正确：有叶片、风吹会转动的玩具，叶片上可以有彩色图案，符合语境。", "天空": "语义：叶子不会挂在天空上。"}, "sentence_index": 6, "correct_answer": "风车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用鞭子抽风车，让它一直转。", "explanation": "这里应该用〈陀螺〉。陀螺要用鞭子抽才会转；风车靠风吹转动，不用鞭子抽。"}, {"text": "飞机的风车一直在转。", "explanation": "这里应该用〈螺旋桨〉。螺旋桨装在飞机上，靠发动机带动；风车是靠风吹转动的叶片玩具，不装在飞机上。"}, {"text": "河边的风车靠水流转动，可以把水提到田里。", "explanation": "这里应该用〈水车〉。水车靠水流带动，用来提水灌溉；风车靠风力转动，不能靠水流。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '523bc86b-7d76-4cbe-bed4-12eddf214c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26694, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "风一吹，院子里的风车转下来了。", "corrected_sentence": "风一吹，院子里的风车转起来了。", "error_description": "补语错误：风车开始转动应说“转起来”；“转下来”表示从高处往下转，这里不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '523bc86b-7d76-4cbe-bed4-12eddf214c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26694, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋檐下的风车慢慢转了着。", "corrected_sentence": "屋檐下的风车慢慢转着。", "error_description": "动态助词错误：“着”表示状态持续，不能和“了”叠用，应说“转着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '523bc86b-7d76-4cbe-bed4-12eddf214c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
