INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26696, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26696, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用磨把粮食变成面粉。", "primary_collocate": null, "pronunciation": "mó miàn", "ipa": "mwɔ˧˥ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "爷爷每天早上去村里磨面。", "target_word": "磨面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前农村人用石磨磨面。", "target_word": "磨面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把小麦送到磨坊磨面。", "target_word": "磨面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说，今天要磨面做馒头。", "target_word": "磨面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家有一头驴，专门用来磨面。", "target_word": "磨面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候我常帮妈妈磨面。", "target_word": "磨面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器磨面又快又细。", "target_word": "磨面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "磨面之前，要先把麦子洗干净。", "target_word": "磨面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的老人还用石头磨面。", "target_word": "磨面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天要包饺子，所以今天得磨面。", "target_word": "磨面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "磨过面", "label": "体标"}, {"form": "磨面机", "label": "复合"}], "register": "口语", "sense_fingerprint": "用磨把麦子等粮食磨成面粉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f5780da-c6e6-4d29-93fe-0d7e321c3e1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26696, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "磨面", "is_correct": true, "explanation": "「去村里磨面」指到村里把粮食磨成面粉，符合题干语境。"}, {"text": "辞职", "is_correct": false, "explanation": "语义：「辞职」与「去村里」的行动不相容，与题干语境不合。"}, {"text": "驾临", "is_correct": false, "explanation": "语域：「驾临」是敬重的书面语，与口语化的日常叙述不合。"}, {"text": "哭", "is_correct": false, "explanation": "语义：「哭」与「磨面」无关，「去村里哭」与题干的劳作语境不合。"}], "explanations": {"磨面": "「去村里磨面」指到村里把粮食磨成面粉，符合题干语境。", "辞职": "语义：「辞职」与「去村里」的行动不相容，与题干语境不合。", "驾临": "语域：「驾临」是敬重的书面语，与口语化的日常叙述不合。", "哭": "语义：「哭」与「磨面」无关，「去村里哭」与题干的劳作语境不合。"}, "sentence_index": 0, "correct_answer": "磨面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在案板上磨面，准备擀饺子皮。", "explanation": "这里应该用〈擀面〉。擀饺子皮要用擀面杖擀，“磨面”指把粮食磨成粉。"}, {"text": "他用压面机磨面，做成了细细的面条。", "explanation": "这里应该用〈轧〉。轧面条是用机器把面团压延成条，“磨面”是把粮食磨成粉，两者不能混用。"}, {"text": "奶奶在大盆里磨面，准备包饺子。", "explanation": "这里应该用〈和面〉。在盆里把面粉加水拌成面团要用“和面”，“磨面”是把粮食磨成粉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26696, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "磨面", "is_correct": true, "explanation": "「这台机器磨面又快又细」指机器把粮食磨成细面，符合题干语境。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：机器不能「唱歌」，「这台机器唱歌又快又细」与常识不合。"}, {"text": "思考", "is_correct": false, "explanation": "语义：「思考」是人的心智活动，与「快」「细」的描述不搭。"}, {"text": "打扮", "is_correct": false, "explanation": "语义：「打扮」指人修饰外表，机器无法打扮，与题干不合。"}], "explanations": {"磨面": "「这台机器磨面又快又细」指机器把粮食磨成细面，符合题干语境。", "唱歌": "语义：机器不能「唱歌」，「这台机器唱歌又快又细」与常识不合。", "思考": "语义：「思考」是人的心智活动，与「快」「细」的描述不搭。", "打扮": "语义：「打扮」指人修饰外表，机器无法打扮，与题干不合。"}, "sentence_index": 6, "correct_answer": "磨面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在锅里磨面条，热气腾腾的。", "explanation": "这里应该用〈煮〉。把面条下锅做熟要用“煮”，“磨面”是把粮食磨成粉。"}, {"text": "妈妈磨饺子时，手指把饺子皮捏紧了。", "explanation": "这里应该用〈包〉。做饺子要用“包”，“磨”是把粮食磨成粉，不能用来做饺子。"}, {"text": "妈妈把面团磨成细条，给我们下面吃。", "explanation": "这里应该用〈切〉。把面团做成细条要切，“磨”不能用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26696, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我帮奶奶磨面得很快，一下午就磨完了。", "corrected_sentence": "我帮奶奶磨面磨得很快，一下午就磨完了。", "error_description": "补语须重复动词：“磨面”是动宾结构，带“得”字补语时应说“磨面磨得很快”，不说“磨面得很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26696, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶今天要把磨面，明天包饺子。", "corrected_sentence": "奶奶今天要磨面，明天包饺子。", "error_description": "“把”字句要求“把+宾语+动词”，“磨面”前不能加“把”，应说“今天要磨面”，不说“今天要把磨面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
