INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26698, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '571872f6-9807-451a-bc7d-5a66fa6060b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26698, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "基因是决定你长得像谁、身体好不好的一种小东西。", "primary_collocate": null, "pronunciation": "jī yīn", "ipa": "tɕi⁵⁵ in⁵⁵", "syllable_count": 2, "sentences": [{"text": "孩子的眼睛像妈妈，这是基因的作用。", "target_word": "基因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说这种病和基因有关系。", "target_word": "基因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他个子很高，因为爸爸的基因好。", "target_word": "基因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家正在研究这个基因。", "target_word": "基因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双胞胎的基因几乎一模一样。", "target_word": "基因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些病会通过基因传给孩子。", "target_word": "基因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的好嗓子来自家人的基因。", "target_word": "基因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院可以检查你的基因。", "target_word": "基因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的基因决定了头发的颜色。", "target_word": "基因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家改变了老鼠的基因。", "target_word": "基因", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "种", "label": "量词"}, {"form": "基因组", "label": "复合"}], "register": "中性", "sense_fingerprint": "生物遗传的基本单位，决定长相和健康", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47c36c6a-10d1-484f-a144-0a730fa56e1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26698, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "基因", "is_correct": true, "explanation": "基因是决定遗传特征的基本单位，“这是基因的作用”正好解释孩子眼睛像妈妈的原因，符合句意。"}, {"text": "疫苗", "is_correct": false, "explanation": "语义：疫苗用于预防疾病，与孩子长得像妈妈无关，“这是疫苗的作用”句意不通。"}, {"text": "性格", "is_correct": false, "explanation": "语义：性格影响行为，不能决定眼睛像不像妈妈，与外貌遗传的语境冲突。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：天气不会造成眼睛像妈妈，“这是天气的作用”与前句的外貌描述搭配不当。"}], "explanations": {"基因": "基因是决定遗传特征的基本单位，“这是基因的作用”正好解释孩子眼睛像妈妈的原因，符合句意。", "疫苗": "语义：疫苗用于预防疾病，与孩子长得像妈妈无关，“这是疫苗的作用”句意不通。", "性格": "语义：性格影响行为，不能决定眼睛像不像妈妈，与外貌遗传的语境冲突。", "天气": "搭配：天气不会造成眼睛像妈妈，“这是天气的作用”与前句的外貌描述搭配不当。"}, "sentence_index": 0, "correct_answer": "基因"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这笔钱存进了基因。", "explanation": "这里应该用〈基金〉。基因指遗传的基本单位，存钱要用〈基金〉，两者读音相近，容易混淆。"}, {"text": "这次失败的基因是准备不足。", "explanation": "这里应该用〈原因〉。基因是遗传单位，说“失败的原因”要用〈原因〉。"}, {"text": "我身上有一只基因，所以我很聪明。", "explanation": "这里应该用〈个〉或〈种〉。“只”用于动物，基因是抽象的遗传单位，不能用“只”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '571872f6-9807-451a-bc7d-5a66fa6060b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26698, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "基因", "is_correct": true, "explanation": "“来自家人的基因”说明嗓子好的遗传来源，与句中的“好嗓子”和“家人”相符。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不能遗传给人嗓子好的特质，“来自家人的手机”与语境冲突。"}, {"text": "故事", "is_correct": false, "explanation": "语义：故事不是嗓子的来源，句中的“好嗓子”与“故事”没有联系。"}, {"text": "比赛", "is_correct": false, "explanation": "搭配：“来自”后面接比赛不通，比赛不能作为嗓子好的来源。"}], "explanations": {"基因": "“来自家人的基因”说明嗓子好的遗传来源，与句中的“好嗓子”和“家人”相符。", "手机": "语义：手机不能遗传给人嗓子好的特质，“来自家人的手机”与语境冲突。", "故事": "语义：故事不是嗓子的来源，句中的“好嗓子”与“故事”没有联系。", "比赛": "搭配：“来自”后面接比赛不通，比赛不能作为嗓子好的来源。"}, "sentence_index": 6, "correct_answer": "基因"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "影响孩子成绩的主要基因是睡眠。", "explanation": "这里应该用〈因素〉。基因指遗传单位，不能用来泛指影响成绩的因素，这时要用〈因素〉。"}, {"text": "这里是军事基因，不许外人进入。", "explanation": "这里应该用〈基地〉。基因不是场所，指军事场所要用〈基地〉。"}, {"text": "妈妈的身体里有一块基因，所以她很健康。", "explanation": "这里应该用〈个〉或〈种〉。“块”用于块状的东西，基因不能用“块”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '571872f6-9807-451a-bc7d-5a66fa6060b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26698, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈说她的高个子对基因有关系。", "corrected_sentence": "妈妈说她的高个子跟基因有关系。", "error_description": "错误形式是「对基因有关系」，正确形式是「跟基因有关系」：表示两者有联系要说「跟……有关系」，不能用「对」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '571872f6-9807-451a-bc7d-5a66fa6060b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26698, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种病和一只基因有关。", "corrected_sentence": "这种病和一个基因有关。", "error_description": "错误形式是「一只基因」，正确形式是「一个基因」：「只」用于动物，基因不能用「只」计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '571872f6-9807-451a-bc7d-5a66fa6060b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
