INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26700, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手或身体让东西换方向或换位置。", "primary_collocate": null, "pronunciation": "zhuǎn", "ipa": "ʈʂwan˨˩˦", "syllable_count": 1, "sentences": [{"text": "他转过身，看了我一眼。", "target_word": "转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把椅子转一下，对着窗户。", "target_word": "转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她转头看向窗外。", "target_word": "转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让大家把书转过来。", "target_word": "转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把杯子转过来，让杯把对着我。", "target_word": "转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明转过脸，认真地看着黑板。", "target_word": "转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你把地图转一下，就能看懂了。", "target_word": "转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈转身走进了厨房。", "target_word": "转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把头转向我，笑了笑。", "target_word": "转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别转脑袋，请看黑板。", "target_word": "转", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "转了", "label": "体标"}, {"form": "转过", "label": "体标"}, {"form": "转着", "label": "体标"}, {"form": "轉", "label": "繁体"}], "register": "口语", "sense_fingerprint": "用手或身体使东西改变朝向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f5780da-c6e6-4d29-93fe-0d7e321c3e1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26700, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "转", "is_correct": true, "explanation": "正确。转 zhuǎn，表示用手或身体让东西换方向或换位置。"}, {"text": "赚", "is_correct": false, "explanation": "zhuàn（第四声）与 zhuǎn（第三声）声调不同，意思是赚钱。"}, {"text": "专", "is_correct": false, "explanation": "zhuān（第一声）与 zhuǎn（第三声）声调不同，意思是专门、专业。"}, {"text": "砖", "is_correct": false, "explanation": "zhuān（第一声）与 zhuǎn（第三声）声调不同，意思是砖头。"}, {"text": "展", "is_correct": false, "explanation": "zhǎn（第三声）比 zhuǎn 少了介音 u，声母和声调相同，意思是展开。"}], "explanations": {"转": "正确。转 zhuǎn，表示用手或身体让东西换方向或换位置。", "赚": "zhuàn（第四声）与 zhuǎn（第三声）声调不同，意思是赚钱。", "专": "zhuān（第一声）与 zhuǎn（第三声）声调不同，意思是专门、专业。", "砖": "zhuān（第一声）与 zhuǎn（第三声）声调不同，意思是砖头。", "展": "zhǎn（第三声）比 zhuǎn 少了介音 u，声母和声调相同，意思是展开。"}, "sentence_index": null, "correct_answer": "转"}, "level_3": {"options": [{"text": "转", "is_correct": true, "explanation": "正确。“转过身”指身体改变朝向，符合句意。"}, {"text": "走", "is_correct": false, "explanation": "搭配：“走”表示移动位置，不表示身体朝向改变，“走过身”不通。"}, {"text": "看", "is_correct": false, "explanation": "语义：“看”指视线活动，身体并没有换方向，且与后文“看了我一眼”重复。"}, {"text": "躺", "is_correct": false, "explanation": "配价：“躺”是不及物动词，后面不能带“身”作宾语，“躺过身”不成立。"}], "explanations": {"转": "正确。“转过身”指身体改变朝向，符合句意。", "走": "搭配：“走”表示移动位置，不表示身体朝向改变，“走过身”不通。", "看": "语义：“看”指视线活动，身体并没有换方向，且与后文“看了我一眼”重复。", "躺": "配价：“躺”是不及物动词，后面不能带“身”作宾语，“躺过身”不成立。"}, "sentence_index": 0, "correct_answer": "转"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她把湿毛巾转干了，晾在阳台上。", "explanation": "这里应该用〈拧〉。拧可以把湿毛巾拧干，“转干”不是这个搭配，不能说。"}, {"text": "她一页一页地转着日记，看得很仔细。", "explanation": "这里应该用〈翻〉。一页一页地换页要说“翻”，“转”不能这样用。"}, {"text": "他转伤了脚踝，只好在家休息。", "explanation": "这里应该用〈扭伤〉。关节受伤说“扭伤”，“转伤”不是这个搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26700, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "转", "is_correct": true, "explanation": "正确。转 zhuǎn，表示用手或身体让东西换方向或换位置。"}, {"text": "准", "is_correct": false, "explanation": "zhǔn（第三声）与 zhuǎn 声调相同，韵母仅一个元音不同（ən 与 an），意思是准确。"}, {"text": "喘", "is_correct": false, "explanation": "chuǎn（第三声）与 zhuǎn（第三声）声调相同，声母不同（ch 与 zh），意思是喘气。"}, {"text": "赚", "is_correct": false, "explanation": "zhuàn（第四声）与 zhuǎn（第三声）声调不同，意思是赚钱。"}, {"text": "专", "is_correct": false, "explanation": "zhuān（第一声）与 zhuǎn（第三声）声调不同，意思是专门、专业。"}], "explanations": {"转": "正确。转 zhuǎn，表示用手或身体让东西换方向或换位置。", "准": "zhǔn（第三声）与 zhuǎn 声调相同，韵母仅一个元音不同（ən 与 an），意思是准确。", "喘": "chuǎn（第三声）与 zhuǎn（第三声）声调相同，声母不同（ch 与 zh），意思是喘气。", "赚": "zhuàn（第四声）与 zhuǎn（第三声）声调不同，意思是赚钱。", "专": "zhuān（第一声）与 zhuǎn（第三声）声调不同，意思是专门、专业。"}, "sentence_index": null, "correct_answer": "转"}, "level_3": {"options": [{"text": "转", "is_correct": true, "explanation": "正确。“转一下”指让地图轻轻换个方向，符合句意。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是抛掷的意思，把地图扔一下并不能让人看懂地图，句意不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，不能说“吃地图”。"}, {"text": "游", "is_correct": false, "explanation": "配价：“游”是不及物动词，不能直接带“地图”作宾语。"}], "explanations": {"转": "正确。“转一下”指让地图轻轻换个方向，符合句意。", "扔": "语义：“扔”是抛掷的意思，把地图扔一下并不能让人看懂地图，句意不通。", "吃": "搭配：“吃”的宾语应是食物，不能说“吃地图”。", "游": "配价：“游”是不及物动词，不能直接带“地图”作宾语。"}, "sentence_index": 6, "correct_answer": "转"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "清晨的鸟叫声转醒了熟睡的弟弟。", "explanation": "这里应该用〈叫醒〉。转醒是不及物动词，不能带宾语，叫醒别人要说“叫醒”。"}, {"text": "他把废纸转成一团，扔进了垃圾桶。", "explanation": "这里应该用〈揉〉。把纸弄成一团要说“揉”，“转”只表示改变方向，不能这样用。"}, {"text": "这件衣服今天转八折，很划算。", "explanation": "这里应该用〈打〉。“打八折”是固定搭配，“转”不能用于折扣。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26700, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把椅子转，面对着我。", "corrected_sentence": "她把椅子转过来，面对着我。", "error_description": "错误：“把椅子转”后面缺少补语。“把”字句中动词后通常要带补语或其他成分，应说“把椅子转过来”，表示椅子转向我这边。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26700, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她转身过，把门关上了。", "corrected_sentence": "她转过身，把门关上了。", "error_description": "错误：动词后的“过”位置不对。“过”应紧跟动词“转”，应说“转过身”，表示转身这一动作已经完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
