INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26702, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让电出来。", "primary_collocate": null, "pronunciation": "fā diàn", "ipa": "fa˥ tiɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这座水电站每天都在发电。", "target_word": "发电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳能板白天可以发电。", "target_word": "发电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风很大的时候，风车发电更多。", "target_word": "发电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的小水电站为村子发电。", "target_word": "发电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "停电后，学校用机器发电。", "target_word": "发电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工厂用煤发电。", "target_word": "发电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里没有阳光，太阳能板不能发电。", "target_word": "发电", "complexity_tier": "T3", "furigana": "yè lǐ méi yǒu yáng guāng, tài yáng néng bǎn bù néng fā diàn.", "sentence_source": "generated"}, {"text": "海边的风车一年四季都在发电。", "target_word": "发电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想用河水发电。", "target_word": "发电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器坏了，不能发电了。", "target_word": "发电", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发了电", "label": "完成体"}, {"form": "发电机", "label": "复合"}, {"form": "发电站", "label": "复合"}, {"form": "發電", "label": "繁体"}], "register": "中性", "sense_fingerprint": "利用水、风、太阳等产生电能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59cd57e6-a11a-4731-b10a-b0c4705d2478') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26702, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发电", "is_correct": true, "explanation": "正确：水电站的功能是产生电能，“发电”与“每天都在”相合。"}, {"text": "跑步", "is_correct": false, "explanation": "搭配：“跑步”的主体是人，水电站不能跑步。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：“唱歌”的主体是人，水电站不能唱歌。"}, {"text": "锻炼", "is_correct": false, "explanation": "搭配：“锻炼”指人的身体练习，不能用于水电站。"}], "explanations": {"发电": "正确：水电站的功能是产生电能，“发电”与“每天都在”相合。", "跑步": "搭配：“跑步”的主体是人，水电站不能跑步。", "唱歌": "搭配：“唱歌”的主体是人，水电站不能唱歌。", "锻炼": "搭配：“锻炼”指人的身体练习，不能用于水电站。"}, "sentence_index": 0, "correct_answer": "发电"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个变电站为村子发电。", "explanation": "这里应该用〈供电〉。把电送给用户用“供电”，“发电”指产生电能，变电站不产生电。"}, {"text": "高压线路负责发电。", "explanation": "这里应该用〈输电〉。把电能送出去用“输电”，“发电”指产生电能，线路不产生电。"}, {"text": "手机需要发电。", "explanation": "这里应该用〈充电〉。给电池补充电能用“充电”，“发电”指产生电能，手机不能发电。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f61c87a-2f96-4f96-b39a-add6d62ee4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26702, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发电", "is_correct": true, "explanation": "正确：夜里没有阳光，太阳能板就不能产生电能，“发电”符合语境。"}, {"text": "煮饭", "is_correct": false, "explanation": "搭配：“煮饭”的对象是米和食物，太阳能板不能用来煮饭。"}, {"text": "开会", "is_correct": false, "explanation": "搭配：“开会”的主体是人，太阳能板不能开会。"}, {"text": "说话", "is_correct": false, "explanation": "语义：太阳能板是设备，不会说话，与句子意思不符。"}], "explanations": {"发电": "正确：夜里没有阳光，太阳能板就不能产生电能，“发电”符合语境。", "煮饭": "搭配：“煮饭”的对象是米和食物，太阳能板不能用来煮饭。", "开会": "搭配：“开会”的主体是人，太阳能板不能开会。", "说话": "语义：太阳能板是设备，不会说话，与句子意思不符。"}, "sentence_index": 6, "correct_answer": "发电"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个电炉子通电后很快发电。", "explanation": "这里应该用〈发热〉。产生热量用“发热”，“发电”指产生电能，电炉子不是用来发电的。"}, {"text": "灯泡通电后会发电。", "explanation": "这里应该用〈发光〉。灯泡放出光用“发光”，“发电”指产生电能。"}, {"text": "火箭发电升空。", "explanation": "这里应该用〈发射〉。火箭等发射物升空用“发射”，“发电”不能用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f61c87a-2f96-4f96-b39a-add6d62ee4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26702, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座小水电站每天能发电一百个。", "corrected_sentence": "这座小水电站每天能发电一百度。", "error_description": "量词错误：“发电”的电量应以“度”计，说“发电一百个”不符合习惯，应改为“发电一百度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f61c87a-2f96-4f96-b39a-add6d62ee4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26702, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们村子用风力很发电，已经十年了。", "corrected_sentence": "我们村子用风力发电，已经十年了。", "error_description": "程度副词错误：「很」修饰的是形容词或心理动词，不能直接修饰动作动词「发电」，应去掉「很」，说「用风力发电」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f61c87a-2f96-4f96-b39a-add6d62ee4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
