INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26704, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一块平的东西。", "primary_collocate": null, "pronunciation": "bǎn", "ipa": "pan˨˩˦", "syllable_count": 1, "sentences": [{"text": "孩子们在地上放了一块板，当作小桥。", "target_word": "板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块板又平又大，可以当桌子用。", "target_word": "板", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他站在一块板上，慢慢过了河。", "target_word": "板", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那块板上有很多小洞。", "target_word": "板", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把一块板架在两块砖上，当作临时桌子。", "target_word": "板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块板有点儿歪，要放平。", "target_word": "板", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地上有一块板，小心别绊倒。", "target_word": "板", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在两把椅子中间搭了一块板。", "target_word": "板", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块板是白色的，很干净。", "target_word": "板", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们把一块板放在箱子上当座位。", "target_word": "板", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "木板", "label": "复合"}, {"form": "黑板", "label": "复合"}], "register": "中性", "sense_fingerprint": "一块平的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7182c7ee-be87-4d6c-bc52-b70eaa74ce89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26704, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "半", "is_correct": false, "explanation": "bàn（第四声）与 bǎn（第三声）声调不同，意思是一半。"}, {"text": "板", "is_correct": true, "explanation": "正确答案：板（bǎn），指一块平的东西。"}, {"text": "晚", "is_correct": false, "explanation": "声母 w 与 b 不同，声调同为第三声，意思是晚上。"}, {"text": "胆", "is_correct": false, "explanation": "dǎn（第三声）与 bǎn 声调相同，只差声母（d 与 b），意思是胆子。"}, {"text": "毯", "is_correct": false, "explanation": "tǎn（第三声）与 bǎn 只差声母（t 与 b），意思是毯子。"}, {"text": "保", "is_correct": false, "explanation": "bǎo（第三声）与 bǎn 只差韵尾（ao 与 an），意思是保护。"}], "explanations": {"半": "bàn（第四声）与 bǎn（第三声）声调不同，意思是一半。", "板": "正确答案：板（bǎn），指一块平的东西。", "晚": "声母 w 与 b 不同，声调同为第三声，意思是晚上。", "胆": "dǎn（第三声）与 bǎn 声调相同，只差声母（d 与 b），意思是胆子。", "毯": "tǎn（第三声）与 bǎn 只差声母（t 与 b），意思是毯子。", "保": "bǎo（第三声）与 bǎn 只差韵尾（ao 与 an），意思是保护。"}, "sentence_index": null, "correct_answer": "板"}, "level_3": {"options": [{"text": "糖", "is_correct": false, "explanation": "语义：糖是食物，放在地上不能当小桥使用，与“当作小桥”矛盾。"}, {"text": "板", "is_correct": true, "explanation": "正确：板，指一块平的东西，可以放在地上当小桥。"}, {"text": "棉花", "is_correct": false, "explanation": "语义：棉花松软，无法铺成稳固的桥面，不能“当作小桥”。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干易碎，不能承重，与“当作小桥”的用途矛盾。"}], "explanations": {"糖": "语义：糖是食物，放在地上不能当小桥使用，与“当作小桥”矛盾。", "板": "正确：板，指一块平的东西，可以放在地上当小桥。", "棉花": "语义：棉花松软，无法铺成稳固的桥面，不能“当作小桥”。", "饼干": "语义：饼干易碎，不能承重，与“当作小桥”的用途矛盾。"}, "sentence_index": 0, "correct_answer": "板"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "湖面上漂着一板落叶，很好看。", "explanation": "这里应该用〈片〉。落叶是薄而轻的东西，用“片”；“板”指硬而厚的板子，不用于树叶。"}, {"text": "他喝了一板牛奶，很解渴。", "explanation": "这里应该用〈杯〉。板是平的块状物，不用来量液体；牛奶要用“杯”“瓶”等量词。"}, {"text": "门口有一只板，挡着路。", "explanation": "这里应该用〈块〉。板是块状的，应用量词“块”；“只”多用于动物等，不能用来数板子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d57181f-830c-4e91-ae6e-299736af61ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26704, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "办", "is_correct": false, "explanation": "bàn（第四声）与 bǎn（第三声）声调不同，意思是办理、办法。"}, {"text": "板", "is_correct": true, "explanation": "正确答案：板（bǎn），指一块平的东西。"}, {"text": "满", "is_correct": false, "explanation": "声母 m 与 b 不同，声调同为第三声，意思是装满、满足。"}, {"text": "反", "is_correct": false, "explanation": "声母 f 与 b 不同，声调同为第三声，意思是相反。"}, {"text": "绑", "is_correct": false, "explanation": "韵尾 ng 与 n 不同（bǎng 与 bǎn），意思是捆绑。"}, {"text": "班", "is_correct": false, "explanation": "bān（第一声）与 bǎn（第三声）声调不同，意思是班级。"}], "explanations": {"办": "bàn（第四声）与 bǎn（第三声）声调不同，意思是办理、办法。", "板": "正确答案：板（bǎn），指一块平的东西。", "满": "声母 m 与 b 不同，声调同为第三声，意思是装满、满足。", "反": "声母 f 与 b 不同，声调同为第三声，意思是相反。", "绑": "韵尾 ng 与 n 不同（bǎng 与 bǎn），意思是捆绑。", "班": "bān（第一声）与 bǎn（第三声）声调不同，意思是班级。"}, "sentence_index": null, "correct_answer": "板"}, "level_3": {"options": [{"text": "太阳", "is_correct": false, "explanation": "语义：太阳在天上，不会落在地上绊人，与“地上”矛盾。"}, {"text": "板", "is_correct": true, "explanation": "正确：板，指一块平的东西，可以落在地上，人可能被绊倒。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮在天上，不能落在地上，与“地上有”矛盾。"}, {"text": "云", "is_correct": false, "explanation": "搭配：“云”一般用“朵”或“片”，不用“块”，且云不会落在地上。"}], "explanations": {"太阳": "语义：太阳在天上，不会落在地上绊人，与“地上”矛盾。", "板": "正确：板，指一块平的东西，可以落在地上，人可能被绊倒。", "月亮": "语义：月亮在天上，不能落在地上，与“地上有”矛盾。", "云": "搭配：“云”一般用“朵”或“片”，不用“块”，且云不会落在地上。"}, "sentence_index": 6, "correct_answer": "板"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这块板当成毛巾，折起来放进了书包。", "explanation": "这里应该用〈布〉。板是平的块状物，不能像布一样折起来；能折叠的是布、纸等软薄物。"}, {"text": "他用一板石头砌了一面墙。", "explanation": "这里应该用〈块〉。石头是块状的，应用量词“块”；“板”指平的板子，不用来数石头。"}, {"text": "他搬起一把板，走进了屋子。", "explanation": "这里应该用〈块〉。“把”用于有柄的器具，如刀、椅子；板子是块状的，不能用“把”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d57181f-830c-4e91-ae6e-299736af61ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26704, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只小猫躺在一块板休息。", "corrected_sentence": "那只小猫躺在一块板上休息。", "error_description": "错误：“在”后面表示地点时，名词“板”后面要加方位词“上”，说“在一块板上”。应说“那只小猫躺在一块板上休息”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d57181f-830c-4e91-ae6e-299736af61ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26704, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们在椅子之间搭了一颗板。", "corrected_sentence": "孩子们在椅子之间搭了一块板。", "error_description": "错误：“颗”用于颗粒状的小东西，不能用于板子。“板”是平的块状物，量词应用“块”，应说“一块板”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d57181f-830c-4e91-ae6e-299736af61ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
