INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26706, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "太阳能是太阳发出的能量，可以转化成电或热，用来发电或烧水。", "primary_collocate": null, "pronunciation": "tài yáng néng", "ipa": "tʰai˥˩ jaŋ˧˥ nɤŋ˧˥", "syllable_count": 3, "sentences": [{"text": "我家的热水器用太阳能烧水。", "target_word": "太阳能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳能是干净的能源，不会弄脏空气。", "target_word": "太阳能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋顶上的板子能把太阳能变成电。", "target_word": "太阳能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆小车是用太阳能走的。", "target_word": "太阳能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳能灯白天存电，晚上亮着。", "target_word": "太阳能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的屋顶装了太阳能板。", "target_word": "太阳能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阴天的时候，太阳能比较少。", "target_word": "太阳能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多国家都在用太阳能发电。", "target_word": "太阳能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小计算器用太阳能，不用电池。", "target_word": "太阳能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "西北地区阳光多，适合用太阳能。", "target_word": "太阳能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "太阳能板", "label": "复合"}, {"form": "太阳能热水器", "label": "复合"}, {"form": "太陽能", "label": "繁体"}], "register": "中性", "sense_fingerprint": "太阳发出的能量，可转化为电或热，用于发电、烧水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7870b6f4-2759-41c0-b1b7-31d9f7ccd8bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26706, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "太阳能", "is_correct": true, "explanation": "符合语境：太阳能可以用来烧水，热水器用它加热。"}, {"text": "月光", "is_correct": false, "explanation": "语义：月光很弱，不能用来给热水器加热，句子意思不通。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：冰块是冷的，不能用来烧水。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：烧水需要燃料或热源，“玻璃”不能用来烧水。"}], "explanations": {"太阳能": "符合语境：太阳能可以用来烧水，热水器用它加热。", "月光": "语义：月光很弱，不能用来给热水器加热，句子意思不通。", "冰块": "语义：冰块是冷的，不能用来烧水。", "玻璃": "搭配：烧水需要燃料或热源，“玻璃”不能用来烧水。"}, "sentence_index": 0, "correct_answer": "太阳能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她每天早上都去窗边晒太阳能。", "explanation": "这里应该用〈太阳〉。“晒太阳”指晒太阳光取暖，“太阳能”指能量，不能用来晒。"}, {"text": "太阳能每天从东边升起。", "explanation": "这里应该用〈太阳〉。“太阳能”指能量，升起的是天体“太阳”。"}, {"text": "他坐在太阳能上面看书，很舒服。", "explanation": "这里应该用〈石头〉。“太阳能”指能量，不是可以坐的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb06fdd9-08b5-4670-be89-e1f673d9f1c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26706, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "太阳能", "is_correct": true, "explanation": "符合语境：阴天时太阳能转化的能量比较少。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果的多少与天气没有直接关系，阴天水果比较少的说法不通。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡的多少与阴天没有关系，句子意思不通。"}, {"text": "普通话", "is_correct": false, "explanation": "搭配：“比较少”描述的是能量或数量，不能用来说普通话。"}], "explanations": {"太阳能": "符合语境：阴天时太阳能转化的能量比较少。", "水果": "语义：水果的多少与天气没有直接关系，阴天水果比较少的说法不通。", "咖啡": "语义：咖啡的多少与阴天没有关系，句子意思不通。", "普通话": "搭配：“比较少”描述的是能量或数量，不能用来说普通话。"}, "sentence_index": 6, "correct_answer": "太阳能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在海边晒太阳能浴。", "explanation": "这里应该用〈日光〉。“晒日光浴”是接受阳光照射，“太阳能”是能量，不能用来晒。"}, {"text": "太阳能是一颗很大的星星，离地球很远。", "explanation": "这里应该用〈太阳〉。“太阳能”指能量，不是天体，不能说它是一颗星星。"}, {"text": "他把书放在太阳能上，怕被风吹走。", "explanation": "这里应该用〈桌子〉。“太阳能”指能量，不是可以放东西的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb06fdd9-08b5-4670-be89-e1f673d9f1c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26706, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个村子用三个太阳能发电。", "corrected_sentence": "这个村子用太阳能发电。", "error_description": "错误形式是“三个太阳能”，正确形式是“太阳能”。“太阳能”指能量，是不可数的，不能用“三个”来数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb06fdd9-08b5-4670-be89-e1f673d9f1c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26706, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这盏路灯向太阳能供电。", "corrected_sentence": "这盏路灯靠太阳能供电。", "error_description": "错误形式是“向太阳能供电”，正确形式是“靠太阳能供电”。表示凭借、依靠的介词应用“靠”；“向”表示方向或对象，不能用来说明供电的能源。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb06fdd9-08b5-4670-be89-e1f673d9f1c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
