INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26708, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "想出就是脑子里出现一个新的主意。", "primary_collocate": null, "pronunciation": "xiǎng chū", "ipa": "ɕiɑŋ˨˩˦ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "我想出了一个新主意。", "target_word": "想出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她突然想出一个好名字。", "target_word": "想出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你快想出一个办法吧。", "target_word": "想出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想出了新的玩法。", "target_word": "想出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子想出一个问题问老师。", "target_word": "想出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们想出了一个新游戏。", "target_word": "想出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你想出什么好主意了？", "target_word": "想出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈想出一个办法，让我早点儿起床。", "target_word": "想出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坐在那里，想出了一个新办法。", "target_word": "想出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们想出了很多新点子。", "target_word": "想出", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "想出了", "label": "体标"}, {"form": "想出过", "label": "体标"}, {"form": "想不出", "label": "复合"}, {"form": "想得出", "label": "复合"}], "register": "中性", "sense_fingerprint": "脑子里出现一个新主意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7182c7ee-be87-4d6c-bc52-b70eaa74ce89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26708, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "想出", "is_correct": true, "explanation": "正确答案：想出（xiǎng chū），指脑子里出现一个新主意。"}, {"text": "现出", "is_correct": false, "explanation": "xiàn 与 xiǎng 的韵尾 n 与 ng 不同，且声调不同，意思是呈现出来。"}, {"text": "选出", "is_correct": false, "explanation": "xuǎn 与 xiǎng 声母相同、声调相同，韵母不同（uan 与 iang），意思是挑选出来。"}, {"text": "相处", "is_correct": false, "explanation": "xiāng chǔ 与 xiǎng chū 两个音节的声调都不同，意思是彼此交往。"}], "explanations": {"想出": "正确答案：想出（xiǎng chū），指脑子里出现一个新主意。", "现出": "xiàn 与 xiǎng 的韵尾 n 与 ng 不同，且声调不同，意思是呈现出来。", "选出": "xuǎn 与 xiǎng 声母相同、声调相同，韵母不同（uan 与 iang），意思是挑选出来。", "相处": "xiāng chǔ 与 xiǎng chū 两个音节的声调都不同，意思是彼此交往。"}, "sentence_index": null, "correct_answer": "想出"}, "level_3": {"options": [{"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是液体，不能接“主意”作宾语。"}, {"text": "想出", "is_correct": true, "explanation": "正确：想出，表示脑子里出现一个新主意，与“一个新主意”搭配。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不接“主意”作宾语，与“新主意”不搭。"}, {"text": "穿", "is_correct": false, "explanation": "语义：主意是抽象的，不能被穿戴，与“新主意”的语义矛盾。"}], "explanations": {"喝": "搭配：“喝”的对象是液体，不能接“主意”作宾语。", "想出": "正确：想出，表示脑子里出现一个新主意，与“一个新主意”搭配。", "吃": "搭配：“吃”不接“主意”作宾语，与“新主意”不搭。", "穿": "语义：主意是抽象的，不能被穿戴，与“新主意”的语义矛盾。"}, "sentence_index": 0, "correct_answer": "想出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶突然想出了小时候的一位朋友。", "explanation": "这里应该用〈想起〉。想出指脑子里产生新的想法，回忆过去的人要用“想起”。"}, {"text": "他想出了桌上的那杯水，端起来喝了。", "explanation": "这里应该用〈看见〉。想出指产生想法，看到实物要用“看见”，不能用“想出”。"}, {"text": "我刚才想出了一阵敲门声。", "explanation": "这里应该用〈听到〉。想出指产生想法，听到声音要用“听到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d57181f-830c-4e91-ae6e-299736af61ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26708, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "显出", "is_correct": false, "explanation": "xiǎn 与 xiǎng 韵母不同（an 与 ang），声调相同，意思是显露出来。"}, {"text": "想出", "is_correct": true, "explanation": "正确答案：想出（xiǎng chū），指脑子里出现一个新主意。"}, {"text": "讲出", "is_correct": false, "explanation": "声母 j 与 x 不同，jiǎng 与 xiǎng 声调相同，意思是说出来。"}, {"text": "省出", "is_correct": false, "explanation": "xǐng 与 xiǎng 韵母不同（ing 与 iang），声调相同，意思是节省出来。"}], "explanations": {"显出": "xiǎn 与 xiǎng 韵母不同（an 与 ang），声调相同，意思是显露出来。", "想出": "正确答案：想出（xiǎng chū），指脑子里出现一个新主意。", "讲出": "声母 j 与 x 不同，jiǎng 与 xiǎng 声调相同，意思是说出来。", "省出": "xǐng 与 xiǎng 韵母不同（ing 与 iang），声调相同，意思是节省出来。"}, "sentence_index": null, "correct_answer": "想出"}, "level_3": {"options": [{"text": "摘", "is_correct": false, "explanation": "搭配：“摘”的对象多为果实等植物，不接“主意”作宾语。"}, {"text": "想出", "is_correct": true, "explanation": "正确：想出，表示脑子里出现一个主意，与“好主意”搭配。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是液体，不能接“主意”作宾语。"}, {"text": "踢", "is_correct": false, "explanation": "语义：主意是抽象的，不能被“踢”，与“什么好主意”的语义矛盾。"}], "explanations": {"摘": "搭配：“摘”的对象多为果实等植物，不接“主意”作宾语。", "想出": "正确：想出，表示脑子里出现一个主意，与“好主意”搭配。", "喝": "搭配：“喝”的对象是液体，不能接“主意”作宾语。", "踢": "语义：主意是抽象的，不能被“踢”，与“什么好主意”的语义矛盾。"}, "sentence_index": 6, "correct_answer": "想出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "操场上，他想出了一群孩子。", "explanation": "这里应该用〈看见〉。想出指脑子里产生想法，看到人或群体要用“看见”。"}, {"text": "他想出了门口那棵大树，又走回了屋里。", "explanation": "这里应该用〈看见〉。想出指产生想法，看到实物要用“看见”，不能用“想出”。"}, {"text": "昨天我想出了一封信。", "explanation": "这里应该用〈收到〉。想出指产生想法，收到信件要用“收到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d57181f-830c-4e91-ae6e-299736af61ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26708, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一下子就想得出了一个新办法。", "corrected_sentence": "他一下子就想出了一个新办法。", "error_description": "“想得出”表示有能力想出，不能再加“了”表示完成。错误在“想得出了”，应改为“想出了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d57181f-830c-4e91-ae6e-299736af61ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26708, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家想出着一个新游戏。", "corrected_sentence": "大家想出了一个新游戏。", "error_description": "“想出”表示思考后得出结果，已经完成，应用“了”；“着”表示状态持续，不能与“想出”搭配。错误在“着”，正确说法是“想出了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d57181f-830c-4e91-ae6e-299736af61ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
