INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26710, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "太阳的光照在东西上，让东西变热。", "primary_collocate": null, "pronunciation": "shài", "ipa": "ʂai˥˩", "syllable_count": 1, "sentences": [{"text": "太阳晒得我的头很热。", "target_word": "晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中午的太阳很大，晒得地面发烫。", "target_word": "晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天在海边，太阳晒得人受不了。", "target_word": "晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在太阳下站了很久，背都晒红了。", "target_word": "晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车停在外面，太阳晒着，里面很热。", "target_word": "晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石头晒了一天，摸起来很热。", "target_word": "晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别在太阳底下站着，晒得头疼。", "target_word": "晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳晒着屋顶，房间里越来越热。", "target_word": "晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天太阳真大，晒得我不想出门。", "target_word": "晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙子晒了一上午，脚踩上去很烫。", "target_word": "晒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "晒了", "label": "体标"}, {"form": "晒着", "label": "体标"}, {"form": "晒红", "label": "复合"}, {"form": "曬", "label": "繁体"}], "register": "中性", "sense_fingerprint": "太阳光照在身上或物体上使其发热", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7182c7ee-be87-4d6c-bc52-b70eaa74ce89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26710, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "晒", "is_correct": true, "explanation": "正确答案。晒 shài，意思是太阳光照在东西上使其变热。"}, {"text": "赛", "is_correct": false, "explanation": "sài（第四声）与 shài 声母不同（s 与 sh），意思是比赛。"}, {"text": "债", "is_correct": false, "explanation": "zhài（第四声）与 shài 声母不同（zh 与 sh），意思是债务。"}, {"text": "哨", "is_correct": false, "explanation": "shào（第四声）与 shài 韵母不同（ao 与 ai），意思是哨子。"}, {"text": "筛", "is_correct": false, "explanation": "shāi（第一声）与 shài（第四声）声调不同，意思是筛子。"}], "explanations": {"晒": "正确答案。晒 shài，意思是太阳光照在东西上使其变热。", "赛": "sài（第四声）与 shài 声母不同（s 与 sh），意思是比赛。", "债": "zhài（第四声）与 shài 声母不同（zh 与 sh），意思是债务。", "哨": "shào（第四声）与 shài 韵母不同（ao 与 ai），意思是哨子。", "筛": "shāi（第一声）与 shài（第四声）声调不同，意思是筛子。"}, "sentence_index": null, "correct_answer": "晒"}, "level_3": {"options": [{"text": "晒", "is_correct": true, "explanation": "正确。晒指太阳光照使人或物发热，与“头很热”相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：太阳不会唱歌，“太阳唱得我的头很热”不成立。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“太阳”搭配表示使人发热，“太阳吃得”不通。"}, {"text": "说", "is_correct": false, "explanation": "语义：太阳不会说话，说不出使人头热的结果。"}], "explanations": {"晒": "正确。晒指太阳光照使人或物发热，与“头很热”相符。", "唱": "语义：太阳不会唱歌，“太阳唱得我的头很热”不成立。", "吃": "搭配：“吃”不能与“太阳”搭配表示使人发热，“太阳吃得”不通。", "说": "语义：太阳不会说话，说不出使人头热的结果。"}, "sentence_index": 0, "correct_answer": "晒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在火炉旁边站了很久，背都晒红了。", "explanation": "这里应该用〈烤〉。晒的热源是太阳光，火炉的热使人发红要用烤。"}, {"text": "热水让我的手晒红了。", "explanation": "这里应该用〈烫〉。热水的热使手变红要用烫，晒指太阳光照。"}, {"text": "把鸡蛋放进热水里晒熟了。", "explanation": "这里应该用〈煮〉。鸡蛋是用热水煮熟的，不是靠阳光晒熟的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d57181f-830c-4e91-ae6e-299736af61ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26710, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "晒", "is_correct": true, "explanation": "正确答案。晒 shài，意思是太阳光照在东西上使其变热。"}, {"text": "沙", "is_correct": false, "explanation": "shā（第一声）与 shài（第四声）声调不同，韵母也不同（a 与 ai），意思是沙子。"}, {"text": "傻", "is_correct": false, "explanation": "shǎ（第三声）与 shài（第四声）声调不同，韵母也不同（a 与 ai），意思是愚笨。"}, {"text": "社", "is_correct": false, "explanation": "shè（第四声）与 shài 韵母不同（e 与 ai），意思是社会。"}, {"text": "善", "is_correct": false, "explanation": "shàn（第四声）与 shài 韵母不同（an 与 ai），意思是善良。"}], "explanations": {"晒": "正确答案。晒 shài，意思是太阳光照在东西上使其变热。", "沙": "shā（第一声）与 shài（第四声）声调不同，韵母也不同（a 与 ai），意思是沙子。", "傻": "shǎ（第三声）与 shài（第四声）声调不同，韵母也不同（a 与 ai），意思是愚笨。", "社": "shè（第四声）与 shài 韵母不同（e 与 ai），意思是社会。", "善": "shàn（第四声）与 shài 韵母不同（an 与 ai），意思是善良。"}, "sentence_index": null, "correct_answer": "晒"}, "level_3": {"options": [{"text": "晒", "is_correct": true, "explanation": "正确。晒得头疼指太阳光照使人难受，与“站着”的语境相合。"}, {"text": "淋", "is_correct": false, "explanation": "搭配：“淋”说水浇落在身上，不说太阳“淋得头疼”。"}, {"text": "冻", "is_correct": false, "explanation": "语义：“冻”指寒冷，与“在太阳底下”的语境矛盾。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”指用水清洁，不会“洗得头疼”，与“太阳底下”不合。"}], "explanations": {"晒": "正确。晒得头疼指太阳光照使人难受，与“站着”的语境相合。", "淋": "搭配：“淋”说水浇落在身上，不说太阳“淋得头疼”。", "冻": "语义：“冻”指寒冷，与“在太阳底下”的语境矛盾。", "洗": "语义：“洗”指用水清洁，不会“洗得头疼”，与“太阳底下”不合。"}, "sentence_index": 6, "correct_answer": "晒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电热毯晒得床铺很热。", "explanation": "这里应该用〈烘〉。电热毯靠电加热使床铺变热要用烘，晒的热源是太阳光。"}, {"text": "用电炉晒得水很快就开了。", "explanation": "这里应该用〈烧〉。电炉加热使水开要用烧，晒的热源是太阳光。"}, {"text": "篝火晒得我眼睛很疼。", "explanation": "这里应该用〈熏〉。篝火的烟使眼睛难受要用“熏”，晒的热源是太阳光。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d57181f-830c-4e91-ae6e-299736af61ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26710, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下午的太阳晒了窗台很热。", "corrected_sentence": "下午的太阳晒得窗台很热。", "error_description": "错误：“晒”后接表示程度的补语“很热”时须用“晒得”连接；“晒了窗台很热”不通，应改为“晒得窗台很热”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d57181f-830c-4e91-ae6e-299736af61ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26710, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "沙滩上的石头晒很烫。", "corrected_sentence": "沙滩上的石头晒得很烫。", "error_description": "错误：“晒”后面接状态补语“很烫”，中间要用“得”连接，不能省略。应说“晒得很烫”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d57181f-830c-4e91-ae6e-299736af61ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
