INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26712, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "电是一种能量，能让灯亮、电器工作。", "primary_collocate": null, "pronunciation": "diàn", "ipa": "tjɛn˥˩", "syllable_count": 1, "sentences": [{"text": "手机没电了，我不能听歌。", "target_word": "电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电是一种能量，可以让灯亮。", "target_word": "电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里没有电，晚上很黑。", "target_word": "电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条线里有电，小孩不要摸。", "target_word": "电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天我们家用的电很多。", "target_word": "电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有电，空调就不能工作。", "target_word": "电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电来了，所有的灯都亮了。", "target_word": "电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车用电，不用油。", "target_word": "电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的小房子没有电，晚上只能点蜡烛。", "target_word": "电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间的灯不亮，可能是没有电了。", "target_word": "电", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "电灯", "label": "复合"}, {"form": "電", "label": "繁体"}], "register": "中性", "sense_fingerprint": "电：能让灯亮、让电器工作的能量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '464d8e31-3b58-4903-948d-c22c693dcaf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26712, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "电", "is_correct": true, "explanation": "diàn（第四声）是本词，意思是能量，能让灯亮、让电器工作。"}, {"text": "点", "is_correct": false, "explanation": "diǎn（第三声）与 diàn（第四声）声调不同，意思是点。"}, {"text": "念", "is_correct": false, "explanation": "niàn 与 diàn 声母不同（n 与 d），意思是读。"}, {"text": "变", "is_correct": false, "explanation": "biàn 与 diàn 声母不同（b 与 d），意思是变化。"}, {"text": "掉", "is_correct": false, "explanation": "diào 与 diàn 韵母不同（iao 与 ian），意思是掉落。"}], "explanations": {"电": "diàn（第四声）是本词，意思是能量，能让灯亮、让电器工作。", "点": "diǎn（第三声）与 diàn（第四声）声调不同，意思是点。", "念": "niàn 与 diàn 声母不同（n 与 d），意思是读。", "变": "biàn 与 diàn 声母不同（b 与 d），意思是变化。", "掉": "diào 与 diàn 韵母不同（iao 与 ian），意思是掉落。"}, "sentence_index": null, "correct_answer": "电"}, "level_3": {"options": [{"text": "电", "is_correct": true, "explanation": "电：能量，手机没有电了，所以不能听歌。"}, {"text": "油", "is_correct": false, "explanation": "搭配：油用于汽车等机器，不说手机没油。"}, {"text": "饭", "is_correct": false, "explanation": "语义：饭是食物，“手机没饭了”与句意不通。"}, {"text": "车", "is_correct": false, "explanation": "语义：车是交通工具，手机不会“没车了”。"}], "explanations": {"电": "电：能量，手机没有电了，所以不能听歌。", "油": "搭配：油用于汽车等机器，不说手机没油。", "饭": "语义：饭是食物，“手机没饭了”与句意不通。", "车": "语义：车是交通工具，手机不会“没车了”。"}, "sentence_index": 0, "correct_answer": "电"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "煤是一种电。", "explanation": "这里应该用〈能源〉。煤是能源，电是能源的一种形式，不能说煤是电。"}, {"text": "这个月我们家用了一个电。", "explanation": "这里应该用〈度〉。电用“度”计量，要说“一度电”，不说“一个电”。"}, {"text": "这碗面的电很高，吃多了容易胖。", "explanation": "这里应该用〈热量〉。食物含的能量叫热量，不能说“电很高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9bc37fe-d124-4688-95fc-05c5e1d76589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26712, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "电", "is_correct": true, "explanation": "diàn（第四声）是本词，意思是能量。"}, {"text": "颠", "is_correct": false, "explanation": "diān（第一声）与 diàn（第四声）声调不同，意思是颠倒。"}, {"text": "便", "is_correct": false, "explanation": "biàn 与 diàn 声母不同（b 与 d），意思是方便。"}, {"text": "调", "is_correct": false, "explanation": "调（diào）与 diàn 韵母不同（iao 与 ian），意思是调查。"}], "explanations": {"电": "diàn（第四声）是本词，意思是能量。", "颠": "diān（第一声）与 diàn（第四声）声调不同，意思是颠倒。", "便": "biàn 与 diàn 声母不同（b 与 d），意思是方便。", "调": "调（diào）与 diàn 韵母不同（iao 与 ian），意思是调查。"}, "sentence_index": null, "correct_answer": "电"}, "level_3": {"options": [{"text": "电", "is_correct": true, "explanation": "电：能量，电来了，灯才能亮。"}, {"text": "水", "is_correct": false, "explanation": "语义：水不能让灯亮，灯亮要靠电。"}, {"text": "报", "is_correct": false, "explanation": "语义：报纸来了与灯亮没有关系，句意不通。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不能让灯亮，“书来了，所有的灯都亮了”句意不通。"}], "explanations": {"电": "电：能量，电来了，灯才能亮。", "水": "语义：水不能让灯亮，灯亮要靠电。", "报": "语义：报纸来了与灯亮没有关系，句意不通。", "书": "语义：书不能让灯亮，“书来了，所有的灯都亮了”句意不通。"}, "sentence_index": 6, "correct_answer": "电"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "月亮发出的电很柔和。", "explanation": "这里应该用〈光〉。电是能量，不会发出柔和的光，说月光要用“光”。"}, {"text": "他有很大的电，一个人能搬动那个箱子。", "explanation": "这里应该用〈力气〉。人的力量要用“力气”，电是能量形式，不能说人有很大的电。"}, {"text": "这间屋子的电很暖和。", "explanation": "这里应该用〈温度〉。电本身没有冷热，屋子暖和与否要说“温度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9bc37fe-d124-4688-95fc-05c5e1d76589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26712, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个月我们家用了五个电。", "corrected_sentence": "这个月我们家用了五度电。", "error_description": "量词错误：电要用“度”计量。应说“五度电”，不说“五个电”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9bc37fe-d124-4688-95fc-05c5e1d76589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26712, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小镇晚上不有电。", "corrected_sentence": "这个小镇晚上没有电。", "error_description": "否定词错误：表示“没有电”要用“没有”，不能用“不有”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9bc37fe-d124-4688-95fc-05c5e1d76589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
