INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26714, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "表示很久以前的时间，比如很久很久之前。", "primary_collocate": null, "pronunciation": "hěn zǎo yǐ qián", "ipa": "xən²¹⁴ tsɑʊ²¹⁴ i²¹⁴ tɕʰjɛn³⁵", "syllable_count": 4, "sentences": [{"text": "很早以前，这里住着猛犸象。", "target_word": "很早以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很早以前，这里是一片大海。", "target_word": "很早以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很早以前就想去北京。", "target_word": "很早以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很早以前，妈妈在小学当老师。", "target_word": "很早以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事我很早以前就知道了。", "target_word": "很早以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很早以前，有一个国王住在这里。", "target_word": "很早以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很早以前，恐龙统治过地球。", "target_word": "很早以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很早以前养过一只小狗。", "target_word": "很早以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很早以前我们是邻居，现在不是了。", "target_word": "很早以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那是很早以前的事了，我已经忘了。", "target_word": "很早以前", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "表示很久很久以前的时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '307c6c66-553a-4fd1-84cf-1f43674cbdfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26714, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "很早以前", "is_correct": true, "explanation": "正确。“很早以前”表示很久以前，与“这里住着猛犸象”所描述的远古情形相符。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指将来，与猛犸象生活在远古的时代不符。"}, {"text": "下个月", "is_correct": false, "explanation": "语义：“下个月”指近期将来，与句中久远的时间背景不符。"}, {"text": "上周", "is_correct": false, "explanation": "语义：“上周”指近期，与猛犸象生活在远古的时代不符。"}], "explanations": {"很早以前": "正确。“很早以前”表示很久以前，与“这里住着猛犸象”所描述的远古情形相符。", "明天": "语义：“明天”指将来，与猛犸象生活在远古的时代不符。", "下个月": "语义：“下个月”指近期将来，与句中久远的时间背景不符。", "上周": "语义：“上周”指近期，与猛犸象生活在远古的时代不符。"}, "sentence_index": 0, "correct_answer": "很早以前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今天很早以前就回家了。", "explanation": "这里应该用〈早早〉。“很早以前”指久远的过去，不能和“今天”连用；说今天的早，要用“早早”。"}, {"text": "这次比赛我很早以前就赢了。", "explanation": "这里应该用〈刚刚〉。“很早以前”指久远的过去，不能指刚结束的比赛；说不久前的事，要用“刚刚”。"}, {"text": "我明天很早以前就出发。", "explanation": "这里应该用〈清晨〉。“很早以前”指过去，不能用于明天；说明天的早晨，要用“清晨”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503fd71d-248c-491d-8c92-75285f88227a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26714, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "很早以前", "is_correct": true, "explanation": "正确。“很早以前”表示很久以前，与“恐龙统治过地球”的远古背景相符。"}, {"text": "下周", "is_correct": false, "explanation": "语义：“下周”指近期将来，与远古的经历不符，且“过”不用于将来的事。"}, {"text": "今晚", "is_correct": false, "explanation": "搭配：“今晚”指当天夜里，不能用来概括这种长时段的历史状况。"}, {"text": "以后", "is_correct": false, "explanation": "语义：“以后”指今后，与句中已经过去的时代不符。"}], "explanations": {"很早以前": "正确。“很早以前”表示很久以前，与“恐龙统治过地球”的远古背景相符。", "下周": "语义：“下周”指近期将来，与远古的经历不符，且“过”不用于将来的事。", "今晚": "搭配：“今晚”指当天夜里，不能用来概括这种长时段的历史状况。", "以后": "语义：“以后”指今后，与句中已经过去的时代不符。"}, "sentence_index": 6, "correct_answer": "很早以前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "很早以前，我们明年要去旅行。", "explanation": "这里应该去掉“很早以前”，或改用〈以后〉。“很早以前”指久远的过去，不能和“明年要”这样的将来安排连用。"}, {"text": "他很早以前一直在这家店干到今天。", "explanation": "这里应该用〈从〉。“很早以前”是一个时间点，不能直接接“一直……到今天”这样的时间段；要说“从很早以前”。"}, {"text": "这件作业我会在很早以前做完。", "explanation": "这里应该用〈明天〉。“很早以前”指过去，不能用于将来才要做的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503fd71d-248c-491d-8c92-75285f88227a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26714, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们很早以前了住在这个村子里。", "corrected_sentence": "他们很早以前住在这个村子里。", "error_description": "错误在于“了”：它被放在时间词“很早以前”之后、动词“住”之前，不合语法；应删去“了”，说“他们很早以前住在这个村子里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503fd71d-248c-491d-8c92-75285f88227a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26714, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座桥是很早以前的建的。", "corrected_sentence": "这座桥是很早以前建的。", "error_description": "错误在于多出的“的”：“以前”与“建”之间插入“的”，“很早以前的建的”结构不通；“是……的”句式中只需说“这座桥是很早以前建的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503fd71d-248c-491d-8c92-75285f88227a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
