INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26716, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让空气变脏。", "primary_collocate": null, "pronunciation": "wū rǎn kōng qì", "ipa": "u˥ ɻan˨˩˦ kʰʊŋ˥ tɕʰi˥˩", "syllable_count": 4, "sentences": [{"text": "汽车会污染空气。", "target_word": "污染空气", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工厂的黑烟污染空气。", "target_word": "污染空气", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这些旧车跑起来会污染空气。", "target_word": "污染空气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "烧煤取暖会污染空气，对身体也不好。", "target_word": "污染空气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市里汽车太多，会污染空气。", "target_word": "污染空气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们不让工厂再污染空气。", "target_word": "污染空气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "放烟花很漂亮，但是也会污染空气。", "target_word": "污染空气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了不污染空气，我每天骑自行车上班。", "target_word": "污染空气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂污染空气，附近的人都很生气。", "target_word": "污染空气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多人用电动车，因为电动车不会污染空气。", "target_word": "污染空气", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "使空气变脏；造成大气污染", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b2333-0eb6-4215-84dd-38c7b4eb1246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26716, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "污染空气", "is_correct": true, "explanation": "正确答案。“汽车会污染空气”指汽车排放的废气使空气变脏。"}, {"text": "修理空气", "is_correct": false, "explanation": "搭配：“修理”的对象是机器或物件，“空气”不能修理。"}, {"text": "装饰空气", "is_correct": false, "explanation": "语义：装饰是为了美化物体，汽车不会“装饰空气”，句意不通。"}, {"text": "打扫空气", "is_correct": false, "explanation": "搭配：“打扫”的对象是地面或房间，不能用于“空气”。"}], "explanations": {"污染空气": "正确答案。“汽车会污染空气”指汽车排放的废气使空气变脏。", "修理空气": "搭配：“修理”的对象是机器或物件，“空气”不能修理。", "装饰空气": "语义：装饰是为了美化物体，汽车不会“装饰空气”，句意不通。", "打扫空气": "搭配：“打扫”的对象是地面或房间，不能用于“空气”。"}, "sentence_index": 0, "correct_answer": "污染空气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂排出的废水污染空气。", "explanation": "这里应该用〈污染水源〉。废水污染的是水体，“污染空气”指烟尘、废气使空气变脏，不能用于废水。"}, {"text": "工厂的机器噪音很大，污染空气。", "explanation": "这里应该用〈噪音污染〉。噪音污染的是声音环境，不说“污染空气”。"}, {"text": "化学药品渗进地下，污染空气，庄稼都长不好了。", "explanation": "这里应该用〈污染土壤〉。渗进地下的药品污染的是土地，不是空气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26716, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "污染空气", "is_correct": true, "explanation": "正确答案。“放烟花也会污染空气”指烟花燃放后产生的烟尘使空气变脏。"}, {"text": "预习功课", "is_correct": false, "explanation": "语义：放烟花不会“预习功课”，句意不通。"}, {"text": "写作文", "is_correct": false, "explanation": "语义：放烟花与“写作文”没有关系，句意不通。"}, {"text": "修剪草坪", "is_correct": false, "explanation": "搭配：“修剪草坪”是园艺动作，不能作为放烟花的后果。"}], "explanations": {"污染空气": "正确答案。“放烟花也会污染空气”指烟花燃放后产生的烟尘使空气变脏。", "预习功课": "语义：放烟花不会“预习功课”，句意不通。", "写作文": "语义：放烟花与“写作文”没有关系，句意不通。", "修剪草坪": "搭配：“修剪草坪”是园艺动作，不能作为放烟花的后果。"}, "sentence_index": 6, "correct_answer": "污染空气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子在墙上乱画，污染空气。", "explanation": "这里应该用〈弄脏〉。乱画弄脏的是墙，「污染空气」不能用于墙。"}, {"text": "把垃圾扔进河里，会污染空气。", "explanation": "这里应该用〈污染河水〉。垃圾扔进河里污染的是水，不是空气。"}, {"text": "他吃饭时把衣服弄得很脏，污染空气了。", "explanation": "这里应该用〈弄脏衣服〉。衣服变脏不是空气变脏，不能说「污染空气」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26716, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家化工厂整天被污染空气。", "corrected_sentence": "这家化工厂整天污染空气。", "error_description": "被字句错误：“污染空气”中“空气”是宾语，不能在动词前加“被”。去掉“被”，应说“这家化工厂整天污染空气”；若要用“被”，应把“空气”提到主语位置，说“空气整天被这家化工厂污染”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26716, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些旧车会能污染空气。", "corrected_sentence": "这些旧车能污染空气。", "error_description": "助动词错误：“能”与“会”不能叠用，应只用其中一个，改为“能污染空气”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
