INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26718, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "每天要做的事情。", "primary_collocate": null, "pronunciation": "rì cháng shēng huó", "ipa": "ɻɻ̩˥˩ ʈʂʰɑŋ˧˥ ʂɤŋ˥ xuɔ˧˥", "syllable_count": 4, "sentences": [{"text": "我的日常生活是上班、吃饭、睡觉。", "target_word": "日常生活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈每天做饭洗衣，日常生活很忙。", "target_word": "日常生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学会做饭是日常生活的一件小事。", "target_word": "日常生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的日常生活要有人照顾。", "target_word": "日常生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在小村子里，日常生活很安静。", "target_word": "日常生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢拍下日常生活里的小故事。", "target_word": "日常生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日常生活中，多喝水对身体好。", "target_word": "日常生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想改变日常生活，每天早点起床。", "target_word": "日常生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学好汉语，日常生活就方便多了。", "target_word": "日常生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "放假的时候，我的日常生活很自由。", "target_word": "日常生活", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "日常生活：每天要做的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71266d48-abd2-408d-ab3d-49d9cf61150e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26718, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "日常生活", "is_correct": true, "explanation": "正确。上班、吃饭、睡觉是每天要做的事，所以是“日常生活”。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“工资”是劳动报酬，“我的工资是上班、吃饭、睡觉”说不通。"}, {"text": "假期", "is_correct": false, "explanation": "语义：假期是休息的时间，与“上班”相反，句子前后矛盾。"}, {"text": "作业", "is_correct": false, "explanation": "语义：上班、吃饭、睡觉不是学习任务，“作业”与句意不符。"}], "explanations": {"日常生活": "正确。上班、吃饭、睡觉是每天要做的事，所以是“日常生活”。", "工资": "搭配：“工资”是劳动报酬，“我的工资是上班、吃饭、睡觉”说不通。", "假期": "语义：假期是休息的时间，与“上班”相反，句子前后矛盾。", "作业": "语义：上班、吃饭、睡觉不是学习任务，“作业”与句意不符。"}, "sentence_index": 0, "correct_answer": "日常生活"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去药店买了一批日常生活。", "explanation": "这里应该用〈用品〉。〈日常生活〉是抽象的生活过程，不能买，应说“日常用品”。"}, {"text": "这次班级组织了一场日常生活，大家一起去郊游。", "explanation": "这里应该用〈活动〉。〈日常生活〉指平时的生活本身，不是可以组织、举行的一场活动。"}, {"text": "这里有一座日常生活。", "explanation": "这里不应该用〈座〉。〈座〉用于山、楼房等大型固定的东西，〈日常生活〉不能这样计数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '028b14c4-f1a5-4baa-a2a4-afa5d77dbcb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26718, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日常生活", "is_correct": true, "explanation": "正确。“日常生活中”指平时每天的生活，多喝水是日常的好习惯。"}, {"text": "手术", "is_correct": false, "explanation": "语义：手术期间通常不能随便喝水，与“多喝水对身体好”的语境相反。"}, {"text": "麻醉", "is_correct": false, "explanation": "语义：麻醉期间身体处于昏迷状态，不能喝水，与句中建议矛盾。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：“月亮中”不是可以多喝水的场合，句意不通。"}], "explanations": {"日常生活": "正确。“日常生活中”指平时每天的生活，多喝水是日常的好习惯。", "手术": "语义：手术期间通常不能随便喝水，与“多喝水对身体好”的语境相反。", "麻醉": "语义：麻醉期间身体处于昏迷状态，不能喝水，与句中建议矛盾。", "月亮": "语义：“月亮中”不是可以多喝水的场合，句意不通。"}, "sentence_index": 6, "correct_answer": "日常生活"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他报名参加了一门日常生活。", "explanation": "这里应该用〈课程〉。〈日常生活〉不是可以报名的课程，〈门〉不能用来数它。"}, {"text": "他昨天参加了一场日常生活。", "explanation": "这里应该用〈比赛〉。〈日常生活〉是平时的生活，不是可以参加的比赛。"}, {"text": "公司完成了一项日常生活。", "explanation": "这里应该用〈项目〉。〈日常生活〉不是可以完成的项目，〈项〉用于项目、任务等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '028b14c4-f1a5-4baa-a2a4-afa5d77dbcb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26718, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的一个日常生活很规律。", "corrected_sentence": "我的日常生活很规律。", "error_description": "错误形式是“一个日常生活”，正确形式是“日常生活”。“日常生活”是抽象名词，不能用个体量词“一个”修饰，应直接说“我的日常生活很规律”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '028b14c4-f1a5-4baa-a2a4-afa5d77dbcb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26718, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学会开车，我地日常生活就方便多了。", "corrected_sentence": "学会开车，我的日常生活就方便多了。", "error_description": "错误形式是“我地日常生活”，正确形式是“我的日常生活”。修饰名词要用“的”，“地”用于修饰动词或形容词，这里不能用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '028b14c4-f1a5-4baa-a2a4-afa5d77dbcb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
