INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26722, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "风让东西动起来。", "primary_collocate": null, "pronunciation": "chuī dòng", "ipa": "tʂʰweɪ˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "风吹动门口的旗子，旗子飘起来了。", "target_word": "吹动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里风很大，吹动了窗外的树。", "target_word": "吹动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春风吹动湖面，水上出现一圈一圈的波纹。", "target_word": "吹动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的风吹动着她的长裙。", "target_word": "吹动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风吹动晾在外面的衣服，衣服来回地摆。", "target_word": "吹动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一阵风吹动了桌上的书，书页翻了起来。", "target_word": "吹动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们看着风吹动风筝，高兴地笑了。", "target_word": "吹动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风吹动帐篷，帐篷里的人都醒了。", "target_word": "吹动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋风吹动树叶，树叶落了一地。", "target_word": "吹动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门没关，风吹动了屋里的帘子。", "target_word": "吹动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "吹动了", "label": "体标"}, {"form": "吹动着", "label": "体标"}, {"form": "吹动过", "label": "体标"}], "register": "中性", "sense_fingerprint": "风让东西动起来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6dab98-14d7-4430-bd0f-b102915e1fde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26722, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "吹动", "is_correct": true, "explanation": "正确答案：吹动（chuī dòng），指风让东西动起来。"}, {"text": "推动", "is_correct": false, "explanation": "tuī（第一声）与 chuī（第一声）声母不同（t 与 ch），意思是用力使物体向前移动，不指风的作用。"}, {"text": "催动", "is_correct": false, "explanation": "cuī（第一声）与 chuī（第一声）声母不同（c 与 ch），意思是促使事物开始运转。"}, {"text": "出动", "is_correct": false, "explanation": "chū（第一声）与 chuī（第一声）韵母不同（少了 i 音），意思是派出人员或车辆行动。"}], "explanations": {"吹动": "正确答案：吹动（chuī dòng），指风让东西动起来。", "推动": "tuī（第一声）与 chuī（第一声）声母不同（t 与 ch），意思是用力使物体向前移动，不指风的作用。", "催动": "cuī（第一声）与 chuī（第一声）声母不同（c 与 ch），意思是促使事物开始运转。", "出动": "chū（第一声）与 chuī（第一声）韵母不同（少了 i 音），意思是派出人员或车辆行动。"}, "sentence_index": null, "correct_answer": "吹动"}, "level_3": {"options": [{"text": "吹动", "is_correct": true, "explanation": "正确：吹动表示风使旗子飘动，与“旗子飘起来了”一致。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”是使东西燃烧，风不能把旗子烧起来，与“飘起来”不符。"}, {"text": "挂", "is_correct": false, "explanation": "配价：“挂”要求人作施事，风不能挂旗子。"}, {"text": "扫", "is_correct": false, "explanation": "搭配：“扫”一般接地面、垃圾，不说扫旗子。"}], "explanations": {"吹动": "正确：吹动表示风使旗子飘动，与“旗子飘起来了”一致。", "烧": "语义：“烧”是使东西燃烧，风不能把旗子烧起来，与“飘起来”不符。", "挂": "配价：“挂”要求人作施事，风不能挂旗子。", "扫": "搭配：“扫”一般接地面、垃圾，不说扫旗子。"}, "sentence_index": 0, "correct_answer": "吹动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小鸟吹动翅膀，飞走了。", "explanation": "这里应该用〈拍动〉。吹动要靠风或气流，鸟振动翅膀要用拍动。"}, {"text": "工人吹动了那张大桌子。", "explanation": "这里应该用〈搬动〉。吹动要靠风或气流，人搬桌子要用搬动。"}, {"text": "他吹动了摇篮，孩子睡着了。", "explanation": "这里应该用〈摇动〉。吹动要靠风或气流，用手摇摇篮要用摇动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deebcdfc-2623-4b3b-a262-1127910088b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26722, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吹动", "is_correct": true, "explanation": "正确：吹动表示风使风筝飘动，正是孩子们看着的情形。"}, {"text": "打破", "is_correct": false, "explanation": "搭配：“打破”多接纪录、杯子，不说打破风筝。"}, {"text": "砸碎", "is_correct": false, "explanation": "搭配：“砸碎”多接玻璃、瓶子，不说砸碎风筝。"}, {"text": "染红", "is_correct": false, "explanation": "体貌：“染红”会改变风筝的颜色，风不能把风筝染红。"}], "explanations": {"吹动": "正确：吹动表示风使风筝飘动，正是孩子们看着的情形。", "打破": "搭配：“打破”多接纪录、杯子，不说打破风筝。", "砸碎": "搭配：“砸碎”多接玻璃、瓶子，不说砸碎风筝。", "染红": "体貌：“染红”会改变风筝的颜色，风不能把风筝染红。"}, "sentence_index": 6, "correct_answer": "吹动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她吹动手帕，向我们告别。", "explanation": "这里应该用〈挥动〉。吹动要靠风或气流，人挥手帕要用挥动。"}, {"text": "他吹动了那辆自行车，推着走了过去。", "explanation": "这里应该用〈推动〉。吹动要靠风或气流，人力推车要用推动。"}, {"text": "他用力吹动了车门，走了出去。", "explanation": "这里应该用〈拉动〉。吹动要靠风或气流，用力拉门要用拉动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deebcdfc-2623-4b3b-a262-1127910088b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26722, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "风吹动了着院子里的旗子。", "corrected_sentence": "风吹动着院子里的旗子。", "error_description": "动态助词错误：表示持续的“着”不能与“了”叠用，应为“风吹动着院子里的旗子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deebcdfc-2623-4b3b-a262-1127910088b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26722, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "风吹动了了窗户上的纸。", "corrected_sentence": "风吹动了窗户上的纸。", "error_description": "动态助词错误：“了”重复。“吹动了”之后不能再加“了”，应为“风吹动了窗户上的纸”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deebcdfc-2623-4b3b-a262-1127910088b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26726, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暗", "is_correct": true, "explanation": "暗与“亮”构成反义，指光线不足。"}, {"text": "快", "is_correct": false, "explanation": "快与“亮”不构成反义，快指速度高，与光线无关。"}, {"text": "重", "is_correct": false, "explanation": "重与“亮”不构成反义，重指分量大，与光线无关。"}, {"text": "软", "is_correct": false, "explanation": "软与“亮”不构成反义，软描述质地，与光线无关。"}], "correct_answer": "暗", "explanations": {"暗": "暗与“亮”构成反义，指光线不足。", "快": "快与“亮”不构成反义，快指速度高，与光线无关。", "重": "重与“亮”不构成反义，重指分量大，与光线无关。", "软": "软与“亮”不构成反义，软描述质地，与光线无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a02c1c-1fe0-454d-9433-88a422d90a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26726, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暗", "is_correct": true, "explanation": "暗与“亮”构成反义，指光线不足。"}, {"text": "慢", "is_correct": false, "explanation": "慢与“亮”不构成反义，慢指速度低，与光线无关。"}, {"text": "硬", "is_correct": false, "explanation": "硬与“亮”不构成反义，硬描述质地，与光线无关。"}, {"text": "厚", "is_correct": false, "explanation": "厚与“亮”不构成反义，厚描述物体的厚度，与光线无关。"}], "correct_answer": "暗", "explanations": {"暗": "暗与“亮”构成反义，指光线不足。", "慢": "慢与“亮”不构成反义，慢指速度低，与光线无关。", "硬": "硬与“亮”不构成反义，硬描述质地，与光线无关。", "厚": "厚与“亮”不构成反义，厚描述物体的厚度，与光线无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a02c1c-1fe0-454d-9433-88a422d90a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26726, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "亮就是光很强，让人能看清楚东西。", "primary_collocate": null, "pronunciation": "liàng", "ipa": "ljɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "今天的太阳很亮。", "target_word": "亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这盏灯太亮了，我睡不着。", "target_word": "亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今晚月光很亮。", "target_word": "亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手电筒的光很亮，能看清路。", "target_word": "亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的光不够亮，看不清字。", "target_word": "亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间不亮，请你开灯。", "target_word": "亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗边比较亮，我在那里看书。", "target_word": "亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室的灯很亮，同学们都能看清黑板。", "target_word": "亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的车灯很亮，照得我睁不开眼。", "target_word": "亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞台上的光特别亮。", "target_word": "亮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "亮了", "label": "体标"}, {"form": "亮着", "label": "体标"}, {"form": "明亮", "label": "复合"}], "register": "中性", "sense_fingerprint": "光很强、能看清东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb066d7-2d45-41ad-9000-ae004e838c44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26726, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "亮", "is_correct": true, "explanation": "这是正确答案：亮（liàng），指光很强、能看清东西。"}, {"text": "凉", "is_correct": false, "explanation": "liáng（第二声）与 liàng（第四声）声调不同，意思是凉。"}, {"text": "练", "is_correct": false, "explanation": "liàn 与 liàng 只差韵尾 n/ng，意思是练习。"}, {"text": "两", "is_correct": false, "explanation": "liǎng（第三声）与 liàng（第四声）声调不同，意思是两个。"}], "explanations": {"亮": "这是正确答案：亮（liàng），指光很强、能看清东西。", "凉": "liáng（第二声）与 liàng（第四声）声调不同，意思是凉。", "练": "liàn 与 liàng 只差韵尾 n/ng，意思是练习。", "两": "liǎng（第三声）与 liàng（第四声）声调不同，意思是两个。"}, "sentence_index": null, "correct_answer": "亮"}, "level_3": {"options": [{"text": "亮", "is_correct": true, "explanation": "正确：“今天的太阳很亮”指太阳的光很强，符合语境。"}, {"text": "甜", "is_correct": false, "explanation": "语义：太阳不能是甜的，“太阳很甜”说不通。"}, {"text": "响", "is_correct": false, "explanation": "搭配：“响”形容声音，不能用来形容太阳。"}, {"text": "硬", "is_correct": false, "explanation": "语义：太阳不是硬的，“太阳很硬”与句意不合。"}], "explanations": {"亮": "正确：“今天的太阳很亮”指太阳的光很强，符合语境。", "甜": "语义：太阳不能是甜的，“太阳很甜”说不通。", "响": "搭配：“响”形容声音，不能用来形容太阳。", "硬": "语义：太阳不是硬的，“太阳很硬”与句意不合。"}, "sentence_index": 0, "correct_answer": "亮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这根绳子太亮了，不够用。", "explanation": "这里应该用〈短〉。“亮”形容光，不能形容长短，绳子不够用要说“短”。"}, {"text": "这个西瓜很亮，大家都爱吃。", "explanation": "这里应该用〈甜〉。“亮”形容光，不能用来形容味道，西瓜的味道要用“甜”。"}, {"text": "这箱子很亮，我搬不动。", "explanation": "这里应该用〈重〉。“亮”不能形容重量，箱子的分量要用“重”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a02c1c-1fe0-454d-9433-88a422d90a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26726, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "亮", "is_correct": true, "explanation": "这是正确答案：亮（liàng），指光很强、能看清东西。"}, {"text": "粮", "is_correct": false, "explanation": "liáng（第二声）与 liàng（第四声）声调不同，意思是粮食。"}, {"text": "两", "is_correct": false, "explanation": "liǎng（第三声）与 liàng（第四声）声调不同，意思是两个。"}, {"text": "酿", "is_correct": false, "explanation": "niàng 与 liàng 声母 n/l 不同，意思是酿造。"}], "explanations": {"亮": "这是正确答案：亮（liàng），指光很强、能看清东西。", "粮": "liáng（第二声）与 liàng（第四声）声调不同，意思是粮食。", "两": "liǎng（第三声）与 liàng（第四声）声调不同，意思是两个。", "酿": "niàng 与 liàng 声母 n/l 不同，意思是酿造。"}, "sentence_index": null, "correct_answer": "亮"}, "level_3": {"options": [{"text": "亮", "is_correct": true, "explanation": "正确：“窗边比较亮”指那里光线较强，适合看书。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”用于人或动物的体形，窗边不能说“胖”。"}, {"text": "苦", "is_correct": false, "explanation": "语义：窗边不能是苦的，与看书的情境不合。"}, {"text": "饱", "is_correct": false, "explanation": "语义：窗边不会饱，“窗边比较饱”说不通。"}], "explanations": {"亮": "正确：“窗边比较亮”指那里光线较强，适合看书。", "胖": "体貌：“胖”用于人或动物的体形，窗边不能说“胖”。", "苦": "语义：窗边不能是苦的，与看书的情境不合。", "饱": "语义：窗边不会饱，“窗边比较饱”说不通。"}, "sentence_index": 6, "correct_answer": "亮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脚很亮，走不了路。", "explanation": "这里应该用〈痛〉。“亮”形容光，不能用来形容身体的感觉，脚疼要用“痛”。"}, {"text": "这段路程很亮，我们走了好久。", "explanation": "这里应该用〈远〉。“亮”不能形容距离，路程的长短要用“远”。"}, {"text": "这药很亮，孩子都不肯喝。", "explanation": "这里应该用〈苦〉。“亮”不能形容味道，药的味道要用“苦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a02c1c-1fe0-454d-9433-88a422d90a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26726, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窗户开着，屋里亮很。", "corrected_sentence": "窗户开着，屋里很亮。", "error_description": "程度修饰语语序错误：应为“很亮”，不能说“亮很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a02c1c-1fe0-454d-9433-88a422d90a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26726, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这盏灯比那盏灯很亮。", "corrected_sentence": "这盏灯比那盏灯亮。", "error_description": "错误：“比”字句中形容词前不能加“很”。正确：“这盏灯比那盏灯亮”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a02c1c-1fe0-454d-9433-88a422d90a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
