INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26730, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "空气动起来就是风，比如风吹动树叶。", "primary_collocate": null, "pronunciation": "fēng", "ipa": "fɤŋ˥", "syllable_count": 1, "sentences": [{"text": "今天的风很大。", "target_word": "风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风吹动了树叶。", "target_word": "风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面有风，你多穿一件衣服。", "target_word": "风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天晚上刮了一夜的风。", "target_word": "风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风停了，天也亮了。", "target_word": "风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗户开着，风从外面吹进来。", "target_word": "风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天的风很暖和。", "target_word": "风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的风带着一点咸味。", "target_word": "风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有风的日子，我喜欢到河边走走。", "target_word": "风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风太大，我的帽子吹到河里去了。", "target_word": "风", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一阵风", "label": "量词"}, {"form": "大风", "label": "复合"}, {"form": "風", "label": "繁体"}], "register": "中性", "sense_fingerprint": "流动的空气，自然现象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a7a008-8700-472e-9416-a17e42e54d73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26730, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "风", "is_correct": true, "explanation": "正确：风（fēng）指流动的空气。"}, {"text": "分", "is_correct": false, "explanation": "韵尾不同：fēn 以 n 结尾，fēng 以 ng 结尾，“分”的意思是分开。"}, {"text": "凤", "is_correct": false, "explanation": "声调不同：fèng（第四声）与 fēng（第一声），意思是凤凰。"}, {"text": "逢", "is_correct": false, "explanation": "声调不同：féng（第二声）与 fēng（第一声），意思是遇到。"}, {"text": "方", "is_correct": false, "explanation": "元音不同：fāng 的元音是 a，fēng 的元音是 e，意思是方形。"}], "explanations": {"风": "正确：风（fēng）指流动的空气。", "分": "韵尾不同：fēn 以 n 结尾，fēng 以 ng 结尾，“分”的意思是分开。", "凤": "声调不同：fèng（第四声）与 fēng（第一声），意思是凤凰。", "逢": "声调不同：féng（第二声）与 fēng（第一声），意思是遇到。", "方": "元音不同：fāng 的元音是 a，fēng 的元音是 e，意思是方形。"}, "sentence_index": null, "correct_answer": "风"}, "level_3": {"options": [{"text": "风", "is_correct": true, "explanation": "正确：“今天的风很大”中的“风”指流动的空气。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“很大”不修饰温度，应说“很高”。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“很大”不说价格，应说“很高”或“很贵”。"}, {"text": "历史", "is_correct": false, "explanation": "语义：“今天的”指当天，历史指过去的事，不能说“今天的历史”。"}], "explanations": {"风": "正确：“今天的风很大”中的“风”指流动的空气。", "温度": "搭配：“很大”不修饰温度，应说“很高”。", "价格": "搭配：“很大”不说价格，应说“很高”或“很贵”。", "历史": "语义：“今天的”指当天，历史指过去的事，不能说“今天的历史”。"}, "sentence_index": 0, "correct_answer": "风"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事的风很快就传开了。", "explanation": "这里应该用〈风声〉。“风”单用指流动的空气，表示消息、传闻要说“风声”。"}, {"text": "我们在山顶上拍了很多风。", "explanation": "这里应该用〈风景〉。风是看不见的气流，不能拍，应说“拍风景”。"}, {"text": "昨天晚上刮了一条风。", "explanation": "这里应该用〈阵〉。“条”用于细长的东西，风的量词多用“阵”或“股”，如“一阵风”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26730, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "风", "is_correct": true, "explanation": "正确：风（fēng）指流动的空气。"}, {"text": "崩", "is_correct": false, "explanation": "声母不同：bēng 的声母是 b，fēng 的声母是 f，意思是崩塌。"}, {"text": "灯", "is_correct": false, "explanation": "声母不同：dēng 的声母是 d，fēng 的声母是 f，意思是灯。"}, {"text": "烹", "is_correct": false, "explanation": "声母不同：pēng 的声母是 p，fēng 的声母是 f，意思是烹饪。"}, {"text": "缝", "is_correct": false, "explanation": "声调不同：fèng（第四声）与 fēng（第一声），意思是缝隙。"}], "explanations": {"风": "正确：风（fēng）指流动的空气。", "崩": "声母不同：bēng 的声母是 b，fēng 的声母是 f，意思是崩塌。", "灯": "声母不同：dēng 的声母是 d，fēng 的声母是 f，意思是灯。", "烹": "声母不同：pēng 的声母是 p，fēng 的声母是 f，意思是烹饪。", "缝": "声调不同：fèng（第四声）与 fēng（第一声），意思是缝隙。"}, "sentence_index": null, "correct_answer": "风"}, "level_3": {"options": [{"text": "风", "is_correct": true, "explanation": "正确：“春天的风很暖和”中的“风”指流动的空气。"}, {"text": "冰", "is_correct": false, "explanation": "语义：冰是冷的，与“很暖和”相矛盾。"}, {"text": "冬天", "is_correct": false, "explanation": "语义：“春天的”与“冬天”相矛盾，春天不是冬天。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“暖和”形容温度，不能修饰声音。"}], "explanations": {"风": "正确：“春天的风很暖和”中的“风”指流动的空气。", "冰": "语义：冰是冷的，与“很暖和”相矛盾。", "冬天": "语义：“春天的”与“冬天”相矛盾，春天不是冬天。", "声音": "搭配：“暖和”形容温度，不能修饰声音。"}, "sentence_index": 6, "correct_answer": "风"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个投资很有风，你要想清楚。", "explanation": "这里的“风”指风险。“风”单用不表示风险，应说“风险”，与“流动的空气”的“风”不同。"}, {"text": "这次考试的风很难，大家都考砸了。", "explanation": "这里应该用〈题目〉。“风”单用指流动的空气，不能用来说考试的难度，应说“题目很难”。"}, {"text": "这个人很有风，走到哪儿都很招人喜欢。", "explanation": "这里的“风”指风度、派头，与“流动的空气”的“风”不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26730, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "刚才吹过一个风，把门关上了。", "corrected_sentence": "刚才吹过一阵风，把门关上了。", "error_description": "量词错误：“风”前的量词“个”不合适，风多用“阵”或“股”，应说“一阵风”，不说“一个风”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26730, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "傍晚吹来一阵凉凉风，很舒服。", "corrected_sentence": "傍晚吹来一阵凉凉的风，很舒服。", "error_description": "结构助词错误：“凉凉”是重叠形容词，修饰“风”时要加“的”，应说“凉凉的风”，不说“凉凉风”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
