INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26732, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "电池板是能吸收太阳光并产生电的东西。", "primary_collocate": null, "pronunciation": "diàn chí bǎn", "ipa": "tjɛn˥˩ ʈʂʰɨ˧˥ pan˨˩˦", "syllable_count": 3, "sentences": [{"text": "屋顶上装了一块大电池板。", "target_word": "电池板", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块电池板能把阳光变成电。", "target_word": "电池板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电池板要放在太阳下面。", "target_word": "电池板", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨天，电池板发的电很少。", "target_word": "电池板", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸每个月都擦一次电池板。", "target_word": "电池板", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在山上放了很多电池板。", "target_word": "电池板", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电池板坏了，家里没有电。", "target_word": "电池板", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小电池板可以给手机充电。", "target_word": "电池板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电池板上有很多灰，要洗一洗。", "target_word": "电池板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的电池板是去年买的。", "target_word": "电池板", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块电池板", "label": "量词"}, {"form": "太阳能电池板", "label": "复合"}, {"form": "電池板", "label": "繁体"}], "register": "中性", "sense_fingerprint": "吸收阳光发电的板状装置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fb7fbe2-03dc-4c00-8c7e-e16f093b9f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26732, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不能装在屋顶上。"}, {"text": "电池板", "is_correct": true, "explanation": "正确：装在屋顶上、能把阳光变成电的板状装置，符合语境。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，不会装在屋顶上。"}, {"text": "地毯", "is_correct": false, "explanation": "语义：地毯铺在地面上，不会装在屋顶上。"}], "explanations": {"面包": "语义：面包是食物，不能装在屋顶上。", "电池板": "正确：装在屋顶上、能把阳光变成电的板状装置，符合语境。", "蛋糕": "语义：蛋糕是食物，不会装在屋顶上。", "地毯": "语义：地毯铺在地面上，不会装在屋顶上。"}, "sentence_index": 0, "correct_answer": "电池板"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的手表没电了，换了一块新电池板。", "explanation": "这里应该用〈电池〉。电池板是吸收阳光、把光变成电的板状装置，手表里换的是小型电池。"}, {"text": "妈妈用电池板炒了一盘菜。", "explanation": "这里应该用〈锅〉。炒菜要用锅；电池板只能把阳光变成电，不能用来做饭。"}, {"text": "天黑了，我打开电池板看书。", "explanation": "这里应该用〈台灯〉。晚上看书要开台灯照明；电池板是吸收阳光发电的装置，不会发光。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '523bc86b-7d76-4cbe-bed4-12eddf214c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26732, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水管", "is_correct": false, "explanation": "语义：水管坏了不会导致家里停电。"}, {"text": "电池板", "is_correct": true, "explanation": "正确：吸收阳光发电的装置，它坏了就会造成家里没电。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包坏了和家里停电没有关系。"}, {"text": "消息", "is_correct": false, "explanation": "搭配：“坏了”用于器物，消息应说“坏消息”，不说“消息坏了”。"}], "explanations": {"水管": "语义：水管坏了不会导致家里停电。", "电池板": "正确：吸收阳光发电的装置，它坏了就会造成家里没电。", "书包": "语义：书包坏了和家里停电没有关系。", "消息": "搭配：“坏了”用于器物，消息应说“坏消息”，不说“消息坏了”。"}, "sentence_index": 6, "correct_answer": "电池板"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块电池板插在插座上，就能给手机充电。", "explanation": "这里应该用〈充电器〉。充电器插在插座上为设备充电；电池板靠吸收阳光发电，不能插在插座上使用。"}, {"text": "这台电脑的电池板坏了，要换一个。", "explanation": "这里应该用〈电池〉。电脑的供电部件叫“电池”；电池板是户外吸收阳光的装置，不能装在电脑里。"}, {"text": "这块电池板能直接把一壶水烧开。", "explanation": "这里应该用〈电水壶〉。烧开水要用电水壶；电池板只能把阳光变成电，不能直接给水加热。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '523bc86b-7d76-4cbe-bed4-12eddf214c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26732, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈以前在房顶上安装过一只电池板。", "corrected_sentence": "妈妈以前在房顶上安装过一块电池板。", "error_description": "量词错误：电池板是片状的，量词应用“块”，不能用“只”；应说“一块电池板”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '523bc86b-7d76-4cbe-bed4-12eddf214c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26732, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爸爸把电池板擦很干净。", "corrected_sentence": "爸爸把电池板擦得很干净。", "error_description": "补语错误：说擦到什么程度要用“得”，应说“擦得很干净”，不能说“擦很干净”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '523bc86b-7d76-4cbe-bed4-12eddf214c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
