INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26740, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用东西擦来擦去。", "primary_collocate": null, "pronunciation": "mó", "ipa": "mwɔ˧˥", "syllable_count": 1, "sentences": [{"text": "新鞋太硬，走路时磨脚，脚很疼。", "target_word": "磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用砂纸把木头磨平了。", "target_word": "磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河里的石头被水磨得很光滑。", "target_word": "磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新鞋把我的脚后跟磨破了。", "target_word": "磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用砂纸在桌子上磨，想把旧漆磨掉。", "target_word": "磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "袖子天天在桌上磨，已经磨破了。", "target_word": "磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗在门上磨爪子，门上有很多印子。", "target_word": "磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把刀在石头上磨了几下，刀快了。", "target_word": "磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书包带太细，肩膀都磨红了。", "target_word": "磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣领太硬，一直磨着脖子。", "target_word": "磨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "磨了", "label": "体标"}, {"form": "磨着", "label": "体标"}, {"form": "磨过", "label": "体标"}, {"form": "磨破", "label": "复合"}], "register": "中性", "sense_fingerprint": "用东西来回擦", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6dab98-14d7-4430-bd0f-b102915e1fde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26740, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "磨", "is_correct": true, "explanation": "正确答案：磨（mó），指用东西来回擦。"}, {"text": "摸", "is_correct": false, "explanation": "mō（第一声）与 mó（第二声）声调不同，意思是用手轻触。"}, {"text": "墨", "is_correct": false, "explanation": "mò（第四声）与 mó（第二声）声调不同，意思是墨汁。"}, {"text": "婆", "is_correct": false, "explanation": "pó 与 mó 声母不同（p 与 m），意思是老年妇女。"}, {"text": "麻", "is_correct": false, "explanation": "má 与 mó 韵母不同（a 与 o），意思是麻类植物或麻木。"}], "explanations": {"磨": "正确答案：磨（mó），指用东西来回擦。", "摸": "mō（第一声）与 mó（第二声）声调不同，意思是用手轻触。", "墨": "mò（第四声）与 mó（第二声）声调不同，意思是墨汁。", "婆": "pó 与 mó 声母不同（p 与 m），意思是老年妇女。", "麻": "má 与 mó 韵母不同（a 与 o），意思是麻类植物或麻木。"}, "sentence_index": null, "correct_answer": "磨"}, "level_3": {"options": [{"text": "磨", "is_correct": true, "explanation": "正确：磨表示鞋子来回摩擦脚，引起疼痛，符合语境。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不与“脚”搭配，走路时“吃脚”不通，与“脚很疼”的语境无关。"}, {"text": "按", "is_correct": false, "explanation": "搭配：“按”一般指用手压，不说走路时按脚。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”一般接球、石头等，不说走路时踢脚。"}], "explanations": {"磨": "正确：磨表示鞋子来回摩擦脚，引起疼痛，符合语境。", "吃": "搭配：“吃”不与“脚”搭配，走路时“吃脚”不通，与“脚很疼”的语境无关。", "按": "搭配：“按”一般指用手压，不说走路时按脚。", "踢": "搭配：“踢”一般接球、石头等，不说走路时踢脚。"}, "sentence_index": 0, "correct_answer": "磨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他磨开了门，走了进去。", "explanation": "这里应该用〈推〉。磨是用东西来回擦动，推门要用推。"}, {"text": "他磨了一口苹果，很甜。", "explanation": "这里应该用〈咬〉。磨是用东西来回擦，吃苹果要用咬。"}, {"text": "医生磨住了伤口，止住了血。", "explanation": "这里应该用〈按〉。磨是来回摩擦，按住伤口要用按。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deebcdfc-2623-4b3b-a262-1127910088b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26740, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "磨", "is_correct": true, "explanation": "正确答案：磨（mó），指用东西来回擦。"}, {"text": "默", "is_correct": false, "explanation": "mò（第四声）与 mó（第二声）声调不同，意思是不出声。"}, {"text": "伯", "is_correct": false, "explanation": "bó 与 mó 声母不同（b 与 m），意思是伯父或父亲的哥哥。"}, {"text": "佛", "is_correct": false, "explanation": "fó 与 mó 声母不同（f 与 m），意思是佛陀。"}], "explanations": {"磨": "正确答案：磨（mó），指用东西来回擦。", "默": "mò（第四声）与 mó（第二声）声调不同，意思是不出声。", "伯": "bó 与 mó 声母不同（b 与 m），意思是伯父或父亲的哥哥。", "佛": "fó 与 mó 声母不同（f 与 m），意思是佛陀。"}, "sentence_index": null, "correct_answer": "磨"}, "level_3": {"options": [{"text": "磨", "is_correct": true, "explanation": "正确：磨表示小狗在门上来回擦爪子，留下印子，符合语境。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：“撕”一般接纸、布，不说撕爪子。"}, {"text": "洗", "is_correct": false, "explanation": "语义：小狗在门上“洗爪子”不通，洗也不会在门上留下印子。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢掉的意思，小狗不会扔自己的爪子。"}], "explanations": {"磨": "正确：磨表示小狗在门上来回擦爪子，留下印子，符合语境。", "撕": "搭配：“撕”一般接纸、布，不说撕爪子。", "洗": "语义：小狗在门上“洗爪子”不通，洗也不会在门上留下印子。", "扔": "语义：“扔”是丢掉的意思，小狗不会扔自己的爪子。"}, "sentence_index": 6, "correct_answer": "磨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他磨了一封信，寄了出去。", "explanation": "这里应该用〈写〉。磨是用东西来回擦动，写信要用写。"}, {"text": "他磨了一杯水，喝了下去。", "explanation": "这里应该用〈倒〉。磨是用东西来回擦，水要用倒。"}, {"text": "他抬脚磨了一下球。", "explanation": "这里应该用〈踢〉。磨是来回摩擦，踢球要用踢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deebcdfc-2623-4b3b-a262-1127910088b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26740, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小猫在沙发上磨了着爪子。", "corrected_sentence": "小猫在沙发上磨着爪子。", "error_description": "动态助词错误：表示持续的“着”不能与“了”叠用，应为“小猫在沙发上磨着爪子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deebcdfc-2623-4b3b-a262-1127910088b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26740, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的脚在鞋里磨很红。", "corrected_sentence": "他的脚在鞋里磨得很红。", "error_description": "补语错误：表示结果的“很红”前必须用“得”引出，漏掉“得”，应为“他的脚在鞋里磨得很红”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deebcdfc-2623-4b3b-a262-1127910088b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
