INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26742, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种机器，能把别的力量变成电。", "primary_collocate": null, "pronunciation": "fā diàn jī", "ipa": "fa⁵⁵ tjɛn⁵¹ tɕi⁵⁵", "syllable_count": 3, "sentences": [{"text": "这台发电机能把风的力量变成电。", "target_word": "发电机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "停电了，爸爸马上把发电机打开了。", "target_word": "发电机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发电机的声音很大，晚上有点吵。", "target_word": "发电机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂有两台大发电机。", "target_word": "发电机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家后院放着一台旧发电机。", "target_word": "发电机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了一台小发电机。", "target_word": "发电机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发电机转得越快，发出的电越多。", "target_word": "发电机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有发电机，工地上的灯就不会亮。", "target_word": "发电机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在修发电机，手上都是油。", "target_word": "发电机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "露营的时候，我们带了一台小发电机。", "target_word": "发电机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "风力发电机", "label": "复合"}, {"form": "水力发电机", "label": "复合"}], "register": "中性", "sense_fingerprint": "能把别的力量变成电的机器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbaefd5-2b40-495b-aa4c-25bf1b57af9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26742, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发电机", "is_correct": true, "explanation": "正确：「发电机」是能把别的力量变成电的机器，符合句子的描述。"}, {"text": "电灯", "is_correct": false, "explanation": "语义：电灯是消耗电的器具，不能把风的力量变成电。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱消耗电来制冷，与把风的力量变成电的功能无关。"}, {"text": "水泵", "is_correct": false, "explanation": "语义：水泵负责抽水，不能把风的力量变成电。"}], "explanations": {"发电机": "正确：「发电机」是能把别的力量变成电的机器，符合句子的描述。", "电灯": "语义：电灯是消耗电的器具，不能把风的力量变成电。", "冰箱": "语义：冰箱消耗电来制冷，与把风的力量变成电的功能无关。", "水泵": "语义：水泵负责抽水，不能把风的力量变成电。"}, "sentence_index": 0, "correct_answer": "发电机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台发电机可以储存很多电。", "explanation": "这里应该用〈电池〉。电池能储存电，发电机只能产生电，不能储存。"}, {"text": "这家工厂有两台大发电机，专门用来压缩空气。", "explanation": "这里应该用〈空压机〉。空压机负责压缩空气，发电机是把能量转成电的机器，不能压缩空气。"}, {"text": "这台发电机把水烧开，给工厂提供热水。", "explanation": "这里应该用〈锅炉〉。锅炉的作用是烧水，发电机不烧水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83167bfe-5c89-4d79-b6ce-37d6fca01128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26742, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发电机", "is_correct": true, "explanation": "正确：只有「发电机」转起来才能发出电，符合「转得越快，发出的电越多」。"}, {"text": "风扇", "is_correct": false, "explanation": "语义：风扇转动是为了送风，不会发出电，「发出的电」说不通。"}, {"text": "洗衣机", "is_correct": false, "explanation": "语义：洗衣机是用电的器具，转得再快也不会发出电。"}, {"text": "陀螺", "is_correct": false, "explanation": "搭配：陀螺不能发出电，「发出的电」与「陀螺」搭配不当。"}], "explanations": {"发电机": "正确：只有「发电机」转起来才能发出电，符合「转得越快，发出的电越多」。", "风扇": "语义：风扇转动是为了送风，不会发出电，「发出的电」说不通。", "洗衣机": "语义：洗衣机是用电的器具，转得再快也不会发出电。", "陀螺": "搭配：陀螺不能发出电，「发出的电」与「陀螺」搭配不当。"}, "sentence_index": 6, "correct_answer": "发电机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台发电机能帮我们把衣服烘干，冬天很方便。", "explanation": "这里应该用〈烘干机〉。烘干机用热风把衣服烘干，发电机不产生热风，不能烘衣服。"}, {"text": "这台发电机把水抽到楼上，给工厂供水。", "explanation": "这里应该用〈水泵〉。水泵负责抽水，发电机不能抽水。"}, {"text": "发电机把风吹向屋子，让人凉快。", "explanation": "这里应该用〈风扇〉。风扇负责送风，发电机不送风。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83167bfe-5c89-4d79-b6ce-37d6fca01128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26742, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂的发电机有两只。", "corrected_sentence": "工厂的发电机有两台。", "error_description": "量词错误：机器应该用「台」，「只」不用于发电机，应写作「两台」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83167bfe-5c89-4d79-b6ce-37d6fca01128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26742, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "露营的时候，发电机一直着开。", "corrected_sentence": "露营的时候，发电机一直开着。", "error_description": "语序错误：“着”表示动作持续，应紧跟动词“开”之后，写作“一直开着”；“着开”的语序是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83167bfe-5c89-4d79-b6ce-37d6fca01128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
