INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26744, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26744, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "有人专门看着外面，防止别人突然过来。", "primary_collocate": null, "pronunciation": "bǎ fēng", "ipa": "pa˨˩˦ fɤŋ˥", "syllable_count": 2, "sentences": [{"text": "同学们在教室里玩手机，小李在门口把风。", "target_word": "把风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去买零食，你在楼梯口把风。", "target_word": "把风", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们想吓老师，让小王在窗外把风。", "target_word": "把风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们偷偷抽烟，一个人负责把风。", "target_word": "把风", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟在厨房拿糖，姐姐给他把风。", "target_word": "把风", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你帮我在门口把风，有人来就告诉我。", "target_word": "把风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明站在路口把风，怕爸爸回来。", "target_word": "把风", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们想偷偷放烟花，让最小的那个把风。", "target_word": "把风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在门外把风，里面的人在准备生日惊喜。", "target_word": "把风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们商量好了，我进去拿东西，你在外面把风。", "target_word": "把风", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "把了风", "label": "体标：了"}, {"form": "把过风", "label": "体标：过"}], "register": "口语", "sense_fingerprint": "离合动词，专门在外面看着，防止别人突然过来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edc2b444-45c3-4e43-811d-0a9ab0a8e562') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26744, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "把风", "is_correct": true, "explanation": "正确答案。小李在门口望风，防止老师突然过来。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：小李在门口洗澡，与“同学们在教室里玩手机”的场景不符，不能用来防备别人。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指写字，小李在门口写字与防备老师的情境不符，不能表达望风。"}, {"text": "骑", "is_correct": false, "explanation": "语义：“骑”指骑乘，小李在门口骑车与防备老师的情境不符，句意不通。"}], "explanations": {"把风": "正确答案。小李在门口望风，防止老师突然过来。", "洗澡": "语义：小李在门口洗澡，与“同学们在教室里玩手机”的场景不符，不能用来防备别人。", "写": "语义：“写”指写字，小李在门口写字与防备老师的情境不符，不能表达望风。", "骑": "语义：“骑”指骑乘，小李在门口骑车与防备老师的情境不符，句意不通。"}, "sentence_index": 0, "correct_answer": "把风"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教室里的窗户要定时把风。", "explanation": "这里应该用〈通风〉。把风是守望警戒，不是让空气流通。"}, {"text": "湿衣服挂在院子里，晒一下午就能把风。", "explanation": "这里应该用〈晾干〉。把风是守望警戒，不是把衣服晒干。"}, {"text": "冬天出门，他用围巾把风。", "explanation": "这里应该用〈挡风〉。把风是守望警戒，不是阻挡风。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26744, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "把风", "is_correct": true, "explanation": "正确答案。小明站在路口望风，防止爸爸突然回来被发现。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：站在路口睡觉与“站在路口”的动作相矛盾，也不能防备爸爸回来。"}, {"text": "说", "is_correct": false, "explanation": "语义：“说”指说话，小明站在路口说话无法防备爸爸回来，句意不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：小明站在路口游泳不合常理，与“怕爸爸回来”的语境不符。"}], "explanations": {"把风": "正确答案。小明站在路口望风，防止爸爸突然回来被发现。", "睡觉": "语义：站在路口睡觉与“站在路口”的动作相矛盾，也不能防备爸爸回来。", "说": "语义：“说”指说话，小明站在路口说话无法防备爸爸回来，句意不通。", "游泳": "语义：小明站在路口游泳不合常理，与“怕爸爸回来”的语境不符。"}, "sentence_index": 6, "correct_answer": "把风"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏天晚上，我喜欢在阳台把风。", "explanation": "这里应该用〈吹风〉。把风是守望警戒，不是让风吹到身上。"}, {"text": "小船把风前进，帆鼓得很满。", "explanation": "这里应该用〈迎风〉。把风是守望警戒，不能用来描述船迎着风前进。"}, {"text": "他拿着蒲扇把风，凉快凉快。", "explanation": "这里应该用〈扇风〉。把风是守望警戒，不能说用蒲扇把风。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26744, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨天他在门口把着一次风。", "corrected_sentence": "昨天他在门口把过一次风。", "error_description": "错误：“把着一次风”。正确：“把过一次风”。“昨天……一次”说的是做过的经历，体标要用“过”，不能用表示持续的“着”；“过”放在“把”和“风”中间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26744, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小李在窗外把风着，怕老师看见。", "corrected_sentence": "小李在窗外把着风，怕老师看见。", "error_description": "错误在体标“着”的位置：“着”应紧跟“把”，写成“把着风”，不能放在“风”后面写成“把风着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
