INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26746, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "风的力量。", "primary_collocate": null, "pronunciation": "fēng lì", "ipa": "fɤŋ˥˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "风车靠风力转动。", "target_word": "风力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "古代的船靠风力前进。", "target_word": "风力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民用风力把水从河里抽上来。", "target_word": "风力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风力可以推动帆船向前走。", "target_word": "风力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子用风力让纸风车转了起来。", "target_word": "风力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种小车是靠风力开动的。", "target_word": "风力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风力能把树叶吹到很远的地方。", "target_word": "风力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们早就知道用风力磨面。", "target_word": "风力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "帆船要有风力才能走。", "target_word": "风力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古时候的磨坊用风力推动石磨。", "target_word": "风力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "风力发电", "label": "复合"}, {"form": "风力发电机", "label": "复合"}], "register": "中性", "sense_fingerprint": "风所具有的、可以利用的力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dd9edb8-eee8-4fd4-bb69-7975075c62e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26746, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "风力", "is_correct": true, "explanation": "正确。风车靠风的力量转动，“风力”与句意相符。"}, {"text": "水力", "is_correct": false, "explanation": "语义：“水力”指水的力量，风车靠的是风，不是水。"}, {"text": "蒸汽", "is_correct": false, "explanation": "语义：“蒸汽”是水受热产生的气体，风车不靠它转动。"}, {"text": "体力", "is_correct": false, "explanation": "搭配：“靠体力”的主语一般是人或畜力，风车是靠风转动的。"}], "explanations": {"风力": "正确。风车靠风的力量转动，“风力”与句意相符。", "水力": "语义：“水力”指水的力量，风车靠的是风，不是水。", "蒸汽": "语义：“蒸汽”是水受热产生的气体，风车不靠它转动。", "体力": "搭配：“靠体力”的主语一般是人或畜力，风车是靠风转动的。"}, "sentence_index": 0, "correct_answer": "风力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很有风力，每天都去跑步。", "explanation": "这里应该用〈精力〉。风力指风的力量，不能用来形容人的精力。"}, {"text": "这颗炸弹的风力很大。", "explanation": "这里应该用〈威力〉。风力指风的力量，炸弹的破坏力要用“威力”。"}, {"text": "今天风力达到每秒十米。", "explanation": "这里应该用〈风速〉。风速才用“每秒多少米”计量，风力通常用等级表示。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26746, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "风力", "is_correct": true, "explanation": "正确。风力可以把树叶吹到很远的地方，语义相符。"}, {"text": "水流", "is_correct": false, "explanation": "语义：“吹”的动力来自风，水流不能像风一样把树叶吹到很远。"}, {"text": "热量", "is_correct": false, "explanation": "语义：热量不能把树叶吹走，这里说的是风的作用。"}, {"text": "力气", "is_correct": false, "explanation": "搭配：“力气”多用于人，不说力气吹树叶。"}], "explanations": {"风力": "正确。风力可以把树叶吹到很远的地方，语义相符。", "水流": "语义：“吹”的动力来自风，水流不能像风一样把树叶吹到很远。", "热量": "语义：热量不能把树叶吹走，这里说的是风的作用。", "力气": "搭配：“力气”多用于人，不说力气吹树叶。"}, "sentence_index": 6, "correct_answer": "风力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的风力很强，大家都佩服他。", "explanation": "这里应该用〈实力〉。风力指风的力量，不能用来说人的能力。"}, {"text": "学习的风力很大，让我喘不过气。", "explanation": "这里应该用〈压力〉。风力指风的力量，不能用来说人承受的心理压力。"}, {"text": "这位演员的风力很大，观众都很喜欢。", "explanation": "这里应该用〈魅力〉。风力指风的力量，不能用来形容人的吸引力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26746, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "风力达到了四个。", "corrected_sentence": "风力达到了四级。", "error_description": "错误：风力的量词用错。风力等级要用“级”，应说“四级”，不说“四个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26746, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农民风力抽水。", "corrected_sentence": "农民用风力抽水。", "error_description": "错误：引出工具的介词“用”漏掉了。应说“农民用风力抽水”，“风力”作为工具前要加“用”，不说“农民风力抽水”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
