INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26748, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "叶子。", "primary_collocate": null, "pronunciation": "yè piàn", "ipa": "je⁵¹ pʰjɛn⁵¹", "syllable_count": 2, "sentences": [{"text": "树上的叶片都绿了。", "target_word": "叶片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上有很多黄色的叶片。", "target_word": "叶片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一吹，叶片就掉下来了。", "target_word": "叶片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花盆里的小草长出了新叶片。", "target_word": "叶片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟躲在大叶片下面。", "target_word": "叶片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹捡了几片红色的叶片。", "target_word": "叶片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种叶片摸起来很软。", "target_word": "叶片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天，叶片又厚又绿。", "target_word": "叶片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小蜗牛爬到了叶片上。", "target_word": "叶片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "叶片上落着一只小虫。", "target_word": "叶片", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "葉片", "label": "繁体"}], "register": "中性", "sense_fingerprint": "树和草上的叶子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dd9edb8-eee8-4fd4-bb69-7975075c62e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26748, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "叶片", "is_correct": true, "explanation": "正确：叶片指叶子，树上的叶子变绿符合语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会长在树上变绿，句子不通。"}, {"text": "雨点", "is_correct": false, "explanation": "语义：雨点不是植物，不会变绿。"}, {"text": "花朵", "is_correct": false, "explanation": "搭配：“绿”通常说叶子或草，不说花朵变绿。"}], "explanations": {"叶片": "正确：叶片指叶子，树上的叶子变绿符合语境。", "石头": "语义：石头不会长在树上变绿，句子不通。", "雨点": "语义：雨点不是植物，不会变绿。", "花朵": "搭配：“绿”通常说叶子或草，不说花朵变绿。"}, "sentence_index": 0, "correct_answer": "叶片"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妹妹买了一棵叶片，放在窗台上。", "explanation": "这里应该用〈片〉。叶片的量词是“片”，“棵”用于整株植物，不用于单片叶子。"}, {"text": "这根叶片很粗，小鸟站在上面唱歌。", "explanation": "这里应该用〈树枝〉。又粗又能让鸟站的是树枝；叶片指扁平的叶子，不指树枝。"}, {"text": "我家的鸡身上长了很多叶片。", "explanation": "这里应该用〈羽毛〉。鸡身上长的是羽毛，叶片是植物的部分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26748, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "叶片", "is_correct": true, "explanation": "正确：叶片是柔软的植物部分，“摸起来很软”符合它的特征。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是无形的气体，不能用手摸起来很软。"}, {"text": "钢铁", "is_correct": false, "explanation": "语义：钢铁坚硬，与“摸起来很软”的描述相矛盾。"}, {"text": "水泥", "is_correct": false, "explanation": "搭配：“摸起来很软”多用于织物、植物等，水泥不作此类描写。"}], "explanations": {"叶片": "正确：叶片是柔软的植物部分，“摸起来很软”符合它的特征。", "空气": "语义：空气是无形的气体，不能用手摸起来很软。", "钢铁": "语义：钢铁坚硬，与“摸起来很软”的描述相矛盾。", "水泥": "搭配：“摸起来很软”多用于织物、植物等，水泥不作此类描写。"}, "sentence_index": 6, "correct_answer": "叶片"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书有很多叶片，我看了一个下午。", "explanation": "这里应该用〈页〉。书的纸张叫“页”，叶片指植物的叶子，不指书页。"}, {"text": "妹妹正在背叶片，明天老师要检查。", "explanation": "这里应该用〈课文〉。“背”的对象是课文等文字，叶片指植物的叶子，不能背。"}, {"text": "这辆自行车的叶片坏了。", "explanation": "这里应该用〈车轮〉。自行车的部件是车轮，叶片指植物的叶子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26748, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院子里落下了好几棵叶片。", "corrected_sentence": "院子里落下了好几片叶片。", "error_description": "量词错误：叶片应用量词“片”计量，“棵”用于整株植物，不用于叶片，应改为“好几片叶片”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26748, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小虫落在好几棵叶片上。", "corrected_sentence": "小虫落在好几片叶片上。", "error_description": "量词错误：叶片应用量词“片”计量，“棵”用于整株植物，应改为“好几片叶片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
