INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26750, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很大很大。", "primary_collocate": null, "pronunciation": "dà dà de", "ipa": "ta˥˩ ta˥˩ tə", "syllable_count": 3, "sentences": [{"text": "这只熊猫有大大的黑眼圈。", "target_word": "大大的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在纸上画了一个大大的太阳。", "target_word": "大大的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的手大大的，能抓住三个苹果。", "target_word": "大大的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海边有一座大大的灯塔。", "target_word": "大大的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子打开大大的礼物盒，笑了。", "target_word": "大大的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天上飘着大大的白云。", "target_word": "大大的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "院子里种着一棵大大的苹果树。", "target_word": "大大的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她戴着一副大大的眼镜。", "target_word": "大大的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个南瓜大大的，一个人抱不动。", "target_word": "大大的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在黑板上写了大大的“好”字。", "target_word": "大大的", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "重叠式形容词，强调形状或尺寸很大，常用来描述具体事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edc2b444-45c3-4e43-811d-0a9ab0a8e562') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26750, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大大的", "is_correct": true, "explanation": "正确答案。形容熊猫眼圈很大，符合句意。"}, {"text": "冷冷的", "is_correct": false, "explanation": "语义：“冷”形容温度，与描写黑眼圈的语境不合。"}, {"text": "软软的", "is_correct": false, "explanation": "语义：“软”形容质地，黑眼圈不能用来描述为“软”的。"}, {"text": "甜甜的", "is_correct": false, "explanation": "搭配：“甜”不能用来形容“黑眼圈”，这一搭配不自然。"}], "explanations": {"大大的": "正确答案。形容熊猫眼圈很大，符合句意。", "冷冷的": "语义：“冷”形容温度，与描写黑眼圈的语境不合。", "软软的": "语义：“软”形容质地，黑眼圈不能用来描述为“软”的。", "甜甜的": "搭配：“甜”不能用来形容“黑眼圈”，这一搭配不自然。"}, "sentence_index": 0, "correct_answer": "大大的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这碗汤大大的，小心烫嘴。", "explanation": "这里应该用〈热热的〉。“大大的”说尺寸，不说温度。"}, {"text": "这杯咖啡大大的，喝了睡不着。", "explanation": "这里应该用〈浓浓的〉。“大大的”说尺寸，不说味道浓淡。"}, {"text": "这根绳子大大的，有十米。", "explanation": "这里应该用〈长长的〉。说长度要用“长长的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26750, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大大的", "is_correct": true, "explanation": "正确答案。形容苹果树很大，符合句意。"}, {"text": "冷冷的", "is_correct": false, "explanation": "语义：“冷”形容温度，与描写苹果树的语境不合。"}, {"text": "硬硬的", "is_correct": false, "explanation": "语义：“硬”形容质地，不用来描述树的大小。"}, {"text": "薄薄的", "is_correct": false, "explanation": "搭配：“薄”形容扁平物体的厚度小，不能用来形容树。"}], "explanations": {"大大的": "正确答案。形容苹果树很大，符合句意。", "冷冷的": "语义：“冷”形容温度，与描写苹果树的语境不合。", "硬硬的": "语义：“硬”形容质地，不用来描述树的大小。", "薄薄的": "搭配：“薄”形容扁平物体的厚度小，不能用来形容树。"}, "sentence_index": 6, "correct_answer": "大大的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的头发大大的，一直到腰。", "explanation": "这里应该用〈长长的〉。头发说长短，不说大小。"}, {"text": "这条河大大的，看不见底。", "explanation": "这里应该用〈深深的〉。看不见底说的是深，不是大。"}, {"text": "这本书大大的，有一千页。", "explanation": "这里应该用〈厚厚的〉。页数多说的是厚，不是大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26750, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本书的封面上印着很大大的字。", "corrected_sentence": "这本书的封面上印着大大的字。", "error_description": "错误：“很大大的”。正确：“大大的”。“大大的”本身已表示程度，前面不能再加“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26750, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "教室里挂着一面很大大的国旗。", "corrected_sentence": "教室里挂着一面大大的国旗。", "error_description": "错误：“很大大的”。正确：“大大的”。“大大的”本身已表示程度，前面不能再加“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
