INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26752, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "物体转圈圈。", "primary_collocate": null, "pronunciation": "zhuàn dòng", "ipa": "ʈʂwan⁵¹ tʊŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "小风车在风里转动。", "target_word": "转动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗衣机的桶一直在转动。", "target_word": "转动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玩具车的轮子转动得很快。", "target_word": "转动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一按开关，玩具飞机的螺旋桨就转动了。", "target_word": "转动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木马在转动，小朋友笑个不停。", "target_word": "转动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水一流，小水车就转动了。", "target_word": "转动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钟里的小齿轮一直在转动。", "target_word": "转动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摩天轮慢慢转动，人们在上面看风景。", "target_word": "转动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的小陀螺转动了很久才停。", "target_word": "转动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友一按开关，音乐盒里的小人就转动起来了。", "target_word": "转动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "转动了", "label": "体标"}, {"form": "转动着", "label": "体标"}, {"form": "转动过", "label": "体标"}, {"form": "轉動", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西一圈一圈地转", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dd9edb8-eee8-4fd4-bb69-7975075c62e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26752, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "转动", "is_correct": true, "explanation": "正确。转动指小风车在风中一圈一圈地转。"}, {"text": "生长", "is_correct": false, "explanation": "语义：“生长”指生物长大，与小风车在风里的运动无关。"}, {"text": "转身", "is_correct": false, "explanation": "搭配：“转身”一般用于人或动物，不说风车转身。"}, {"text": "睡觉", "is_correct": false, "explanation": "搭配：“睡觉”的主语是人或动物，小风车不会睡觉。"}], "explanations": {"转动": "正确。转动指小风车在风中一圈一圈地转。", "生长": "语义：“生长”指生物长大，与小风车在风里的运动无关。", "转身": "搭配：“转身”一般用于人或动物，不说风车转身。", "睡觉": "搭配：“睡觉”的主语是人或动物，小风车不会睡觉。"}, "sentence_index": 0, "correct_answer": "转动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一按开关，玩具车就转动到了桌子另一头。", "explanation": "这里应该用〈移动〉。转动指物体绕轴旋转；玩具车整体从一头挪到另一头是平移，要用“移动”。"}, {"text": "拉门沿着轨道一直向前转动。", "explanation": "这里应该用〈滑动〉。拉门沿轨道直线推拉是滑动，不是绕轴旋转，转动不能这么用。"}, {"text": "妹妹在房间里转动，找她的书。", "explanation": "这里应该用〈走动〉。人在房间里来回走要用“走动”，转动指物体绕轴旋转。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26752, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "转动", "is_correct": true, "explanation": "正确。转动指小齿轮在钟里一直绕轴运转。"}, {"text": "静止", "is_correct": false, "explanation": "语义：“一直在”强调持续的运动，“静止”与之矛盾。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：“唱歌”的主语是人，不说齿轮唱歌。"}, {"text": "微笑", "is_correct": false, "explanation": "搭配：“微笑”的主语是人，齿轮不会微笑。"}], "explanations": {"转动": "正确。转动指小齿轮在钟里一直绕轴运转。", "静止": "语义：“一直在”强调持续的运动，“静止”与之矛盾。", "唱歌": "搭配：“唱歌”的主语是人，不说齿轮唱歌。", "微笑": "搭配：“微笑”的主语是人，齿轮不会微笑。"}, "sentence_index": 6, "correct_answer": "转动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "钟摆在左右转动。", "explanation": "这里应该用〈摆动〉。钟摆左右来回摆，不是绕轴转圈，要用“摆动”。"}, {"text": "窗帘在风里转动，来回飘。", "explanation": "这里应该用〈飘动〉。窗帘被风吹得来回飘，是左右摇摆，不是绕轴旋转。"}, {"text": "心脏在胸口里转动。", "explanation": "这里应该用〈跳动〉。心脏一起一伏地搏动要用“跳动”，转动指绕轴旋转。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26752, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "陀螺又转动下来了。", "corrected_sentence": "陀螺又转动起来了。", "error_description": "错误：趋向补语用错，“下来”应改为“起来”。陀螺开始旋转，要说“转动起来”，不说“转动下来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26752, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电扇还没转动了。", "corrected_sentence": "电扇还没转动。", "error_description": "错误：否定句中“没”后面不能再用“了”。正确说法是“还没转动”，不说“还没转动了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26754, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "注水", "is_correct": true, "explanation": "正确答案。注水指把水灌入某处，与抽水的方向相反，构成反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "跑步与抽水的动作无关，不是它的反义词。"}, {"text": "读书", "is_correct": false, "explanation": "读书与抽水没有相对的关系，二者不是同类动作。"}, {"text": "打扫", "is_correct": false, "explanation": "打扫与抽水没有反义关系，不是相对的动作。"}], "correct_answer": "注水", "explanations": {"注水": "正确答案。注水指把水灌入某处，与抽水的方向相反，构成反义关系。", "跑步": "跑步与抽水的动作无关，不是它的反义词。", "读书": "读书与抽水没有相对的关系，二者不是同类动作。", "打扫": "打扫与抽水没有反义关系，不是相对的动作。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26754, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "注水", "is_correct": true, "explanation": "正确答案。注水指把水灌入某处，与抽水的方向相反，构成反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌与抽水没有相对的关系，不是它的反义词。"}, {"text": "散步", "is_correct": false, "explanation": "散步与抽水的动作无关，不构成反义关系。"}, {"text": "写字", "is_correct": false, "explanation": "写字与抽水没有反义关系，二者不是相对的动作。"}], "correct_answer": "注水", "explanations": {"注水": "正确答案。注水指把水灌入某处，与抽水的方向相反，构成反义关系。", "唱歌": "唱歌与抽水没有相对的关系，不是它的反义词。", "散步": "散步与抽水的动作无关，不构成反义关系。", "写字": "写字与抽水没有反义关系，二者不是相对的动作。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26754, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用水泵把水从一个地方吸到另一个地方。", "primary_collocate": null, "pronunciation": "chōu shuǐ", "ipa": "ʈʂʰoʊ˥ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他们用水泵抽水灌溉稻田。", "target_word": "抽水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "暴雨过后，街道上到处都是水，消防队来抽水。", "target_word": "抽水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人在矿井里抽水，里面的水太多了。", "target_word": "抽水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的水池太脏了，爸爸准备抽水换新的。", "target_word": "抽水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器声音很大，一直在抽水。", "target_word": "抽水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河边有一座小房子，专门用来抽水。", "target_word": "抽水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天来了，农民开始给麦田抽水。", "target_word": "抽水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没电的时候，村里就不能抽水。", "target_word": "抽水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "游泳池该换水了，工人正在抽水。", "target_word": "抽水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他按下开关，水泵就开始抽水了。", "target_word": "抽水", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "抽了水", "label": "体标：了"}, {"form": "抽过水", "label": "体标：过"}], "register": "中性", "sense_fingerprint": "离合动词，用水泵把水吸出并送到另一个地方，如灌溉、排水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edc2b444-45c3-4e43-811d-0a9ab0a8e562') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26754, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "抽水", "is_correct": true, "explanation": "正确答案。chōu shuǐ 指用水泵把水吸出并送到另一个地方。"}, {"text": "冲水", "is_correct": false, "explanation": "冲水（chōng shuǐ）与抽水的韵母不同（ong 与 ou），意思是用水冲洗，不是用水泵送水。"}, {"text": "出水", "is_correct": false, "explanation": "出水（chū shuǐ）与抽水的韵母不同（u 与 ou），意思是水从里面流出。"}, {"text": "臭水", "is_correct": false, "explanation": "臭水（chòu shuǐ）与抽水的声调不同（第四声与第一声），意思是难闻的水。"}, {"text": "抽税", "is_correct": false, "explanation": "抽税（chōu shuì）与抽水的第二个音节声调不同（第四声与第三声），意思是征收税款。"}], "explanations": {"抽水": "正确答案。chōu shuǐ 指用水泵把水吸出并送到另一个地方。", "冲水": "冲水（chōng shuǐ）与抽水的韵母不同（ong 与 ou），意思是用水冲洗，不是用水泵送水。", "出水": "出水（chū shuǐ）与抽水的韵母不同（u 与 ou），意思是水从里面流出。", "臭水": "臭水（chòu shuǐ）与抽水的声调不同（第四声与第一声），意思是难闻的水。", "抽税": "抽税（chōu shuì）与抽水的第二个音节声调不同（第四声与第三声），意思是征收税款。"}, "sentence_index": null, "correct_answer": "抽水"}, "level_3": {"options": [{"text": "抽水", "is_correct": true, "explanation": "正确答案。用水泵把水抽出来，再灌溉稻田。"}, {"text": "修理", "is_correct": false, "explanation": "语义：修理不能用来灌溉稻田，与“用水泵”的动作不相容。"}, {"text": "关", "is_correct": false, "explanation": "搭配：“关”不能直接与“灌溉稻田”搭配，关的是水泵或水阀，句子说不通。"}, {"text": "说", "is_correct": false, "explanation": "语义：“说”指说话，用水泵灌溉稻田与“说”无关，句意不通。"}], "explanations": {"抽水": "正确答案。用水泵把水抽出来，再灌溉稻田。", "修理": "语义：修理不能用来灌溉稻田，与“用水泵”的动作不相容。", "关": "搭配：“关”不能直接与“灌溉稻田”搭配，关的是水泵或水阀，句子说不通。", "说": "语义：“说”指说话，用水泵灌溉稻田与“说”无关，句意不通。"}, "sentence_index": 0, "correct_answer": "抽水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "河堤的闸门一开，水就往下游抽水。", "explanation": "这里应该用〈放水〉。抽水需要水泵把水吸走，闸门打开后水自己流下去，要说放水，不能说抽水。"}, {"text": "护士用针管从病人手指上抽水，化验血糖。", "explanation": "这里应该用〈抽血〉。抽水是用水泵把水输送走，从人体里取血要说抽血，不能说抽水。"}, {"text": "小鸟在河边抽水，喝得很开心。", "explanation": "这里应该用〈喝水〉。抽水要借助水泵，小鸟是自己低头饮水，不能说抽水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26754, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抽水", "is_correct": true, "explanation": "正确答案。农民在春天用水泵把水送到麦田里。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：给麦田唱歌不是农民春耕的动作，与“春天来了”的语境不符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：农民不会给麦田睡觉，这句话说不通。"}, {"text": "扔", "is_correct": false, "explanation": "配价：“扔”要接被扔的东西，此处没有宾语，句子不完整。"}], "explanations": {"抽水": "正确答案。农民在春天用水泵把水送到麦田里。", "唱歌": "语义：给麦田唱歌不是农民春耕的动作，与“春天来了”的语境不符。", "睡觉": "语义：农民不会给麦田睡觉，这句话说不通。", "扔": "配价：“扔”要接被扔的东西，此处没有宾语，句子不完整。"}, "sentence_index": 6, "correct_answer": "抽水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天气干燥，我每天往脸上抽水。", "explanation": "这里应该用〈补水〉。抽水是把水取出送走，不能用来给皮肤增加水分。"}, {"text": "抹布可以抽水，擦干地面。", "explanation": "这里应该用〈吸水〉。抽水是用水泵把水送到别处，抹布靠纤维把水吸进去，不能说抽水。"}, {"text": "屋檐还在一滴一滴地抽水。", "explanation": "这里应该用〈滴水〉。抽水是用水泵把水输送走，屋檐的水是自己往下滴，不能说抽水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26754, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人昨天抽着两个小时水。", "corrected_sentence": "工人昨天抽了两个小时水。", "error_description": "错误：“抽着两个小时水”。正确：“抽了两个小时水”。“昨天”加时量表示已经完成的动作，体标要用“了”，不能用表示持续的“着”；“了”放在“抽”和“水”中间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26754, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "水泵一直在抽水着。", "corrected_sentence": "水泵一直在抽水。", "error_description": "错误：“抽水着”。正确：“抽水”。体标“着”不能附在离合词“抽水”的宾语“水”之后；表持续时“着”应紧跟动词“抽”，即“抽着水”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
