INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26758, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一直想出新东西。", "primary_collocate": null, "pronunciation": "bú duàn chuàng xīn", "ipa": "pu˧˥ tuan˥˩ ʈʂʰuaŋ˥˩ ɕin˥", "syllable_count": 4, "sentences": [{"text": "他做菜很用心，总是不断创新。", "target_word": "不断创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆的老板不断创新，每个月都有新菜。", "target_word": "不断创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们玩游戏时不断创新，想出很多新玩法。", "target_word": "不断创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想让生活有意思，就要不断创新。", "target_word": "不断创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个设计师不断创新，每年都画出新衣服。", "target_word": "不断创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂的工人不断创新，把机器改得更好用。", "target_word": "不断创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们不断创新，所以顾客每次来都有新东西看。", "target_word": "不断创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校鼓励学生不断创新，多想新办法。", "target_word": "不断创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王做玩具不断创新，每个玩具都不一样。", "target_word": "不断创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的歌手不断创新，新歌总是和以前不同。", "target_word": "不断创新", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不断地创新", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "一直想出新东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbaefd5-2b40-495b-aa4c-25bf1b57af9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26758, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不断偷懒", "is_correct": false, "explanation": "语义：“不断偷懒”与“他做菜很用心”矛盾，用心的人不会偷懒。"}, {"text": "不断创新", "is_correct": true, "explanation": "“他做菜很用心，总是不断创新”前后一致，是正确答案。"}, {"text": "不断抱怨", "is_correct": false, "explanation": "语义：“不断抱怨”与“做菜很用心”的态度矛盾，前后语气不一致。"}, {"text": "不断吃饭", "is_correct": false, "explanation": "语义：“不断吃饭”与“他做菜很用心”没有逻辑联系，句子意思不通。"}], "explanations": {"不断偷懒": "语义：“不断偷懒”与“他做菜很用心”矛盾，用心的人不会偷懒。", "不断创新": "“他做菜很用心，总是不断创新”前后一致，是正确答案。", "不断抱怨": "语义：“不断抱怨”与“做菜很用心”的态度矛盾，前后语气不一致。", "不断吃饭": "语义：“不断吃饭”与“他做菜很用心”没有逻辑联系，句子意思不通。"}, "sentence_index": 0, "correct_answer": "不断创新"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子每天不断创新课文。", "explanation": "这里应该用〈复习〉。不断创新是一直想出新东西，复习课文要用复习，不能用创新。"}, {"text": "妈妈不断创新房间。", "explanation": "这里应该用〈整理〉。不断创新是指想出新东西，收拾房间要用整理。"}, {"text": "运动员每天不断创新体力。", "explanation": "这里应该用〈训练〉。不断创新是指想出新东西，锻炼体力要用训练。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83167bfe-5c89-4d79-b6ce-37d6fca01128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26758, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不断停业", "is_correct": false, "explanation": "语义：“不断停业”与“顾客每次来都有新东西看”矛盾，店铺停业顾客就看不到新东西。"}, {"text": "不断创新", "is_correct": true, "explanation": "“他们不断创新，所以顾客每次来都有新东西看”因果连贯，是正确答案。"}, {"text": "不断重复", "is_correct": false, "explanation": "语义：“不断重复”与“有新东西看”矛盾，重复不会带来新东西。"}, {"text": "不断抄袭", "is_correct": false, "explanation": "语域：“抄袭”带明显的指责色彩，与这里的赞扬语气不合，而且意思与“有新东西看”相反。"}], "explanations": {"不断停业": "语义：“不断停业”与“顾客每次来都有新东西看”矛盾，店铺停业顾客就看不到新东西。", "不断创新": "“他们不断创新，所以顾客每次来都有新东西看”因果连贯，是正确答案。", "不断重复": "语义：“不断重复”与“有新东西看”矛盾，重复不会带来新东西。", "不断抄袭": "语域：“抄袭”带明显的指责色彩，与这里的赞扬语气不合，而且意思与“有新东西看”相反。"}, "sentence_index": 6, "correct_answer": "不断创新"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人每天不断创新碗筷。", "explanation": "这里应该用〈清洗〉。不断创新指一直想出新东西，洗碗筷要用清洗，不能用创新。"}, {"text": "园丁每天不断创新草地。", "explanation": "这里应该用〈修剪〉。不断创新指一直想出新东西，修整草地要用修剪，不能用创新。"}, {"text": "阿姨每天不断创新屋子。", "explanation": "这里应该用〈打扫〉。不断创新是想出新东西，收拾屋子要用打扫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83167bfe-5c89-4d79-b6ce-37d6fca01128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26758, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个作家了不断创新，每本书的写法都不同。", "corrected_sentence": "这个作家不断创新，每本书的写法都不同。", "error_description": "多了一个“了”，而且放错了位置。“了”不能放在“不断”前面，这句不需要“了”，应写作“这个作家不断创新”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83167bfe-5c89-4d79-b6ce-37d6fca01128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26758, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们的歌手会不断创新去，新歌总是和以前不同。", "corrected_sentence": "我们的歌手会不断创新下去，新歌总是和以前不同。", "error_description": "补语少了一个“下”。“去”单独接在“创新”后面不通，应写作“不断创新下去”，表示持续地创新下去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83167bfe-5c89-4d79-b6ce-37d6fca01128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
