INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26762, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "电站是能发出电的地方。", "primary_collocate": null, "pronunciation": "diàn zhàn", "ipa": "tjɛn⁵¹ ʈʂan⁵¹", "syllable_count": 2, "sentences": [{"text": "电站是发电的地方。", "target_word": "电站", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我家旁边有一座电站，能发很多电。", "target_word": "电站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电站旁边有一条大河，水用来发电。", "target_word": "电站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸在电站修发电机，他是工程师。", "target_word": "电站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有了电站，村里晚上就有灯了。", "target_word": "电站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师带我们参观了一座能发电的电站。", "target_word": "电站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电站用风发电。", "target_word": "电站", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "电站发的电可以让工厂开机器。", "target_word": "电站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河上有一座电站，水从高处流下来发电。", "target_word": "电站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道电站是怎样发电的吗？", "target_word": "电站", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "水电站", "label": "复合"}, {"form": "電站", "label": "繁体"}], "register": "中性", "sense_fingerprint": "能发出电的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2be58e91-1e7c-48b9-beed-073729f7dde7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26762, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "医院", "is_correct": false, "explanation": "语义：“医院”是治病的地方，不是发电的地方，与句意不符。"}, {"text": "电站", "is_correct": true, "explanation": "正确：“电站”是发电的地方，符合“是发电的地方”的句意。"}, {"text": "发电机", "is_correct": false, "explanation": "搭配：“发电机”是设备，不是“地方”，不能与“是……的地方”搭配。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：“图书馆”是供人读书的地方，不是发电的地方。"}], "explanations": {"医院": "语义：“医院”是治病的地方，不是发电的地方，与句意不符。", "电站": "正确：“电站”是发电的地方，符合“是发电的地方”的句意。", "发电机": "搭配：“发电机”是设备，不是“地方”，不能与“是……的地方”搭配。", "图书馆": "语义：“图书馆”是供人读书的地方，不是发电的地方。"}, "sentence_index": 0, "correct_answer": "电站"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家电站每天卖很多蔬菜。", "explanation": "这里应该用〈超市〉。电站不卖东西，卖蔬菜要用〈超市〉。"}, {"text": "这个电站有一千多名学生。", "explanation": "这里应该用〈学校〉。学生在学校学习，电站是发电的地方，不是学校，没有学生。"}, {"text": "这个电站每周都有比赛。", "explanation": "这里应该用〈体育馆〉。比赛要在〈体育馆〉举行，电站不举办比赛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7920bec-511e-4978-abf0-7c5fcd4f53ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26762, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手机", "is_correct": false, "explanation": "语义：手机不能用风发电，与句中“用风发电”的语境冲突。"}, {"text": "电站", "is_correct": true, "explanation": "正确：“电站”是能发电的地方，可以用风发电，符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“桌子”不是发电的设备或场所，不能与“用风发电”搭配。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎是动物，不能用风发电，与句意不符。"}], "explanations": {"手机": "语义：手机不能用风发电，与句中“用风发电”的语境冲突。", "电站": "正确：“电站”是能发电的地方，可以用风发电，符合句意。", "桌子": "搭配：“桌子”不是发电的设备或场所，不能与“用风发电”搭配。", "老虎": "语义：老虎是动物，不能用风发电，与句意不符。"}, "sentence_index": 6, "correct_answer": "电站"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座电站每天有很多病人来看病。", "explanation": "这里应该用〈医院〉。看病要去〈医院〉，电站是发电的地方，不接待病人。"}, {"text": "这座电站每天有很多航班起飞。", "explanation": "这里应该用〈机场〉。航班起飞要在〈机场〉，电站不起降飞机。"}, {"text": "这家电站每天有很多人存钱。", "explanation": "这里应该用〈银行〉。存钱要去〈银行〉，电站不办理存款。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7920bec-511e-4978-abf0-7c5fcd4f53ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26762, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只电站白天也在发电。", "corrected_sentence": "那座电站白天也在发电。", "error_description": "量词错误：“电站”的量词是“座”，“只”用于动物，应改为“那座电站”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7920bec-511e-4978-abf0-7c5fcd4f53ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26762, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那座电站停来下了。", "corrected_sentence": "那座电站停下来了。", "error_description": "“下来”是趋向补语，顺序不能颠倒，应说“停下来了”；“停来下了”把“下来”的顺序颠倒了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7920bec-511e-4978-abf0-7c5fcd4f53ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
