INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26770, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26770, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大地平平的，没有山，也没有高大的树林。", "primary_collocate": null, "pronunciation": "píng yuán", "ipa": "pʰiŋ˧˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "平原一眼看不到山。", "target_word": "平原", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这片平原一望无际，没有山也没有高树。", "target_word": "平原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "平原上没有高树。", "target_word": "平原", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我喜欢在平原上骑车。", "target_word": "平原", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "平原上风很大，也没有树。", "target_word": "平原", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "走了一天，还是平原，看不到山。", "target_word": "平原", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从小住在平原，没见过高山。", "target_word": "平原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐车在平原上走，窗外一直是平平的大地。", "target_word": "平原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "平原那么大，站着也能看到很远的地方。", "target_word": "平原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里人第一次到平原，觉得天特别大。", "target_word": "平原", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一片平原", "label": "量词"}, {"form": "平原地区", "label": "复合"}], "register": "中性", "sense_fingerprint": "平坦开阔、无山无高树的大地（强调一望无际的平）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c8e9f36-9d8f-4bd1-976d-30c7aefae07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26770, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "平原", "is_correct": true, "explanation": "正确答案。“平原一眼看不到山”符合平原没有山的特点。"}, {"text": "山区", "is_correct": false, "explanation": "语义：山区到处是山，与“一眼看不到山”矛盾。"}, {"text": "山谷", "is_correct": false, "explanation": "搭配：山谷是两山之间的低地，不能与“一眼看不到山”这样的说法搭配。"}, {"text": "高山", "is_correct": false, "explanation": "语义：高山本身就是山，不能说“高山一眼看不到山”。"}], "explanations": {"平原": "正确答案。“平原一眼看不到山”符合平原没有山的特点。", "山区": "语义：山区到处是山，与“一眼看不到山”矛盾。", "山谷": "搭配：山谷是两山之间的低地，不能与“一眼看不到山”这样的说法搭配。", "高山": "语义：高山本身就是山，不能说“高山一眼看不到山”。"}, "sentence_index": 0, "correct_answer": "平原"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "草地的尽头有一座平原。", "explanation": "量词“座”用于山、楼等，平原应用〈片〉。"}, {"text": "平原上的山峰一个接一个，连绵不断。", "explanation": "这里应该用〈山区〉。平原没有山，不能说平原上有连绵的山峰。"}, {"text": "他爬上平原，俯瞰整个城市。", "explanation": "这里应该用〈高塔〉。“爬上”指向高处，平原平坦，不能说爬上平原。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26770, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平原", "is_correct": true, "explanation": "正确答案。“他从小住在平原，没见过高山”符合平原地区没有高山的情况。"}, {"text": "山村", "is_correct": false, "explanation": "语义：山村位于山中，住在那里常能看见高山，与“没见过高山”矛盾。"}, {"text": "峡谷", "is_correct": false, "explanation": "语义：峡谷两侧是山壁，住在峡谷的人不可能没见过高山。"}, {"text": "雪山", "is_correct": false, "explanation": "语义：雪山本身就是高山，住在雪山的人不可能没见过高山，与句意矛盾。"}], "explanations": {"平原": "正确答案。“他从小住在平原，没见过高山”符合平原地区没有高山的情况。", "山村": "语义：山村位于山中，住在那里常能看见高山，与“没见过高山”矛盾。", "峡谷": "语义：峡谷两侧是山壁，住在峡谷的人不可能没见过高山。", "雪山": "语义：雪山本身就是高山，住在雪山的人不可能没见过高山，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "平原"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "屋前长着一棵平原。", "explanation": "量词“棵”用于树木，平原应用〈片〉。"}, {"text": "翻过平原，就能看到大海。", "explanation": "这里应该用〈高山〉。“翻过”需要有障碍，平原没有山，不能说翻过平原。"}, {"text": "他潜入平原寻找贝壳。", "explanation": "这里应该用〈海底〉。“潜入”指进入水下，平原是陆地，不能说潜入平原。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26770, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在一只平原上露营。", "corrected_sentence": "我们在一片平原上露营。", "error_description": "量词错误：「只」用于动物等，不能计量平原，平原应用量词「片」。正确说法是「一片平原」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26770, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "牧民们赶着羊群平原上走过。", "corrected_sentence": "牧民们赶着羊群从平原上走过。", "error_description": "缺少介词：表示经过某处要用「从……上走过」，「平原上」前应加「从」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
