INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26772, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "电的力量。", "primary_collocate": null, "pronunciation": "diàn lì", "ipa": "tjɛn˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "这个城市的电力很足。", "target_word": "电力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天晚上电力不够用。", "target_word": "电力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这辆车用电力，不用汽油。", "target_word": "电力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里的电力是从水电站来的。", "target_word": "电力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天用空调多，电力很紧张。", "target_word": "电力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人在修理电力设备。", "target_word": "电力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个村子终于能用上电力了。", "target_word": "电力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风可以变成电力。", "target_word": "电力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家工厂用了很多电力。", "target_word": "电力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有电力，电梯就不能用。", "target_word": "电力", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "电作为能源所提供的力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ac6ae9e-65f2-4cd8-afbe-fbecadfb9dc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26772, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "电力", "is_correct": true, "explanation": "正确：电力指电的力量，即供电的能力，与释义相符。"}, {"text": "店里", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，意思是在商店里面。"}, {"text": "典礼", "is_correct": false, "explanation": "diǎn（第三声）与 diàn（第四声）、lǐ（第三声）与 lì（第四声）声调都不同，意思是隆重的仪式。"}, {"text": "电离", "is_correct": false, "explanation": "lí（第二声）与 lì（第四声）声调不同，意思是物质分解成离子。"}], "explanations": {"电力": "正确：电力指电的力量，即供电的能力，与释义相符。", "店里": "lǐ（第三声）与 lì（第四声）声调不同，意思是在商店里面。", "典礼": "diǎn（第三声）与 diàn（第四声）、lǐ（第三声）与 lì（第四声）声调都不同，意思是隆重的仪式。", "电离": "lí（第二声）与 lì（第四声）声调不同，意思是物质分解成离子。"}, "sentence_index": null, "correct_answer": "电力"}, "level_3": {"options": [{"text": "电力", "is_correct": true, "explanation": "正确：电力指电的能量，“很足”说明供应充足，与句子相符。"}, {"text": "楼房", "is_correct": false, "explanation": "搭配：“楼房”说多少、高低，不说“很足”。"}, {"text": "水质", "is_correct": false, "explanation": "搭配：“水质”说好坏，不说“很足”。"}, {"text": "电线", "is_correct": false, "explanation": "语义：电线是导线，不是可以“足”的供应量。"}], "explanations": {"电力": "正确：电力指电的能量，“很足”说明供应充足，与句子相符。", "楼房": "搭配：“楼房”说多少、高低，不说“很足”。", "水质": "搭配：“水质”说好坏，不说“很足”。", "电线": "语义：电线是导线，不是可以“足”的供应量。"}, "sentence_index": 0, "correct_answer": "电力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的电力很大。", "explanation": "这里应该用〈力量〉。电力指电的能量，不能用来形容人的力气。"}, {"text": "他的电力很好。", "explanation": "这里应该用〈体力〉。电力指电能供应，不能用来说人的身体能力。"}, {"text": "孩子们的学习电力很大。", "explanation": "这里应该用〈压力〉。电力指电的能量，不能形容学习给人的心理负担。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26772, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电力", "is_correct": true, "explanation": "正确：“用上”后接供应的资源，“电力”与“终于能用上”相符。"}, {"text": "灵感", "is_correct": false, "explanation": "搭配：“用上”后接具体的设备或资源，“灵感”是抽象想法，一般不说“用上”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气人人都有，不说村子“终于能用上”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是可以“用上”的供应，不能和“终于能”搭配。"}], "explanations": {"电力": "正确：“用上”后接供应的资源，“电力”与“终于能用上”相符。", "灵感": "搭配：“用上”后接具体的设备或资源，“灵感”是抽象想法，一般不说“用上”。", "空气": "语义：空气人人都有，不说村子“终于能用上”。", "石头": "语义：石头不是可以“用上”的供应，不能和“终于能”搭配。"}, "sentence_index": 6, "correct_answer": "电力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对工作的电力很足。", "explanation": "这里应该用〈干劲〉。电力指电的能量，不能用来形容人对工作的热情。"}, {"text": "他下定了电力。", "explanation": "这里应该用〈决心〉。“下定”搭配的是“决心”，电力指电的能量，不能用来表示人的意志。"}, {"text": "地球的电力很强。", "explanation": "这里应该用〈引力〉。电力指电的能量，不能用来说地球对物体的吸引。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26772, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小村子终于有了一个稳定的电力。", "corrected_sentence": "这个小村子终于有了稳定的电力。", "error_description": "量词错误：“电力”是不可数名词，不能用“一个”修饰。正确说法是“终于有了稳定的电力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26772, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这里的电力们很充足。", "corrected_sentence": "这里的电力很充足。", "error_description": "加词错误：“电力”是不可数的抽象名词，不能加“们”表示复数。正确说法是“这里的电力很充足”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26774, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "骤然", "is_correct": true, "explanation": "与“缓缓”形成反义：突然发生，与一点一点地渐变正好相反。"}, {"text": "轻轻", "is_correct": false, "explanation": "“轻轻”形容动作的轻柔，与渐变与否没有反义关系。"}, {"text": "悄悄", "is_correct": false, "explanation": "“悄悄”形容不让人察觉，与变化的快慢无关。"}, {"text": "偶尔", "is_correct": false, "explanation": "“偶尔”说的是频率，与渐变过程不构成反义。"}], "correct_answer": "骤然", "explanations": {"骤然": "与“缓缓”形成反义：突然发生，与一点一点地渐变正好相反。", "轻轻": "“轻轻”形容动作的轻柔，与渐变与否没有反义关系。", "悄悄": "“悄悄”形容不让人察觉，与变化的快慢无关。", "偶尔": "“偶尔”说的是频率，与渐变过程不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26774, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "骤然", "is_correct": true, "explanation": "与“缓缓”形成反义：突然发生，与一点一点地渐变正好相反。"}, {"text": "轻声", "is_correct": false, "explanation": "“轻声”说的是声音的大小，与变化的快慢无关。"}, {"text": "连连", "is_correct": false, "explanation": "“连连”表示接连不断，说的是次数，与渐变过程不构成反义。"}, {"text": "默默", "is_correct": false, "explanation": "“默默”形容不声不响，与变化的快慢无关。"}], "correct_answer": "骤然", "explanations": {"骤然": "与“缓缓”形成反义：突然发生，与一点一点地渐变正好相反。", "轻声": "“轻声”说的是声音的大小，与变化的快慢无关。", "连连": "“连连”表示接连不断，说的是次数，与渐变过程不构成反义。", "默默": "“默默”形容不声不响，与变化的快慢无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26774, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "property", "definition": "慢慢地，一点点地动或者变化。", "primary_collocate": null, "pronunciation": "huǎn huǎn", "ipa": "xwan˨˩˦ xwan˨˩˦", "syllable_count": 2, "sentences": [{"text": "月亮缓缓移动。", "target_word": "缓缓", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "雾缓缓散开。", "target_word": "缓缓", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "水位缓缓上升。", "target_word": "缓缓", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "云在天上缓缓地飘。", "target_word": "缓缓", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天缓缓黑了。", "target_word": "缓缓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "气温缓缓下降了。", "target_word": "缓缓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的病缓缓好转，一个月后就出院了。", "target_word": "缓缓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雪缓缓落在屋顶上，也落在树上。", "target_word": "缓缓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经济缓缓恢复，人们的生活也好起来。", "target_word": "缓缓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳把冰缓缓化成了水。", "target_word": "缓缓", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "一点一点地移动或变化（强调渐变过程）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c8e9f36-9d8f-4bd1-976d-30c7aefae07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26774, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "缓缓", "is_correct": true, "explanation": "“缓缓”表示一点一点地移动，与月亮慢慢移动的情景相合。"}, {"text": "一动不动", "is_correct": false, "explanation": "语义：“一动不动”表示静止，与“移动”的动态相矛盾。"}, {"text": "瞬间", "is_correct": false, "explanation": "语义：“瞬间”说转眼之间完成，与渐进的移动过程不符。"}, {"text": "倒着", "is_correct": false, "explanation": "搭配：月亮“倒着移动”不符合天体运行的常识，句子说不通。"}], "explanations": {"缓缓": "“缓缓”表示一点一点地移动，与月亮慢慢移动的情景相合。", "一动不动": "语义：“一动不动”表示静止，与“移动”的动态相矛盾。", "瞬间": "语义：“瞬间”说转眼之间完成，与渐进的移动过程不符。", "倒着": "搭配：月亮“倒着移动”不符合天体运行的常识，句子说不通。"}, "sentence_index": 0, "correct_answer": "缓缓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的手机缓缓碎了一地。", "explanation": "“缓缓”表示逐渐发生的变化，碎裂是瞬间完成的，不能这样用。"}, {"text": "灯泡缓缓爆炸了。", "explanation": "爆炸是瞬间的，不是一点一点的变化，“缓缓”在这里不适用。"}, {"text": "杯子缓缓摔在地上。", "explanation": "摔落是瞬间的动作，“缓缓”表示的渐变过程在这里不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26774, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缓缓", "is_correct": true, "explanation": "“缓缓”表示病情一点一点地好转，与“一个月后出院”的过程相合。"}, {"text": "拼命", "is_correct": false, "explanation": "搭配：病情是自然好转的，不能「拼命」好转；「拼命」指人主动用力，与病情变化不合。"}, {"text": "骤然", "is_correct": false, "explanation": "语义：“骤然”说突然发生，与渐进的好转不合。"}, {"text": "故意", "is_correct": false, "explanation": "搭配：病不会「故意」好转，「故意」指有意识地去做，与病情的自然变化不合。"}], "explanations": {"缓缓": "“缓缓”表示病情一点一点地好转，与“一个月后出院”的过程相合。", "拼命": "搭配：病情是自然好转的，不能「拼命」好转；「拼命」指人主动用力，与病情变化不合。", "骤然": "语义：“骤然”说突然发生，与渐进的好转不合。", "故意": "搭配：病不会「故意」好转，「故意」指有意识地去做，与病情的自然变化不合。"}, "sentence_index": 6, "correct_answer": "缓缓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的封面缓缓是红色的。", "explanation": "“缓缓”只用于动作或变化的过程，“是红色”是静态状态，不能搭配。"}, {"text": "他的考试成绩一夜之间缓缓提高了。", "explanation": "“缓缓”表示一点点的渐变，“一夜之间”表示极短时间内完成，二者的时间义相互矛盾，成绩的变化不是逐步发生的。"}, {"text": "门缓缓被一脚踢开。", "explanation": "踢开是瞬间动作，不是一点一点的变化，“缓缓”不适用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26774, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窗外的雪缓缓的停了。", "corrected_sentence": "窗外的雪缓缓停了。", "error_description": "“缓缓”是副词，直接修饰动词，中间不加“的”；错写成“缓缓的停”，应为“缓缓停了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26774, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜色很缓缓降临，天边渐渐暗了。", "corrected_sentence": "夜色缓缓降临，天边渐渐暗了。", "error_description": "“缓缓”是副词，本身已表示渐进的慢速，不能再受“很”修饰；错写成“很缓缓降临”，应删去“很”，为“缓缓降临”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26776, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暗淡无光", "is_correct": true, "explanation": "与“熠熠生辉”形成反义：光彩暗淡，没有光亮，正好相反。"}, {"text": "狭窄", "is_correct": false, "explanation": "“狭窄”形容空间的宽度，与光彩的明暗无关，不是反义词。"}, {"text": "潮湿", "is_correct": false, "explanation": "“潮湿”形容含水分多的状态，与光亮没有对立关系。"}, {"text": "温热", "is_correct": false, "explanation": "“温热”说的是温度，与“光彩闪耀”不构成反义。"}], "correct_answer": "暗淡无光", "explanations": {"暗淡无光": "与“熠熠生辉”形成反义：光彩暗淡，没有光亮，正好相反。", "狭窄": "“狭窄”形容空间的宽度，与光彩的明暗无关，不是反义词。", "潮湿": "“潮湿”形容含水分多的状态，与光亮没有对立关系。", "温热": "“温热”说的是温度，与“光彩闪耀”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26776, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暗淡无光", "is_correct": true, "explanation": "与“熠熠生辉”形成反义：光彩暗淡，没有光亮，正好相反。"}, {"text": "沉重", "is_correct": false, "explanation": "“沉重”形容重量或心情，与光彩的明暗无关，不是反义词。"}, {"text": "柔软", "is_correct": false, "explanation": "“柔软”形容质地，与光亮没有对立关系。"}, {"text": "迟钝", "is_correct": false, "explanation": "“迟钝”形容反应慢，与“光彩闪耀”不构成反义。"}], "correct_answer": "暗淡无光", "explanations": {"暗淡无光": "与“熠熠生辉”形成反义：光彩暗淡，没有光亮，正好相反。", "沉重": "“沉重”形容重量或心情，与光彩的明暗无关，不是反义词。", "柔软": "“柔软”形容质地，与光亮没有对立关系。", "迟钝": "“迟钝”形容反应慢，与“光彩闪耀”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26776, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "亮闪闪的，像星星一样发光。", "primary_collocate": null, "pronunciation": "yì yì shēng huī", "ipa": "i˥˩ i˥˩ ʂɤŋ˥ xweɪ˥", "syllable_count": 4, "sentences": [{"text": "夜里的海面熠熠生辉。", "target_word": "熠熠生辉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小河里的水熠熠生辉。", "target_word": "熠熠生辉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她的银首饰在灯下熠熠生辉。", "target_word": "熠熠生辉", "complexity_tier": "T3", "furigana": "tā de yín shǒushi zài dēng xià yì yì shēng huī", "sentence_source": "generated"}, {"text": "孩子的眼睛像星星，熠熠生辉。", "target_word": "熠熠生辉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河面上的灯光熠熠生辉，像星星一样。", "target_word": "熠熠生辉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下了雪，树上的冰熠熠生辉。", "target_word": "熠熠生辉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "王冠上的宝石在灯下熠熠生辉。", "target_word": "熠熠生辉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "草地上的露水在早上熠熠生辉。", "target_word": "熠熠生辉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "擦过以后，银杯熠熠生辉。", "target_word": "熠熠生辉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把铜钟擦得熠熠生辉。", "target_word": "熠熠生辉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "成语：亮闪闪、像星星般发光（强调一闪一闪）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c8e9f36-9d8f-4bd1-976d-30c7aefae07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26776, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "熠熠生辉", "is_correct": true, "explanation": "形容夜里海面反射出一闪一闪的亮光，与“夜里”的情境相合。"}, {"text": "滚烫", "is_correct": false, "explanation": "语义：夜里的海面不会是“滚烫”的，这样说与句中的情境相冲突。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：海面是水体，不能用“干燥”来形容。"}, {"text": "光秃秃", "is_correct": false, "explanation": "体貌：“光秃秃”多用于草木、山地的外观，不能用于海面。"}], "explanations": {"熠熠生辉": "形容夜里海面反射出一闪一闪的亮光，与“夜里”的情境相合。", "滚烫": "语义：夜里的海面不会是“滚烫”的，这样说与句中的情境相冲突。", "干燥": "语义：海面是水体，不能用“干燥”来形容。", "光秃秃": "体貌：“光秃秃”多用于草木、山地的外观，不能用于海面。"}, "sentence_index": 0, "correct_answer": "熠熠生辉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜晚的虫鸣熠熠生辉，很动听。", "explanation": "「熠熠生辉」指光亮，虫鸣是声音，不能这样形容。"}, {"text": "厨房里的饭香熠熠生辉。", "explanation": "「熠熠生辉」只形容光亮，饭香是气味，这里用错了。"}, {"text": "这碗粥的温度熠熠生辉。", "explanation": "温度是冷热的感受，不是光，「熠熠生辉」在这里不适用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26776, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "熠熠生辉", "is_correct": true, "explanation": "形容宝石在灯下闪闪发光，与王冠的华贵形象相合。"}, {"text": "破旧", "is_correct": false, "explanation": "语义：王冠上的宝石与“破旧”的意思矛盾，句子要表达的是光彩。"}, {"text": "粗糙", "is_correct": false, "explanation": "体貌：表面粗糙的宝石不会在灯下闪光，这样描写与句意不符。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”与“在灯下”的干亮景象相矛盾。"}], "explanations": {"熠熠生辉": "形容宝石在灯下闪闪发光，与王冠的华贵形象相合。", "破旧": "语义：王冠上的宝石与“破旧”的意思矛盾，句子要表达的是光彩。", "粗糙": "体貌：表面粗糙的宝石不会在灯下闪光，这样描写与句意不符。", "潮湿": "语义：“潮湿”与“在灯下”的干亮景象相矛盾。"}, "sentence_index": 6, "correct_answer": "熠熠生辉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的叹息熠熠生辉，让屋子里安静下来。", "explanation": "「熠熠生辉」指光亮，叹息是声音，这里用错了对象。"}, {"text": "山谷里的回声熠熠生辉。", "explanation": "回声是声音，「熠熠生辉」描写的是光彩，属于错用。"}, {"text": "他的心跳熠熠生辉，很有力。", "explanation": "心跳是身体的节律，看不见，「熠熠生辉」只用于光亮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26776, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "湖面上的月光把熠熠生辉，很美。", "corrected_sentence": "湖面上的月光熠熠生辉，很美。", "error_description": "“把”字句误用：「熠熠生辉」是不及物的形容性词语，不能放在“把”后作动词，应说「湖面上的月光熠熠生辉，很美」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26776, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车灯照过，玻璃窗很熠熠生辉。", "corrected_sentence": "车灯照过，玻璃窗熠熠生辉。", "error_description": "程度副词“很”不能修饰「熠熠生辉」这类固定四字形容语，应说「车灯照过，玻璃窗熠熠生辉」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
