INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26778, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "环境压力就是周围的事情让人感到紧张或不开心。", "primary_collocate": null, "pronunciation": "huán jìng yā lì", "ipa": "xwan˧˥ tɕiŋ˥˩ ja˥ li˥˩", "syllable_count": 4, "sentences": [{"text": "新同事都很冷淡，我感到很大的环境压力。", "target_word": "环境压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公室里人人都加班，环境压力让我很紧张。", "target_word": "环境压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他搬到新学校，环境压力让他睡不好。", "target_word": "环境压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周围的同学都很努力，我有环境压力。", "target_word": "环境压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里总是吵架，孩子的环境压力很大。", "target_word": "环境压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她换了工作，环境压力使她不开心。", "target_word": "环境压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板一直看着大家，这种环境压力让人紧张。", "target_word": "环境压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居都很有钱，他觉得有环境压力。", "target_word": "环境压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在新城市，环境压力常常让我想家。", "target_word": "环境压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在比成绩，班里的环境压力很大。", "target_word": "环境压力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "環境壓力", "label": "繁体"}], "register": "中性", "sense_fingerprint": "周围的人和事让人紧张、不开心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71b48025-77bf-4b1a-941e-4f378a784baf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26778, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "环境压力", "is_correct": true, "explanation": "环境压力指周围的人和事让人紧张，与“新同事都很冷淡”的感受相符。"}, {"text": "能源危机", "is_correct": false, "explanation": "语义：能源危机是社会性的资源问题，不是个人可以感到的紧张。"}, {"text": "自然压力", "is_correct": false, "explanation": "语义：自然压力指自然界的负担，与同事之间的冷淡无关。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“感到很大的”后面不能接“温度”，温度不作为可以感受到的压力。"}], "explanations": {"环境压力": "环境压力指周围的人和事让人紧张，与“新同事都很冷淡”的感受相符。", "能源危机": "语义：能源危机是社会性的资源问题，不是个人可以感到的紧张。", "自然压力": "语义：自然压力指自然界的负担，与同事之间的冷淡无关。", "温度": "搭配：“感到很大的”后面不能接“温度”，温度不作为可以感受到的压力。"}, "sentence_index": 0, "correct_answer": "环境压力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张桌子的环境压力很高，放不下电脑。", "explanation": "这里应该用〈高度〉。环境压力指周围的事让人紧张，不能用来说桌子的高度。"}, {"text": "这台机器的环境压力太大，需要经常维修。", "explanation": "这里应该用〈负荷〉。环境压力指周围的事让人紧张或不开心，不能用来说机器的负荷。"}, {"text": "这块蛋糕的环境压力很好，大家都抢着吃。", "explanation": "这里应该用〈味道〉。环境压力指让人紧张的周围事物，不能用来说蛋糕的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26778, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "环境压力", "is_correct": true, "explanation": "环境压力指周围的环境让人紧张，与“这种……让人紧张”的语境相符。"}, {"text": "香味", "is_correct": false, "explanation": "语义：香味令人放松，不会让人紧张，“这种香味让人紧张”句意不通。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：阳光不是老板注视大家造成的紧张来源，“这种阳光让人紧张”句意不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：体重不作为让人紧张的原因，不说“这种体重让人紧张”。"}], "explanations": {"环境压力": "环境压力指周围的环境让人紧张，与“这种……让人紧张”的语境相符。", "香味": "语义：香味令人放松，不会让人紧张，“这种香味让人紧张”句意不通。", "阳光": "语义：阳光不是老板注视大家造成的紧张来源，“这种阳光让人紧张”句意不通。", "体重": "搭配：体重不作为让人紧张的原因，不说“这种体重让人紧张”。"}, "sentence_index": 6, "correct_answer": "环境压力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条路的环境压力很宽，能走三辆车。", "explanation": "这里应该用〈宽度〉。环境压力指周围的事让人紧张，不能用来说路的宽度。"}, {"text": "这条河的环境压力很长，流到了大海里。", "explanation": "这里应该用〈长度〉。环境压力指周围的事让人紧张，不能用来说河流的长度。"}, {"text": "这幅画的环境压力很鲜艳，挂在墙上很好看。", "explanation": "这里应该用〈色彩〉。环境压力指让人紧张的周围事物，不能用来形容画的颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26778, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新公司的氛围很紧张，我感到一只很大的环境压力。", "corrected_sentence": "新公司的氛围很紧张，我感到一种很大的环境压力。", "error_description": "量词错误。“环境压力”不用量词“只”，应说“一种环境压力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26778, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份工作有一座环境压力，让我想换个地方。", "corrected_sentence": "这份工作有一种环境压力，让我想换个地方。", "error_description": "量词错误。“环境压力”不用量词“座”，应说“一种环境压力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
