INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26782, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "像小鸟一样跳起来飞。", "primary_collocate": null, "pronunciation": "fēi yuè", "ipa": "fei˥ yɛ˥˩", "syllable_count": 2, "sentences": [{"text": "小鸟从树枝飞跃到另一棵树上。", "target_word": "飞跃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一只麻雀飞跃过矮墙。", "target_word": "飞跃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟轻轻一跳，飞跃到了窗台上。", "target_word": "飞跃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟看到猫，马上飞跃到高处。", "target_word": "飞跃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟飞跃过小河，到了对岸。", "target_word": "飞跃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸽子飞跃过篱笆，落进院子里。", "target_word": "飞跃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "麻雀飞跃上屋顶，叽叽地叫。", "target_word": "飞跃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟从地上飞跃到桌子上吃米。", "target_word": "飞跃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟儿飞跃过水沟，不怕弄湿脚。", "target_word": "飞跃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟飞跃过石头，往树林里去了。", "target_word": "飞跃", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "飞跃了", "label": "体标"}, {"form": "飞跃过", "label": "体标"}, {"form": "飛躍", "label": "繁体"}], "register": "中性", "sense_fingerprint": "本义：小鸟跳起来飞过去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71b48025-77bf-4b1a-941e-4f378a784baf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26782, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "飞跃", "is_correct": true, "explanation": "飞跃指小鸟跳起来飞过去，与“从树枝到另一棵树上”的动作相符。"}, {"text": "漂浮", "is_correct": false, "explanation": "语义：漂浮指随水或空气浮动，不能表示小鸟有目的地移动到另一棵树。"}, {"text": "游", "is_correct": false, "explanation": "语义：游指在水中或水面行进，与小鸟在树间移动的情景不符。"}, {"text": "跑", "is_correct": false, "explanation": "语义：跑指用腿快速行进，句中的小鸟是飞到另一棵树上，“跑到另一棵树上”句意不通。"}], "explanations": {"飞跃": "飞跃指小鸟跳起来飞过去，与“从树枝到另一棵树上”的动作相符。", "漂浮": "语义：漂浮指随水或空气浮动，不能表示小鸟有目的地移动到另一棵树。", "游": "语义：游指在水中或水面行进，与小鸟在树间移动的情景不符。", "跑": "语义：跑指用腿快速行进，句中的小鸟是飞到另一棵树上，“跑到另一棵树上”句意不通。"}, "sentence_index": 0, "correct_answer": "飞跃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头太重了，飞跃不起来。", "explanation": "这里应该用〈搬〉。飞跃指小鸟跳起来飞过去，石头不会飞，应说“搬不起来”。"}, {"text": "小鸟在天空中飞跃了一整天。", "explanation": "这里应该用〈飞行〉。飞行指持续地在空中飞，飞跃指一下子跳过去，不能说飞了一整天。"}, {"text": "他在大街上飞跃了一圈，见人就打招呼。", "explanation": "这里应该用〈走〉。飞跃指像小鸟一样跳起来飞过去，不能用来说在街上走一圈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26782, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "飞跃", "is_correct": true, "explanation": "飞跃指麻雀跳起来飞过去，与“上屋顶”的动作相符。"}, {"text": "跌", "is_correct": false, "explanation": "语义：跌指摔落，与麻雀主动跳上屋顶的动作相反。"}, {"text": "滚", "is_correct": false, "explanation": "语义：滚指翻转打滚，不能表示麻雀跳上屋顶。"}, {"text": "滑", "is_correct": false, "explanation": "搭配：滑多指在平面上滑行，不说鸟“滑上屋顶”。"}], "explanations": {"飞跃": "飞跃指麻雀跳起来飞过去，与“上屋顶”的动作相符。", "跌": "语义：跌指摔落，与麻雀主动跳上屋顶的动作相反。", "滚": "语义：滚指翻转打滚，不能表示麻雀跳上屋顶。", "滑": "搭配：滑多指在平面上滑行，不说鸟“滑上屋顶”。"}, "sentence_index": 6, "correct_answer": "飞跃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汽车在公路上飞跃，很快就到了。", "explanation": "这里应该用〈飞驰〉。飞驰指快速行驶，飞跃指跳跃式越过，不用于汽车在路上行驶。"}, {"text": "孩子在操场上飞跃，跑得很快。", "explanation": "这里应该用〈飞奔〉。飞奔指快跑，飞跃指跳起来越过，不用于一般的快跑。"}, {"text": "树叶从树上飞跃下来，落在地上。", "explanation": "这里应该用〈飘落〉。飘落指轻轻地落下，飞跃指一下子跳过去，不说树叶飞跃下来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26782, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只麻雀从屋顶飞跃了过院墙，落在树上。", "corrected_sentence": "一只麻雀从屋顶飞跃过院墙，落在树上。", "error_description": "错误在多出的“了”：“了”不能放在“过”之前，应删去“了”，说“飞跃过院墙”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26782, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "白鸽飞跃着过矮墙，落在屋檐上。", "corrected_sentence": "白鸽飞跃过矮墙，落在屋檐上。", "error_description": "体标错误：“飞跃过篱笆”是一下子完成的动作，不能用表示持续的“着”，应删去“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
