INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26784, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过渠道或努力取得信息、资料、利益等。", "primary_collocate": null, "pronunciation": "huò qǔ", "ipa": "xwɔ˥˩ tɕʰy˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们可以从网上获取信息。", "target_word": "获取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想获取更多的知识。", "target_word": "获取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生可以在图书馆获取资料。", "target_word": "获取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些数据可以从公开渠道获取。", "target_word": "获取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要获取这个文件，需要密码。", "target_word": "获取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者从警察那里获取了消息。", "target_word": "获取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想通过努力获取更多的支持。", "target_word": "获取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份资料可以免费获取。", "target_word": "获取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司靠广告获取利润。", "target_word": "获取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们没能获取任何帮助。", "target_word": "获取", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "获取了", "label": "体标"}, {"form": "获取过", "label": "体标"}], "register": "书面", "sense_fingerprint": "取得信息、知识、利益等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d78632b-8856-4b08-affc-b5331421b71a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26784, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "获取", "is_correct": true, "explanation": "正确：“获取”指通过渠道取得，与“从网上”和“信息”搭配。"}, {"text": "丢失", "is_correct": false, "explanation": "语义：“丢失”是失去，与“可以从网上”取得的语境相反。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”只接食物，不接“信息”。"}, {"text": "关闭", "is_correct": false, "explanation": "语义：“关闭”是停止开放，与“从网上”取得信息的动作相反。"}], "explanations": {"获取": "正确：“获取”指通过渠道取得，与“从网上”和“信息”搭配。", "丢失": "语义：“丢失”是失去，与“可以从网上”取得的语境相反。", "吃": "搭配：“吃”只接食物，不接“信息”。", "关闭": "语义：“关闭”是停止开放，与“从网上”取得信息的动作相反。"}, "sentence_index": 0, "correct_answer": "获取"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在冬天获取了感冒。", "explanation": "这里应该用〈得〉。得病要说“得”，“获取”指取得可以得到的东西，不用于疾病。"}, {"text": "这次实验获取了成功。", "explanation": "这里应该用〈取得〉。“取得成功”是固定搭配，“获取”不接“成功”。"}, {"text": "他昨天在路上获取了一个跟头。", "explanation": "这里应该用〈摔〉。摔跟头要用“摔”，“获取”指取得信息、资料或利益，不能用于意外动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26784, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "获取", "is_correct": true, "explanation": "正确：“获取”指取得，与“通过努力”和“支持”搭配。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”是不接受，与“想通过努力”的目标相反。"}, {"text": "消灭", "is_correct": false, "explanation": "搭配：“消灭”接敌人、问题等，不接“支持”。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”是不再争取，与“通过努力”的目的矛盾。"}], "explanations": {"获取": "正确：“获取”指取得，与“通过努力”和“支持”搭配。", "拒绝": "语义：“拒绝”是不接受，与“想通过努力”的目标相反。", "消灭": "搭配：“消灭”接敌人、问题等，不接“支持”。", "放弃": "语义：“放弃”是不再争取，与“通过努力”的目的矛盾。"}, "sentence_index": 6, "correct_answer": "获取"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们队获取了这场比赛。", "explanation": "这里应该用〈赢得〉。比赛的胜负要用“赢得”，“获取”多用于信息和资料。"}, {"text": "他终于获取了早起的好习惯。", "explanation": "这里应该用〈养成〉。习惯要说“养成”，“获取”指取得可以得到的东西。"}, {"text": "夏天的午后，我们获取了一场大雨。", "explanation": "这里应该用〈下〉。下大雨要用“下”，“获取”指取得信息、资料或利益，不能用于天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26784, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校可以免费获取了这份软件。", "corrected_sentence": "学校可以免费获取这份软件。", "error_description": "“可以”表示许可或可能，与表示完成的“了”不能同用：应说“可以免费获取这份软件”，不说“可以免费获取了这份软件”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26784, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他正在努力获取了更多资料。", "corrected_sentence": "他正在努力获取更多资料。", "error_description": "“正在”表示动作进行中，不和“了”同用：应说“正在努力获取”，不说“正在努力获取了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
