INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26788, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26788, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "装置是机器或工具上用来做某件事的部件。", "primary_collocate": null, "pronunciation": "zhuāng zhì", "ipa": "ʈʂwaŋ˥ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "洗衣机上有一个自动断电装置。", "target_word": "装置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车有一个防盗装置。", "target_word": "装置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空调的定时装置坏了，所以不会自己关。", "target_word": "装置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机里的这个装置可以记录你走了多少步。", "target_word": "装置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门上装着一个小装置，一开门就会响。", "target_word": "装置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器上的安全装置一定不能拆掉。", "target_word": "装置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台相机有防抖装置，拍出的照片很清楚。", "target_word": "装置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把电视的散热装置修好了。", "target_word": "装置", "complexity_tier": "T3", "furigana": "tā bǎ diànshì de sànrè zhuāngzhì xiū hǎo le", "sentence_source": "generated"}, {"text": "烤箱里有控温装置，所以温度不会太高。", "target_word": "装置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个加热装置只用来烧水。", "target_word": "装置", "complexity_tier": "T3", "furigana": "zhè ge jiārè zhuāngzhì zhǐ yònglái shāo shuǐ", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "裝置", "label": "繁体"}], "register": "中性", "sense_fingerprint": "机器或工具上负责某项具体功能的部件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71b48025-77bf-4b1a-941e-4f378a784baf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26788, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "装置", "is_correct": true, "explanation": "装置指机器或工具上负责某项功能的部件，是所听到的词。"}, {"text": "壮志", "is_correct": false, "explanation": "壮志（zhuàng zhì）与装置（zhuāng zhì）第一音节声调不同，意思是远大的志向。"}, {"text": "专制", "is_correct": false, "explanation": "专制（zhuān zhì）与装置（zhuāng zhì）韵母不同（an/ang），意思是独断统治。"}, {"text": "状纸", "is_correct": false, "explanation": "声调：状纸（zhuàng zhǐ）与装置（zhuāng zhì）两个音节声调都不同，意思是诉状。"}], "explanations": {"装置": "装置指机器或工具上负责某项功能的部件，是所听到的词。", "壮志": "壮志（zhuàng zhì）与装置（zhuāng zhì）第一音节声调不同，意思是远大的志向。", "专制": "专制（zhuān zhì）与装置（zhuāng zhì）韵母不同（an/ang），意思是独断统治。", "状纸": "声调：状纸（zhuàng zhǐ）与装置（zhuāng zhì）两个音节声调都不同，意思是诉状。"}, "sentence_index": null, "correct_answer": "装置"}, "level_3": {"options": [{"text": "装置", "is_correct": true, "explanation": "装置指机器上负责某项功能的部件，“洗衣机上的自动断电装置”语义通顺，是唯一能填入的词。"}, {"text": "小说", "is_correct": false, "explanation": "语义：洗衣机上不能有小说作为断电部件，“自动断电小说”语义不通。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不是机器部件，洗衣机上不可能有“自动断电河流”。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“自动断电”搭配的是部件或功能，“脾气”不能被断电，搭配不当。"}], "explanations": {"装置": "装置指机器上负责某项功能的部件，“洗衣机上的自动断电装置”语义通顺，是唯一能填入的词。", "小说": "语义：洗衣机上不能有小说作为断电部件，“自动断电小说”语义不通。", "河流": "语义：河流不是机器部件，洗衣机上不可能有“自动断电河流”。", "脾气": "搭配：“自动断电”搭配的是部件或功能，“脾气”不能被断电，搭配不当。"}, "sentence_index": 0, "correct_answer": "装置"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天玩手机装置。", "explanation": "这里应该用〈游戏〉。装置是机器上的部件，不能拿来玩；“玩”搭配的是“游戏”。"}, {"text": "晚上我们看了一部装置。", "explanation": "这里应该用〈电影〉。装置是机器部件，不是可以观看的作品，“看”的对象应是电影。"}, {"text": "妈妈做了一桌好吃的装置。", "explanation": "这里应该用〈菜〉。装置是机器上的部件，不能吃；“好吃的”应是菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26788, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "装置", "is_correct": true, "explanation": "装置指机器或工具上负责某项功能的部件，是所听到的词。"}, {"text": "专治", "is_correct": false, "explanation": "专治（zhuān zhì）与装置（zhuāng zhì）韵母不同（an/ang），意思是专门医治。"}, {"text": "壮志", "is_correct": false, "explanation": "声调：壮志（zhuàng zhì）与装置（zhuāng zhì）只有第一个音节声调不同（第四声与第一声），意思是远大的志向。"}, {"text": "庄子", "is_correct": false, "explanation": "庄子（zhuāng zǐ）与装置（zhuāng zhì）第一音节相同，第二音节声母和声调不同，指古代思想家。"}], "explanations": {"装置": "装置指机器或工具上负责某项功能的部件，是所听到的词。", "专治": "专治（zhuān zhì）与装置（zhuāng zhì）韵母不同（an/ang），意思是专门医治。", "壮志": "声调：壮志（zhuàng zhì）与装置（zhuāng zhì）只有第一个音节声调不同（第四声与第一声），意思是远大的志向。", "庄子": "庄子（zhuāng zǐ）与装置（zhuāng zhì）第一音节相同，第二音节声母和声调不同，指古代思想家。"}, "sentence_index": null, "correct_answer": "装置"}, "level_3": {"options": [{"text": "装置", "is_correct": true, "explanation": "装置指机器上负责某项功能的部件，“相机的防抖装置”语义通顺，是唯一能填入的词。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：相机上不可能有“防抖饭菜”这样的部件，句子语义不通。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘不是相机的部件，“相机有防抖窗帘”语义不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“防抖”针对的是相机的镜头或机身，“体重”与之不搭配。"}], "explanations": {"装置": "装置指机器上负责某项功能的部件，“相机的防抖装置”语义通顺，是唯一能填入的词。", "饭菜": "语义：相机上不可能有“防抖饭菜”这样的部件，句子语义不通。", "窗帘": "语义：窗帘不是相机的部件，“相机有防抖窗帘”语义不通。", "体重": "搭配：“防抖”针对的是相机的镜头或机身，“体重”与之不搭配。"}, "sentence_index": 6, "correct_answer": "装置"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的装置很好，每次考试都是第一名。", "explanation": "这里应该用〈头脑〉。装置是机器上的部件，不指人的头脑或天赋；形容人聪明应说“头脑好”。"}, {"text": "他穿了一件新装置。", "explanation": "这里应该用〈衣服〉。装置是机器部件，不能穿在身上，“穿”的对象应是衣服。"}, {"text": "他钓到了一条大装置。", "explanation": "这里应该用〈鱼〉。装置是机器部件，不是可以钓到的东西，应说“钓到一条大鱼”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26788, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台洗碗机有一条定时装置。", "corrected_sentence": "这台洗碗机有一个定时装置。", "error_description": "量词错误：装置是部件，应说“一个定时装置”；“条”用于细长的东西，不能用于装置。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26788, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "烤箱里有一条控温装置。", "corrected_sentence": "烤箱里有一个控温装置。", "error_description": "量词错误：装置是部件，应说“一个控温装置”；“条”用于细长的东西，不能用于装置。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
