INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26790, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "磨坊是磨面粉的地方。", "primary_collocate": null, "pronunciation": "mò fáng", "ipa": "mwo˥˩ faŋ˧˥", "syllable_count": 2, "sentences": [{"text": "农民把小麦送进了磨坊。", "target_word": "磨坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "磨坊在河边，旁边有一个大水车。", "target_word": "磨坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时在磨坊里磨过玉米。", "target_word": "磨坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "磨坊里的石磨很重，一个人推不动。", "target_word": "磨坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家磨坊每天都磨很多面粉。", "target_word": "磨坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们参观了一座有两百年历史的磨坊。", "target_word": "磨坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "磨坊的屋顶上落满了白色的面粉。", "target_word": "磨坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们喜欢在磨坊前看水车转动。", "target_word": "磨坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个磨坊用马拉石磨来磨麦子。", "target_word": "磨坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "磨坊老板说今年的小麦特别好。", "target_word": "磨坊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}], "register": "中性", "sense_fingerprint": "磨面粉的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '851baa46-0c4d-405d-9c2e-d5933994bbc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26790, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "磨坊", "is_correct": true, "explanation": "磨坊：磨面粉的地方，小麦可以送进去加工，与句意相符。"}, {"text": "钟表", "is_correct": false, "explanation": "语义：钟表不是加工谷物的地方，“送进钟表”说不通。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是上课的地方，农民不会把小麦送进教室。"}, {"text": "诗歌", "is_correct": false, "explanation": "搭配：“送进”要接具体的地点，不能说送进诗歌。"}], "explanations": {"磨坊": "磨坊：磨面粉的地方，小麦可以送进去加工，与句意相符。", "钟表": "语义：钟表不是加工谷物的地方，“送进钟表”说不通。", "教室": "语义：教室是上课的地方，农民不会把小麦送进教室。", "诗歌": "搭配：“送进”要接具体的地点，不能说送进诗歌。"}, "sentence_index": 0, "correct_answer": "磨坊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家磨坊每天烤出几十炉面包。", "explanation": "这里应该用〈面包房〉。磨坊只磨面粉，烤面包要用〈面包房〉。"}, {"text": "这家磨坊的酿酒师傅经验很丰富。", "explanation": "这里应该用〈酒坊〉。磨坊不酿酒，酿酒的地方要说〈酒坊〉。"}, {"text": "村东头有一座磨坊，大家都去那里修自行车。", "explanation": "这里应该用〈修车铺〉。磨坊是磨面粉的地方，修车要去〈修车铺〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b8024f-b22b-4953-93e5-eab38a007145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26790, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "磨坊", "is_correct": true, "explanation": "磨坊：磨面粉的地方，屋顶落满面粉，与句意相符。"}, {"text": "教堂", "is_correct": false, "explanation": "语义：教堂不是磨面粉的地方，句中屋顶落满面粉说不通。"}, {"text": "书店", "is_correct": false, "explanation": "语义：书店里没有面粉，屋顶上不会落满白色的面粉。"}, {"text": "飞机", "is_correct": false, "explanation": "搭配：“飞机的屋顶上落满面粉”不合常理，应指储存或加工面粉的建筑。"}], "explanations": {"磨坊": "磨坊：磨面粉的地方，屋顶落满面粉，与句意相符。", "教堂": "语义：教堂不是磨面粉的地方，句中屋顶落满面粉说不通。", "书店": "语义：书店里没有面粉，屋顶上不会落满白色的面粉。", "飞机": "搭配：“飞机的屋顶上落满面粉”不合常理，应指储存或加工面粉的建筑。"}, "sentence_index": 6, "correct_answer": "磨坊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家磨坊每天榨出几百斤菜籽油。", "explanation": "这里应该用〈油坊〉。磨坊磨面粉，榨油要用〈油坊〉。"}, {"text": "这家磨坊每天编很多竹器。", "explanation": "这里应该用〈作坊〉。磨坊只磨面粉，编竹器要用〈作坊〉。"}, {"text": "这家磨坊每天熬出很多红糖。", "explanation": "这里应该用〈糖坊〉。磨坊加工谷物，熬制红糖要用〈糖坊〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b8024f-b22b-4953-93e5-eab38a007145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26790, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我小时候去过那只磨坊。", "corrected_sentence": "我小时候去过那座磨坊。", "error_description": "量词用错：磨坊是建筑，量词应用“座”；“只”用于动物或单个小件物品，不能用来数磨坊，应说“那座磨坊”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b8024f-b22b-4953-93e5-eab38a007145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26790, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农民磨坊门口等着磨面。", "corrected_sentence": "农民在磨坊门口等着磨面。", "error_description": "漏掉介词“在”：表示地点要说“在磨坊门口”，不能直接接在主语之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b8024f-b22b-4953-93e5-eab38a007145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
