INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26792, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "物体动起来带的能量。", "primary_collocate": null, "pronunciation": "dòng néng", "ipa": "tʊŋ˥˩ nɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "小球动起来，就有动能。", "target_word": "动能", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "车开得越快，动能越大。", "target_word": "动能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风吹着风车转，风车得到了动能。", "target_word": "动能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑自行车下坡时，车的动能越来越大。", "target_word": "动能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "动能大的东西，撞到人会很疼。", "target_word": "动能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "石头从山上滚下来，动能很大。", "target_word": "动能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水流有很大的动能，推动了小水车。", "target_word": "动能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球停了，球的动能就没有了。", "target_word": "动能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跑步的时候，我的身体有动能。", "target_word": "动能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩跑得快，动能比走路时大。", "target_word": "动能", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "东西动起来所带的能量，通俗说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbdf5e2f-210f-4716-b9b6-47323c31ed04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26792, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "动能", "is_correct": true, "explanation": "正确。小球运动起来，就具有动能。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不会因为运动而产生，“动起来就有颜色”与事实不符。"}, {"text": "味道", "is_correct": false, "explanation": "语义：小球动起来不会产生味道，这个说法不合理。"}, {"text": "疼痛", "is_correct": false, "explanation": "配价：“疼痛”需要有感觉的主体，小球没有感觉，不能说“就有疼痛”。"}], "explanations": {"动能": "正确。小球运动起来，就具有动能。", "颜色": "语义：颜色不会因为运动而产生，“动起来就有颜色”与事实不符。", "味道": "语义：小球动起来不会产生味道，这个说法不合理。", "疼痛": "配价：“疼痛”需要有感觉的主体，小球没有感觉，不能说“就有疼痛”。"}, "sentence_index": 0, "correct_answer": "动能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆电动车的电池里有很多动能。", "explanation": "这里应该用〈能量〉。电池里储存的是化学能，动能指运动物体的能量，不能说电池里有很多动能。"}, {"text": "我跑步的速度很快，动能也很快。", "explanation": "这里应该用〈速率〉。动能是能量的大小，只能说大或小，表示运动快慢的量要用速率，不能说动能快。"}, {"text": "这碗热汤的动能很大，喝了很暖和。", "explanation": "这里应该用〈热量〉。热汤的热度来自热量，动能只能表示运动物体的能量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e98ee5d-27a7-4a7a-841a-afebe2286d71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26792, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "动能", "is_correct": true, "explanation": "正确。水流具有动能，所以能推动小水车。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度本身不能推动物体，句中“推动了小水车”需要能量来承担。"}, {"text": "形状", "is_correct": false, "explanation": "语义：形状是事物的外观，不能推动小水车，句中“推动”需要能量。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不能直接推动小水车，这里的“推动”需要能量。"}], "explanations": {"动能": "正确。水流具有动能，所以能推动小水车。", "温度": "语义：温度本身不能推动物体，句中“推动了小水车”需要能量来承担。", "形状": "语义：形状是事物的外观，不能推动小水车，句中“推动”需要能量。", "声音": "语义：声音不能直接推动小水车，这里的“推动”需要能量。"}, "sentence_index": 6, "correct_answer": "动能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他跑了一个小时，动能还是很好。", "explanation": "这里应该用〈体力〉。动能指运动物体的能量，跑步后人还有没有力气要用体力。"}, {"text": "这杯水的动能很高，烫得不能喝。", "explanation": "这里应该用〈温度〉。水的冷热要用温度来说，动能指运动物体的能量。"}, {"text": "这座山的动能很高，有三千米。", "explanation": "这里应该用〈高度〉。山是静止的，没有动能，说山的高低要用高度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e98ee5d-27a7-4a7a-841a-afebe2286d71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26792, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他抛出去的铅球有很长的动能。", "corrected_sentence": "他抛出去的铅球有很大的动能。", "error_description": "形容词搭配错误：“动能”说的是能量的大小，应说“很大的动能”，不能用“长”来形容。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e98ee5d-27a7-4a7a-841a-afebe2286d71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26792, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小球从桌上滚落，获得了一只动能。", "corrected_sentence": "小球从桌上滚落，获得了一点动能。", "error_description": "量词错误：“动能”是抽象的量，数量常用“点”来计量；“只”多用于动物或单件器物，不用于抽象的能量。错误在于量词“只”，应为“一点动能”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e98ee5d-27a7-4a7a-841a-afebe2286d71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26794, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '888cb201-d78f-465b-b735-085f7336b91b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26794, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '888cb201-d78f-465b-b735-085f7336b91b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26794, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西弄成碎末或粉末。", "primary_collocate": null, "pronunciation": "niǎn mó", "ipa": "njɛn˨˩˦ mwo˧˥", "syllable_count": 2, "sentences": [{"text": "她用小石臼碾磨芝麻，香味很浓。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这些盐粒碾磨得更细一点。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸用工具碾磨干辣椒，做辣椒粉。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他碾磨过茶叶，会做抹茶。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心点，别把种子碾磨得太碎。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石头太硬，很难碾磨成粉末。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药片太大，请碾磨成粉再喝。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里有人在碾磨胡椒。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小机器专门用来碾磨香料。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人把豆子放在石碾上碾磨。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "碾磨了", "label": "完成体"}, {"form": "碾磨着", "label": "持续体"}, {"form": "碾磨过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "把香料、种子、石头等弄成碎末或粉末", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45c25686-c5ad-4d03-8fbd-51e08612bbaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26794, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "摘", "is_correct": false, "explanation": "语义：摘是采下果实或叶子，不能用小石臼完成。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮需要锅和水，小石臼不能用来煮芝麻。"}, {"text": "碾磨", "is_correct": true, "explanation": "碾磨：用石臼把芝麻压碎磨成粉，与“香味很浓”的结果相符。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”不能与固体的芝麻搭配。"}], "explanations": {"摘": "语义：摘是采下果实或叶子，不能用小石臼完成。", "煮": "语义：煮需要锅和水，小石臼不能用来煮芝麻。", "碾磨": "碾磨：用石臼把芝麻压碎磨成粉，与“香味很浓”的结果相符。", "喝": "搭配：“喝”不能与固体的芝麻搭配。"}, "sentence_index": 0, "correct_answer": "碾磨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把剪刀钝了，要碾磨一下才好用。", "explanation": "这里应该用〈磨〉。磨剪刀是使刃口变锋利，碾磨是把香料、种子压成粉末，剪刀不能这样处理。"}, {"text": "压路机把路面碾磨得很平整。", "explanation": "这里应该用〈碾压〉。碾压指用重物滚压使路面平整，碾磨指压成粉末，路面不会变成粉末。"}, {"text": "他每天碾磨一个小时的英语。", "explanation": "这里应该用〈练习〉。碾磨只能用于把实物弄成粉末，学英语要说“练习”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '888cb201-d78f-465b-b735-085f7336b91b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26794, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "切", "is_correct": false, "explanation": "语义：切只能把药片切成块，不能磨成细粉。"}, {"text": "碾磨", "is_correct": true, "explanation": "碾磨：压碎磨成粉，才能“再喝”，与“药片太大”的语境相符。"}, {"text": "洗", "is_correct": false, "explanation": "语义：洗不能把药片变成粉。"}, {"text": "站", "is_correct": false, "explanation": "配价：站是不及物动词，不能带宾语“药片”，也不能用于此结构。"}], "explanations": {"切": "语义：切只能把药片切成块，不能磨成细粉。", "碾磨": "碾磨：压碎磨成粉，才能“再喝”，与“药片太大”的语境相符。", "洗": "语义：洗不能把药片变成粉。", "站": "配价：站是不及物动词，不能带宾语“药片”，也不能用于此结构。"}, "sentence_index": 6, "correct_answer": "碾磨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶用擀面杖把面团碾磨成薄饼。", "explanation": "这里应该用〈擀〉。擀是用擀面杖把面团压成薄饼，碾磨是把东西压成粉末。"}, {"text": "不小心把水碾磨了。", "explanation": "这里应该用〈泼〉。水是液体，不能碾磨成粉，应说“泼”或“洒”。"}, {"text": "工人用砂纸把铁器碾磨得很光亮。", "explanation": "这里应该用〈抛光〉。抛光是使表面光滑发亮，碾磨是把东西压成粉末。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '888cb201-d78f-465b-b735-085f7336b91b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26794, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈用研钵把花椒碾磨了成粉。", "corrected_sentence": "妈妈用研钵把花椒碾磨成粉。", "error_description": "“了”位置错误：「碾磨了成粉」中“了”插在结果补语“成”之前，应去掉，正确为「碾磨成粉」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '888cb201-d78f-465b-b735-085f7336b91b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26794, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前碾磨着花椒，味道很香。", "corrected_sentence": "我以前碾磨过花椒，味道很香。", "error_description": "“着”用错。“以前”表示过去的经历，应用经历体标记“过”；“着”表示动作持续，与“以前”矛盾。正确形式为“碾磨过花椒”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '888cb201-d78f-465b-b735-085f7336b91b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
