INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26796, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26796, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "自然力是指大自然中存在的力量，比如风、雨水和太阳的热。", "primary_collocate": null, "pronunciation": "zì rán lì", "ipa": "tsɨ˥˩ ʐan˧˥ li˥˩", "syllable_count": 3, "sentences": [{"text": "大风和大雨都是自然力。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳的热是一种自然力。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自然力可以让风车转起来。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "流动的河水也是一种自然力。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的石头被自然力慢慢磨小了。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该尊重自然力。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自然力让种子发芽，长成大树。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台风是一种很强大的自然力。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人不能完全控制自然力。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人靠自然力晒盐。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "大自然中的力量，如风、雨水、太阳的热", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71b48025-77bf-4b1a-941e-4f378a784baf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26796, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自然力", "is_correct": true, "explanation": "自然力指大自然中的力量，风和雨正属于此类，是唯一能填入的词。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：大风和大雨不是桌子，“大风和大雨都是桌子”语义不通。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：大风和大雨不是诗歌，句子语义不通。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：大风和大雨不是电脑，“都是电脑”语义不通。"}], "explanations": {"自然力": "自然力指大自然中的力量，风和雨正属于此类，是唯一能填入的词。", "桌子": "语义：大风和大雨不是桌子，“大风和大雨都是桌子”语义不通。", "诗歌": "语义：大风和大雨不是诗歌，句子语义不通。", "电脑": "语义：大风和大雨不是电脑，“都是电脑”语义不通。"}, "sentence_index": 0, "correct_answer": "自然力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的自然力很大，一个人能搬动石头。", "explanation": "这里应该用〈力气〉。自然力指大自然的力量，不指人的力气。"}, {"text": "他忙了一整天，已经没有自然力了。", "explanation": "这里应该用〈精力〉。自然力指自然界的力量，不指人的精力。"}, {"text": "这位画家很有自然力，作品很多人喜欢。", "explanation": "这里应该用〈才华〉。自然力指自然界的力量，不指人的才华。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26796, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自然力", "is_correct": true, "explanation": "自然力指大自然中的力量，阳光、雨水等自然条件让种子发芽，正是这一意义，是唯一能填入的词。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室不能让种子发芽，“教室让种子发芽”语义不通。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不能让种子发芽，句子语义不通。"}, {"text": "螺丝", "is_correct": false, "explanation": "搭配：“让……发芽”需要水分、阳光等自然条件，“螺丝”与之不搭配。"}], "explanations": {"自然力": "自然力指大自然中的力量，阳光、雨水等自然条件让种子发芽，正是这一意义，是唯一能填入的词。", "教室": "语义：教室不能让种子发芽，“教室让种子发芽”语义不通。", "书包": "语义：书包不能让种子发芽，句子语义不通。", "螺丝": "搭配：“让……发芽”需要水分、阳光等自然条件，“螺丝”与之不搭配。"}, "sentence_index": 6, "correct_answer": "自然力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他靠自然力赢得了比赛。", "explanation": "这里应该用〈天赋〉。自然力指自然界的力量，不指人的天赋。"}, {"text": "他的自然力很强，队员们都服他。", "explanation": "这里应该用〈实力〉。自然力指自然界的力量，不指人的实力。"}, {"text": "这位老师傅的自然力很好，做的家具很精致。", "explanation": "这里应该用〈手艺〉。自然力指自然界的力量，不指人的手艺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26796, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一台自然力把水推向岸边。", "corrected_sentence": "一股自然力把水推向岸边。", "error_description": "量词错误：“自然力”是抽象的力量，应说“一股”；“台”用于机器，不能用来数自然力。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26796, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几种自然力们一起把这块石头磨小了。", "corrected_sentence": "几种自然力一起把这块石头磨小了。", "error_description": "错误形式：“自然力们”；正确形式：“自然力”。“们”只附在指人或有生命的名词后，抽象的“自然力”不能加“们”，数量已由“几种”表示，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26798, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7920bec-511e-4978-abf0-7c5fcd4f53ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26798, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7920bec-511e-4978-abf0-7c5fcd4f53ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26798, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "煤是一种黑色的石头，可以烧火取暖。", "primary_collocate": null, "pronunciation": "méi", "ipa": "mei˧˥", "syllable_count": 1, "sentences": [{"text": "冬天，奶奶在炉子里放了几块煤。", "target_word": "煤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "煤是黑色的，摸一下手就黑了。", "target_word": "煤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷家用煤烧火取暖。", "target_word": "煤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块煤很大，能烧一晚上。", "target_word": "煤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他蹲在地上捡煤。", "target_word": "煤", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小时候，我家的院子里堆着很多煤。", "target_word": "煤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "煤烧起来很热，但是烟很大。", "target_word": "煤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈买了一袋煤回家。", "target_word": "煤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有煤了，我们得去买一些。", "target_word": "煤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些煤放在门外，别弄脏地板。", "target_word": "煤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "袋", "label": "量词"}, {"form": "煤炭", "label": "复合"}, {"form": "煤油", "label": "复合"}], "register": "中性", "sense_fingerprint": "可以烧火取暖的黑色石头", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2be58e91-1e7c-48b9-beed-073729f7dde7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26798, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "煤", "is_correct": true, "explanation": "正确答案。听到的是“煤”（méi），指可以烧火取暖的黑色石头。"}, {"text": "妹", "is_correct": false, "explanation": "妹（mèi）与 méi 声调不同（第四声与第二声），意思是妹妹。"}, {"text": "美", "is_correct": false, "explanation": "美（měi）与 méi 声调不同（第三声与第二声），意思是美丽。"}, {"text": "门", "is_correct": false, "explanation": "门（mén）与 méi 韵母不同（en 与 ei），意思是门。"}], "explanations": {"煤": "正确答案。听到的是“煤”（méi），指可以烧火取暖的黑色石头。", "妹": "妹（mèi）与 méi 声调不同（第四声与第二声），意思是妹妹。", "美": "美（měi）与 méi 声调不同（第三声与第二声），意思是美丽。", "门": "门（mén）与 méi 韵母不同（en 与 ei），意思是门。"}, "sentence_index": null, "correct_answer": "煤"}, "level_3": {"options": [{"text": "煤", "is_correct": true, "explanation": "正确答案。“放了几块”后面要接烧火用的块状燃料，即“煤”。"}, {"text": "冰", "is_correct": false, "explanation": "语义：冰放进炉子里无法取暖，与“在炉子里”取暖的语境矛盾。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：玻璃一般不放进炉子里，与“炉子”和取暖的情境不搭配。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板不会放进炉子里，与冬天取暖的情景不符。"}], "explanations": {"煤": "正确答案。“放了几块”后面要接烧火用的块状燃料，即“煤”。", "冰": "语义：冰放进炉子里无法取暖，与“在炉子里”取暖的语境矛盾。", "玻璃": "搭配：玻璃一般不放进炉子里，与“炉子”和取暖的情境不搭配。", "黑板": "语义：黑板不会放进炉子里，与冬天取暖的情景不符。"}, "sentence_index": 0, "correct_answer": "煤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我渴了，想喝一杯煤。", "explanation": "这里应该用〈水〉。煤是烧火用的黑色石头，不能喝，口渴要喝〈水〉。"}, {"text": "妈妈用煤洗衣服。", "explanation": "这里应该用〈肥皂〉。煤会把衣服弄黑，洗衣服要用〈肥皂〉。"}, {"text": "冬天到了，山上下了很多煤。", "explanation": "这里应该用〈雪〉。天上下的是〈雪〉，煤不会从天上下来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7920bec-511e-4978-abf0-7c5fcd4f53ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26798, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "煤", "is_correct": true, "explanation": "正确答案。“烧起来很热，但是烟很大”描述的是煤这种燃料。"}, {"text": "水", "is_correct": false, "explanation": "语义：水不会烧起来，也不会冒烟，句子说的不是水。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：墨水不能烧，也不会“烧起来很热”。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“烧”需要燃料，不能说空气烧起来，与“烧”不搭配。"}], "explanations": {"煤": "正确答案。“烧起来很热，但是烟很大”描述的是煤这种燃料。", "水": "语义：水不会烧起来，也不会冒烟，句子说的不是水。", "墨水": "语义：墨水不能烧，也不会“烧起来很热”。", "空气": "搭配：“烧”需要燃料，不能说空气烧起来，与“烧”不搭配。"}, "sentence_index": 6, "correct_answer": "煤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗煤很好吃，我还想再吃一碗。", "explanation": "这里应该用〈米饭〉。煤不能吃，一碗好吃的东西应该是〈米饭〉。"}, {"text": "我用煤在本子上写作业。", "explanation": "这里应该用〈铅笔〉。写作业要用〈铅笔〉，煤是烧火用的。"}, {"text": "天黑了，请打开煤。", "explanation": "这里应该用〈灯〉。天黑了要开〈灯〉，煤不能打开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7920bec-511e-4978-abf0-7c5fcd4f53ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26798, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈又在炉子里加了一个煤。", "corrected_sentence": "妈妈又在炉子里加了一块煤。", "error_description": "“煤”是块状固体，应用量词“块”，不能说“一个煤”，应说“一块煤”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7920bec-511e-4978-abf0-7c5fcd4f53ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26798, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只煤要放在门外。", "corrected_sentence": "这块煤要放在门外。", "error_description": "“只”用于小动物或成对东西中的一个，煤是块状固体，不能用“只”计量，应改为“这块煤”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7920bec-511e-4978-abf0-7c5fcd4f53ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
