INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26802, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "乡村就是有很多田地和房子的地方，人们在那里种菜和养动物。", "primary_collocate": null, "pronunciation": "xiāng cūn", "ipa": "ɕjaŋ⁵⁵ tsʰwən⁵⁵", "syllable_count": 2, "sentences": [{"text": "乡村有很多田地和房子。", "target_word": "乡村", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "奶奶家在乡村，她种菜也养鸡。", "target_word": "乡村", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "乡村的早上很安静。", "target_word": "乡村", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们坐车去乡村看爷爷。", "target_word": "乡村", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "乡村里没有高楼，只有小房子。", "target_word": "乡村", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在乡村长大，会种菜。", "target_word": "乡村", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "乡村的路旁边是绿色的田。", "target_word": "乡村", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "住在乡村的人常常养动物。", "target_word": "乡村", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市很吵，乡村很安静。", "target_word": "乡村", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个周末我想去乡村玩。", "target_word": "乡村", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "乡村音乐", "label": "复合"}, {"form": "鄉村", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有田地和房子、人们种菜养动物的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2be58e91-1e7c-48b9-beed-073729f7dde7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26802, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "城市", "is_correct": false, "explanation": "语义：“城市”是人口密集的地方，与句中“有很多田地和房子”的描述不符。"}, {"text": "乡村", "is_correct": true, "explanation": "正确：“乡村”有很多田地和房子，符合句意。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：“工厂”是生产场所，不是以田地为主的地方，与句意冲突。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：“海洋”不是有田地和房子的地方，与句意不符。"}], "explanations": {"城市": "语义：“城市”是人口密集的地方，与句中“有很多田地和房子”的描述不符。", "乡村": "正确：“乡村”有很多田地和房子，符合句意。", "工厂": "语义：“工厂”是生产场所，不是以田地为主的地方，与句意冲突。", "海洋": "语义：“海洋”不是有田地和房子的地方，与句意不符。"}, "sentence_index": 0, "correct_answer": "乡村"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个乡村下午三点开了董事会。", "explanation": "这里应该用〈公司〉。“乡村”是地方，不会开董事会，开会的应是公司。"}, {"text": "这个乡村是国家的首都。", "explanation": "这里应该用〈首都〉。乡村指以农田和自然景观为主的地方，国家的政治中心要用〈首都〉。"}, {"text": "这个乡村的地铁站每天都很挤。", "explanation": "这里应该用〈城市〉。地铁和拥挤的车站是城市的特点，乡村以农田和自然景观为主。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7920bec-511e-4978-abf0-7c5fcd4f53ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26802, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "课本", "is_correct": false, "explanation": "语义：“课本”不是地方，不能有“路旁边”，句意不通。"}, {"text": "乡村", "is_correct": true, "explanation": "正确：“乡村”是有田地和房子、人们种菜养动物的地方，符合句意。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的房间，不是有田地的地方，与句意不符。"}, {"text": "牛奶", "is_correct": false, "explanation": "搭配：“牛奶”不是地方，不能与“的路旁边是绿色的田”搭配。"}], "explanations": {"课本": "语义：“课本”不是地方，不能有“路旁边”，句意不通。", "乡村": "正确：“乡村”是有田地和房子、人们种菜养动物的地方，符合句意。", "厨房": "语义：厨房是做饭的房间，不是有田地的地方，与句意不符。", "牛奶": "搭配：“牛奶”不是地方，不能与“的路旁边是绿色的田”搭配。"}, "sentence_index": 6, "correct_answer": "乡村"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "乡村都来帮忙盖房子。", "explanation": "这里应该用〈乡亲〉。“乡村”是地方，不能来帮忙，指村里的人要用〈乡亲〉。"}, {"text": "乡村都在操场上开会。", "explanation": "这里应该用〈村民〉。“乡村”是地方，不能开会，指村里的人要用〈村民〉。"}, {"text": "乡村都在厂里上班。", "explanation": "这里应该用〈工人〉。“乡村”是地方，不能上班，指干活的人要用〈工人〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7920bec-511e-4978-abf0-7c5fcd4f53ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26802, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只乡村有一条小河。", "corrected_sentence": "那个乡村有一条小河。", "error_description": "量词错误：“乡村”的量词是“个”，“只”用于动物，应改为“那个乡村”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7920bec-511e-4978-abf0-7c5fcd4f53ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26802, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想乡村住。", "corrected_sentence": "我想在乡村住。", "error_description": "介词缺失：表示地点的“乡村”前要加介词“在”，“乡村住”不成立，应说“在乡村住”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7920bec-511e-4978-abf0-7c5fcd4f53ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
