INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26808, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "自己和自己不矛盾，很合理。", "primary_collocate": null, "pronunciation": "zì qià", "ipa": "tsɨ˥˩ tɕʰja˥˩", "syllable_count": 2, "sentences": [{"text": "他说的话前后自洽，让人觉得可信。", "target_word": "自洽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套办法的逻辑很自洽，前后能对上，也很合理。", "target_word": "自洽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的想法很自洽，说话前后一样。", "target_word": "自洽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个理由不自洽，连他自己都说不通。", "target_word": "自洽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写小说时，人物的行为要自洽。", "target_word": "自洽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的计划看起来自洽，也很合理。", "target_word": "自洽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板的要求不自洽，又要快又要慢。", "target_word": "自洽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套规则很自洽，每条都不冲突。", "target_word": "自洽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要让你的说法自洽，先检查前后意思。", "target_word": "自洽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得他的解释自洽，没有明显问题。", "target_word": "自洽", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自洽性", "label": "复合"}], "register": "书面语", "sense_fingerprint": "说法、想法前后一致，自己不与自己矛盾，合情合理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a28e3c9-6de5-4ea0-9885-7603a65e2d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26808, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自洽", "is_correct": true, "explanation": "自洽：说法前后一致、没有矛盾，与“前后”和“让人觉得可信”相符"}, {"text": "清澈", "is_correct": false, "explanation": "语义：“清澈”形容水等透明的东西，不能用来说话前后的情况"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材或外形，说话没有形体，不能说“高大”"}, {"text": "狭窄", "is_correct": false, "explanation": "语义：“狭窄”指空间窄小，不能形容话语前后的情况"}], "explanations": {"自洽": "自洽：说法前后一致、没有矛盾，与“前后”和“让人觉得可信”相符", "清澈": "语义：“清澈”形容水等透明的东西，不能用来说话前后的情况", "高大": "体貌：“高大”形容身材或外形，说话没有形体，不能说“高大”", "狭窄": "语义：“狭窄”指空间窄小，不能形容话语前后的情况"}, "sentence_index": 0, "correct_answer": "自洽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这碗汤的味道很自洽。", "explanation": "这里应该用〈可口〉。自洽指说法或道理前后不矛盾，不用来形容食物的味道。"}, {"text": "同学之间相处得很自洽。", "explanation": "这里应该用〈融洽〉。自洽形容说法或理论内部没有矛盾，不用来形容人与人相处的关系"}, {"text": "这笔开销很自洽。", "explanation": "这里应该用〈合理〉。自洽强调内部逻辑一致，不用来评价开销是否合理"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edcde3de-1b60-425c-8b32-5d016f279331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26808, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自洽", "is_correct": true, "explanation": "自洽：这里用“不自洽”，指要求前后相互矛盾，与“又要快又要慢”的语境相符"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”形容味道，要求不能有咸淡，句意不通"}, {"text": "沉默", "is_correct": false, "explanation": "语义：“沉默”形容人不说话，要求本身不会沉默"}, {"text": "繁荣", "is_correct": false, "explanation": "搭配：“繁荣”多形容经济、城市，不用来形容要求"}], "explanations": {"自洽": "自洽：这里用“不自洽”，指要求前后相互矛盾，与“又要快又要慢”的语境相符", "咸": "语义：“咸”形容味道，要求不能有咸淡，句意不通", "沉默": "语义：“沉默”形容人不说话，要求本身不会沉默", "繁荣": "搭配：“繁荣”多形容经济、城市，不用来形容要求"}, "sentence_index": 6, "correct_answer": "自洽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间屋子的颜色很自洽。", "explanation": "这里应该用〈和谐〉。自洽指说法或体系内部没有矛盾，不用来形容颜色搭配是否协调"}, {"text": "车子开得很自洽。", "explanation": "这里应该用〈平稳〉。自洽不用来形容车辆行驶是否平稳"}, {"text": "这个社区很自洽，居民都自己管理事务。", "explanation": "这里应该用〈自治〉。自洽指自己和自己不矛盾，不表示“自己管理自己”，不能用来说社区的管理方式"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edcde3de-1b60-425c-8b32-5d016f279331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26808, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他提出的假设很自洽性，没有明显漏洞。", "corrected_sentence": "他提出的假设很自洽，没有明显漏洞。", "error_description": "错误：“很自洽性”。正确：“很自洽”。“自洽性”是名词，不能受程度副词“很”修饰，这里应用形容词“自洽”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edcde3de-1b60-425c-8b32-5d016f279331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26808, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他找到了一种自洽地说法，大家都能接受。", "corrected_sentence": "他找到了一种自洽的说法，大家都能接受。", "error_description": "错误：“自洽地”。正确：“自洽的”。“自洽”修饰名词“说法”时要用“的”，“地”只用于修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edcde3de-1b60-425c-8b32-5d016f279331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
