INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26818, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "燃料是可以烧的东西，用来让机器动起来或让东西变热。", "primary_collocate": null, "pronunciation": "rán liào", "ipa": "ɻan˧˥ liɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "木头、煤和油都可以当燃料。", "target_word": "燃料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车没有燃料就不能开。", "target_word": "燃料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "炉子里的燃料用完了，屋子越来越冷。", "target_word": "燃料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷把木柴当燃料，在院子里做饭。", "target_word": "燃料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机上要带够燃料。", "target_word": "燃料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小炉子用酒精做燃料。", "target_word": "燃料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "露营时，我们带了一袋燃料来烧水。", "target_word": "燃料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "燃料太贵了，他们很少开车。", "target_word": "燃料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种燃料烧起来没有烟。", "target_word": "燃料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船上的燃料只够再走一天。", "target_word": "燃料", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "可以燃烧、用来开动机器或加热的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71b48025-77bf-4b1a-941e-4f378a784baf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26818, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "燃料", "is_correct": true, "explanation": "正确：木头、煤和油都可以用来燃烧，属于燃料。"}, {"text": "食物", "is_correct": false, "explanation": "语义：木头、煤和油不是食物，“当食物”与句意不符。"}, {"text": "饲料", "is_correct": false, "explanation": "语义：饲料用于喂养牲畜，木头、煤和油不能当饲料。"}, {"text": "电线", "is_correct": false, "explanation": "搭配：“当电线”与“木头、煤和油”搭配不当，句子不通。"}], "explanations": {"燃料": "正确：木头、煤和油都可以用来燃烧，属于燃料。", "食物": "语义：木头、煤和油不是食物，“当食物”与句意不符。", "饲料": "语义：饲料用于喂养牲畜，木头、煤和油不能当饲料。", "电线": "搭配：“当电线”与“木头、煤和油”搭配不当，句子不通。"}, "sentence_index": 0, "correct_answer": "燃料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用燃料洗衣服。", "explanation": "这里应该用〈洗衣粉〉。燃料用于燃烧，不能用来洗衣服。"}, {"text": "这些燃料够全家吃一个冬天。", "explanation": "这里应该用〈粮食〉。燃料不能用来吃，粮食才够全家吃一个冬天。"}, {"text": "这种燃料可以治感冒。", "explanation": "这里应该用〈药材〉。燃料用于燃烧产生热能，不能用来治病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26818, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "燃料", "is_correct": true, "explanation": "正确：露营时带一袋燃料，才能用来烧水。"}, {"text": "食物", "is_correct": false, "explanation": "语义：食物不能用来烧水，句中“烧水”需要的是可燃物。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不是可燃物，“带一袋钥匙来烧水”语义不通。"}, {"text": "帐篷", "is_correct": false, "explanation": "语义：帐篷不是可燃物，不能用来烧水。"}], "explanations": {"燃料": "正确：露营时带一袋燃料，才能用来烧水。", "食物": "语义：食物不能用来烧水，句中“烧水”需要的是可燃物。", "钥匙": "语义：钥匙不是可燃物，“带一袋钥匙来烧水”语义不通。", "帐篷": "语义：帐篷不是可燃物，不能用来烧水。"}, "sentence_index": 6, "correct_answer": "燃料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅画用了红色的燃料。", "explanation": "这里应该用〈颜料〉。燃料用于燃烧，不能用来上色，画画用的是颜料。"}, {"text": "农场主用燃料养牛。", "explanation": "这里应该用〈饲料〉。燃料用于燃烧产生能量，不能用来喂养牲畜。"}, {"text": "工人用燃料盖房子。", "explanation": "这里应该用〈材料〉。燃料用于燃烧，盖房子需要的是建筑材料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26818, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农场买了一只燃料。", "corrected_sentence": "农场买了一袋燃料。", "error_description": "量词错误：燃料不用“只”来数，这里应改为“袋”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26818, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "叔叔去加油站买了一条燃料。", "corrected_sentence": "叔叔去加油站买了一桶燃料。", "error_description": "量词错误：装在桶里的燃料应说“一桶燃料”。“条”用于细长的东西，不能用于燃料。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0931a02d-49bb-4bc3-b09e-905f04bd468d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
