INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26820, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "出现在某处。", "primary_collocate": null, "pronunciation": "jiàn yú", "ipa": "tɕjɛn˥˩ y˧˥", "syllable_count": 2, "sentences": [{"text": "这种动物只见于热带森林。", "target_word": "见于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话见于今天的新闻。", "target_word": "见于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首诗见于《唐诗三百首》。", "target_word": "见于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个字见于最早的字典。", "target_word": "见于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样的树多见于北方。", "target_word": "见于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的作品见于很多杂志。", "target_word": "见于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种说法最早见于一本旧书。", "target_word": "见于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病多见于小孩。", "target_word": "见于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种建筑见于中国南方的小城。", "target_word": "见于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的名字见于比赛名单。", "target_word": "见于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "出现在某处或某种文献、场合中", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a28e3c9-6de5-4ea0-9885-7603a65e2d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id 