INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26820, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "见于", "is_correct": true, "explanation": "正确答案。见于（jiàn yú）：出现在某处或某种文献中。"}, {"text": "限于", "is_correct": false, "explanation": "xiàn 与 jiàn 声母不同（x 与 j），意思是局限在。"}, {"text": "将于", "is_correct": false, "explanation": "jiāng 与 jiàn 韵母与声调不同（ang 与 an，一声与四声），意思是将在。"}, {"text": "先于", "is_correct": false, "explanation": "xiān 与 jiàn 声母不同（x 与 j）且声调不同，意思是在……之前。"}], "explanations": {"见于": "正确答案。见于（jiàn yú）：出现在某处或某种文献中。", "限于": "xiàn 与 jiàn 声母不同（x 与 j），意思是局限在。", "将于": "jiāng 与 jiàn 韵母与声调不同（ang 与 an，一声与四声），意思是将在。", "先于": "xiān 与 jiàn 声母不同（x 与 j）且声调不同，意思是在……之前。"}, "sentence_index": null, "correct_answer": "见于"}, "level_3": {"options": [{"text": "见于", "is_correct": true, "explanation": "正确答案。“见于”表示只出现在某地，与“只”和“热带森林”搭配，句意通顺。"}, {"text": "毕业于", "is_correct": false, "explanation": "语义：毕业于要求人在学校完成学业，动物不能毕业。"}, {"text": "出版于", "is_correct": false, "explanation": "搭配：出版于常用于书籍，不能用于动物和森林。"}, {"text": "发表于", "is_correct": false, "explanation": "语义：发表于要求文章或研究成果作主语，动物不能被发表。"}], "explanations": {"见于": "正确答案。“见于”表示只出现在某地，与“只”和“热带森林”搭配，句意通顺。", "毕业于": "语义：毕业于要求人在学校完成学业，动物不能毕业。", "出版于": "搭配：出版于常用于书籍，不能用于动物和森林。", "发表于": "语义：发表于要求文章或研究成果作主语，动物不能被发表。"}, "sentence_index": 0, "correct_answer": "见于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天在车站见于一位老朋友。", "explanation": "这里应该用〈见到〉。见于不能带人作宾语，见到朋友应说“见到”。"}, {"text": "这座公园见于城东，人很多。", "explanation": "这里应该用〈位于〉。见于表示事物在某处出现或被看到，说地点的位置要用“位于”。"}, {"text": "明天的会议见于下午三点。", "explanation": "这里应该用〈定于〉。见于不用于安排时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edcde3de-1b60-425c-8b32-5d016f279331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26820, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "见于", "is_correct": true, "explanation": "正确答案。见于（jiàn yú）：出现在某处或某种文献中。"}, {"text": "江鱼", "is_correct": false, "explanation": "jiāng 与 jiàn 韵母与声调不同（ang 与 an），意思是江里的鱼。"}, {"text": "鲜鱼", "is_correct": false, "explanation": "xiān 与 jiàn 声母不同（x 与 j）且声调不同，意思是新鲜的鱼。"}, {"text": "陷于", "is_correct": false, "explanation": "xiàn 与 jiàn 声母不同（x 与 j），意思是落入（困境）。"}], "explanations": {"见于": "正确答案。见于（jiàn yú）：出现在某处或某种文献中。", "江鱼": "jiāng 与 jiàn 韵母与声调不同（ang 与 an），意思是江里的鱼。", "鲜鱼": "xiān 与 jiàn 声母不同（x 与 j）且声调不同，意思是新鲜的鱼。", "陷于": "xiàn 与 jiàn 声母不同（x 与 j），意思是落入（困境）。"}, "sentence_index": null, "correct_answer": "见于"}, "level_3": {"options": [{"text": "见于", "is_correct": true, "explanation": "正确答案。“见于”表示在某处（文献）出现，与“最早”和“一本旧书”搭配。"}, {"text": "出生于", "is_correct": false, "explanation": "语义：出生于要求人或动物作主语，说法不能出生。"}, {"text": "盛行于", "is_correct": false, "explanation": "搭配：盛行于常指风气或习俗在某地流行，不能指一本书。"}, {"text": "流行于", "is_correct": false, "explanation": "搭配：流行于多指风尚或事物在人群中传播，与“一本旧书”不搭。"}], "explanations": {"见于": "正确答案。“见于”表示在某处（文献）出现，与“最早”和“一本旧书”搭配。", "出生于": "语义：出生于要求人或动物作主语，说法不能出生。", "盛行于": "搭配：盛行于常指风气或习俗在某地流行，不能指一本书。", "流行于": "搭配：流行于多指风尚或事物在人群中传播，与“一本旧书”不搭。"}, "sentence_index": 6, "correct_answer": "见于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在路上见于了一只小狗。", "explanation": "这里应该用〈看见〉。见于表示事物出现在某处，不能表示人看到某物。"}, {"text": "她见于上海。", "explanation": "这里应该用〈出生〉。见于表示事物在某处出现或被看到，不表示人在某地出生。"}, {"text": "两国领导明天见于北京。", "explanation": "这里应该用〈会见〉。见于表示出现在某处，不表示正式与人会面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edcde3de-1b60-425c-8b32-5d016f279331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid,