INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26820, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个说法最早很见于先秦的典籍。", "corrected_sentence": "这个说法最早见于先秦的典籍。", "error_description": "错误：“最早很见于”。正确：“最早见于”。“很”是程度副词，不能修饰动词“见于”，应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edcde3de-1b60-425c-8b32-5d016f279331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26824, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "主动式", "is_correct": true, "explanation": "反义：被动式指等人推动、不主动做事，主动式指主动做事，二者相反"}, {"text": "河流", "is_correct": false, "explanation": "无关：“河流”是地理事物，与做事态度无关"}, {"text": "石头", "is_correct": false, "explanation": "无关：“石头”是自然物，与被动式没有反义关系"}, {"text": "星星", "is_correct": false, "explanation": "无关：“星星”是天体，与被动式没有反义关系"}], "correct_answer": "主动式", "explanations": {"主动式": "反义：被动式指等人推动、不主动做事，主动式指主动做事，二者相反", "河流": "无关：“河流”是地理事物，与做事态度无关", "石头": "无关：“石头”是自然物，与被动式没有反义关系", "星星": "无关：“星星”是天体，与被动式没有反义关系"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edcde3de-1b60-425c-8b32-5d016f279331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
