INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26824, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做事不主动，总等别人安排或推动的工作、处事方式。", "primary_collocate": null, "pronunciation": "bèi dòng shì", "ipa": "pei˥˩ tʊŋ˥˩ ʂɨ˥˩", "syllable_count": 3, "sentences": [{"text": "他的工作方式是被动式，总等别人安排。", "target_word": "被动式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "被动式的学习，只会等老师教。", "target_word": "被动式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她习惯了被动式的处事方式，总要别人替她拿主意。", "target_word": "被动式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想改变被动式的管理方法。", "target_word": "被动式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到问题时，他总是用被动式的办法，等人帮忙。", "target_word": "被动式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "被动式的人很少自己找事做。", "target_word": "被动式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做销售不能用被动式，要主动找客人。", "target_word": "被动式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们习惯了被动式的学习，不会自己想。", "target_word": "被动式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种被动式的态度，对工作没有帮助。", "target_word": "被动式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从被动式变成了主动式，进步很快。", "target_word": "被动式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "做事不主动，等别人安排、推动的方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a28e3c9-6de5-4ea0-9885-7603a65e2d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26824, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "被动式", "is_correct": true, "explanation": "被动式：指做事不主动、等别人安排推动的方式，与“总等别人安排”相符"}, {"text": "主动式", "is_correct": false, "explanation": "语义：“主动式”指主动做事，与“总等别人安排”正相矛盾"}, {"text": "自主式", "is_correct": false, "explanation": "语义：“自主式”指自己拿主意，与“总等别人安排”正相反"}, {"text": "手工式", "is_correct": false, "explanation": "搭配：“手工式”多指靠手工完成的生产方法，不用来说人的工作方式"}], "explanations": {"被动式": "被动式：指做事不主动、等别人安排推动的方式，与“总等别人安排”相符", "主动式": "语义：“主动式”指主动做事，与“总等别人安排”正相矛盾", "自主式": "语义：“自主式”指自己拿主意，与“总等别人安排”正相反", "手工式": "搭配：“手工式”多指靠手工完成的生产方法，不用来说人的工作方式"}, "sentence_index": 0, "correct_answer": "被动式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的处事方式是被动式，凡事都自己拿主意。", "explanation": "这里应该用〈自主式〉。被动式指等别人安排推动，句中“凡事都自己拿主意”是自主做事。"}, {"text": "他的做法是被动式，不等别人安排。", "explanation": "这里应该用〈主动式〉。句子说他不等别人安排，是主动做事，而被动式指等别人推动"}, {"text": "这种管理方式是一只被动式。", "explanation": "这里的量词不对。〈只〉用于动物等，被动式是做事方式，应该用〈种〉"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edcde3de-1b60-425c-8b32-5d016f279331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26824, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "被动式", "is_correct": true, "explanation": "被动式：指等人来找、不主动出击的做法，与“不能用”和“要主动找客人”形成对比"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“用”后接方法或手段，“天气”不能用作销售的方式"}, {"text": "咸味", "is_correct": false, "explanation": "语义：“咸味”是口味，不能用作销售的做法"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”是物体，不能作为销售的做法"}], "explanations": {"被动式": "被动式：指等人来找、不主动出击的做法，与“不能用”和“要主动找客人”形成对比", "天气": "搭配：“用”后接方法或手段，“天气”不能用作销售的方式", "咸味": "语义：“咸味”是口味，不能用作销售的做法", "石头": "语义：“石头”是物体，不能作为销售的做法"}, "sentence_index": 6, "correct_answer": "被动式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他总是主动找事做，工作方式是被动式。", "explanation": "这里应该用〈主动式〉。“总是主动找事做”与被动式“等别人安排”相矛盾。"}, {"text": "他的工作方式是一座被动式。", "explanation": "这里的量词不对。〈座〉用于山、楼房等大型固定物，被动式指做事方式，应该用〈种〉"}, {"text": "他的做事风格是一块被动式。", "explanation": "这里的量词不对。〈块〉用于块状的东西，被动式指做事方式，应该用〈种〉"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edcde3de-1b60-425c-8b32-5d016f279331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26824, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的工作习惯是一只被动式，总等别人安排。", "corrected_sentence": "他的工作习惯是一种被动式，总等别人安排。", "error_description": "错误：“一只被动式”。正确：“一种被动式”。“只”用于动物等，“被动式”是做事的方式，应该用“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edcde3de-1b60-425c-8b32-5d016f279331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26824, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种被动式地工作方法没有效果。", "corrected_sentence": "这种被动式的工作方法没有效果。", "error_description": "错误形式：被动式地。正确形式：被动式的。修饰名词“工作方法”要用“的”，不用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edcde3de-1b60-425c-8b32-5d016f279331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
