INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26826, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "食物或东西里含有的能量，能让身体暖和、有力气。", "primary_collocate": null, "pronunciation": "rè liàng", "ipa": "ʐɤ˥˩ ljɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "米饭的热量比青菜高。", "target_word": "热量", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一块蛋糕有很多热量。", "target_word": "热量", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想减肥，所以不吃热量高的东西。", "target_word": "热量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跑步一小时，会用掉很多热量。", "target_word": "热量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子正在长身体，每天需要足够的热量。", "target_word": "热量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天吃点热量高的东西，身体会暖和。", "target_word": "热量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "包装袋上写着每一百克有多少热量。", "target_word": "热量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天只吃蔬菜，身体得不到足够的热量。", "target_word": "热量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坚果很小，可是热量不低。", "target_word": "热量", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生说，运动后要吃点东西补充热量。", "target_word": "热量", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "食物里含有的、能让身体暖和有力气的能量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '892e6a23-674a-4223-9c9c-54e9c0f9d361') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26826, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "热量", "is_correct": true, "explanation": "热量（rè liàng）：食物里含有的能量，即正确答案。"}, {"text": "热恋", "is_correct": false, "explanation": "rè liàn 与 rè liàng 的韵母不同（an 与 ang），意思是热恋。"}, {"text": "热浪", "is_correct": false, "explanation": "làng 与 liàng 少了介音 i，韵母不同，意思是热浪。"}, {"text": "热烈", "is_correct": false, "explanation": "热烈（rè liè）与热量（rè liàng）韵母不同（ie 与 iang），意思是气氛很热闹、激动。"}], "explanations": {"热量": "热量（rè liàng）：食物里含有的能量，即正确答案。", "热恋": "rè liàn 与 rè liàng 的韵母不同（an 与 ang），意思是热恋。", "热浪": "làng 与 liàng 少了介音 i，韵母不同，意思是热浪。", "热烈": "热烈（rè liè）与热量（rè liàng）韵母不同（ie 与 iang），意思是气氛很热闹、激动。"}, "sentence_index": null, "correct_answer": "热量"}, "level_3": {"options": [{"text": "热量", "is_correct": true, "explanation": "热量：食物所含能量，可以比较高低，与“比青菜高”相符。"}, {"text": "颜色", "is_correct": false, "explanation": "体貌：颜色不用高低来比较，“米饭的颜色比青菜高”说不通。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：味道说浓淡，不说“高”，与“比青菜高”不搭配。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是米饭里含有的东西，不能说“米饭的空气比青菜高”。"}], "explanations": {"热量": "热量：食物所含能量，可以比较高低，与“比青菜高”相符。", "颜色": "体貌：颜色不用高低来比较，“米饭的颜色比青菜高”说不通。", "味道": "搭配：味道说浓淡，不说“高”，与“比青菜高”不搭配。", "空气": "语义：空气不是米饭里含有的东西，不能说“米饭的空气比青菜高”。"}, "sentence_index": 0, "correct_answer": "热量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这袋薯片有很多个热量。", "explanation": "量词用错。热量是抽象的能量，不能用“个”计量，应说“很多热量”。"}, {"text": "这杯果汁有一条热量。", "explanation": "量词用错。“条”用于细长的东西，热量不能用“条”计量。"}, {"text": "这碗粥里有五只热量。", "explanation": "量词用错。“只”用于动物，热量不能用“只”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae14e5c-e07c-4bf1-9912-b238114359dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26826, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "热量", "is_correct": true, "explanation": "热量：包装上标注的每百克所含能量，与“有多少”相符。"}, {"text": "保质期", "is_correct": false, "explanation": "搭配：“有多少保质期”不搭配，保质期应说“多长”。"}, {"text": "产地", "is_correct": false, "explanation": "语义：产地是地点，不能按每一百克计量。"}, {"text": "生产日期", "is_correct": false, "explanation": "语义：生产日期是时间点，不能说“每一百克有多少”。"}], "explanations": {"热量": "热量：包装上标注的每百克所含能量，与“有多少”相符。", "保质期": "搭配：“有多少保质期”不搭配，保质期应说“多长”。", "产地": "语义：产地是地点，不能按每一百克计量。", "生产日期": "语义：生产日期是时间点，不能说“每一百克有多少”。"}, "sentence_index": 6, "correct_answer": "热量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他减肥后，热量减轻了五公斤。", "explanation": "这里应该用〈体重〉。热量是能量，不用“公斤”计量，体重减轻才说公斤。"}, {"text": "这部电脑的热量只剩百分之十了。", "explanation": "这里应该用〈电量〉。电量指电池的电，热量指物质释放的热能，不能说电脑的热量只剩百分之十。"}, {"text": "他对工作充满热量。", "explanation": "这里应该用〈热情〉。热量指物质释放的能量，形容人的情绪要用热情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae14e5c-e07c-4bf1-9912-b238114359dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26826, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块奶酪的一个热量很高。", "corrected_sentence": "这块奶酪的热量很高。", "error_description": "“一个热量”多了量词“一个”。热量是抽象的能量，不能用“个”计量，应说“热量很高”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae14e5c-e07c-4bf1-9912-b238114359dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26826, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次运动能把多余的热量消耗。", "corrected_sentence": "这次运动能把多余的热量消耗掉。", "error_description": "“把”字句缺少补语。“把……消耗”后要加结果补语“掉”，应说“消耗掉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae14e5c-e07c-4bf1-9912-b238114359dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
