INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26832, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "墙是房子的一部分，像一块大板子，把房间分开。", "primary_collocate": null, "pronunciation": "qiáng tǐ", "ipa": "tɕʰiaŋ˧˥ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "墙体把大房间分成了两个小房间。", "target_word": "墙体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房子的墙体是白色的。", "target_word": "墙体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年挂画时，他在墙体上打了一个洞。", "target_word": "墙体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙体很厚，外面的声音进不来。", "target_word": "墙体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在修墙体上的大洞。", "target_word": "墙体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙体旁边放着一张旧沙发。", "target_word": "墙体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手敲了敲墙体，里面是空的。", "target_word": "墙体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新房子的墙体还没有刷漆。", "target_word": "墙体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水流进墙体，墙上留下了黑印。", "target_word": "墙体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这面墙体用砖砌成，很结实。", "target_word": "墙体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "墙体材料", "label": "复合"}, {"form": "墙体裂缝", "label": "复合"}], "register": "中性", "sense_fingerprint": "房子里把房间分开的墙", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a28e3c9-6de5-4ea0-9885-7603a65e2d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26832, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "墙体", "is_correct": true, "explanation": "墙体：把房间分开的墙，符合句意。"}, {"text": "地毯", "is_correct": false, "explanation": "语义：地毯铺在地上，不能把房间分成两个。"}, {"text": "灯", "is_correct": false, "explanation": "语义：灯不能把大房间分成两个小房间。"}, {"text": "树叶", "is_correct": false, "explanation": "搭配：“把……分成”一般搭配可以分隔空间的物体，树叶不行。"}], "explanations": {"墙体": "墙体：把房间分开的墙，符合句意。", "地毯": "语义：地毯铺在地上，不能把房间分成两个。", "灯": "语义：灯不能把大房间分成两个小房间。", "树叶": "搭配：“把……分成”一般搭配可以分隔空间的物体，树叶不行。"}, "sentence_index": 0, "correct_answer": "墙体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把墙体很厚，外面的声音进不来。", "explanation": "这里应该用〈面〉。墙体是竖直的面状结构，用“面”计量，不能用“把”。"}, {"text": "他把墙体挂在墙上。", "explanation": "这里应该用〈画〉。“挂”的对象是画、镜子等可以挂的物品，墙体是建筑结构，不能挂。"}, {"text": "地上铺着墙体，大家都走在上面。", "explanation": "这里应该用〈地毯〉。“铺”用于地毯等可以铺开的物品，墙体是竖直的结构，不能铺在地上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edcde3de-1b60-425c-8b32-5d016f279331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26832, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "墙体", "is_correct": true, "explanation": "墙体：空心或实心的墙，敲击后会发出声音，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：空气不能用手敲。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮在天上，不能用手敲，也谈不上“里面是空的”。"}, {"text": "云", "is_correct": false, "explanation": "语义：云飘在天上，不能用手敲。"}], "explanations": {"墙体": "墙体：空心或实心的墙，敲击后会发出声音，符合句意。", "空气": "搭配：空气不能用手敲。", "月亮": "语义：月亮在天上，不能用手敲，也谈不上“里面是空的”。", "云": "语义：云飘在天上，不能用手敲。"}, "sentence_index": 6, "correct_answer": "墙体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把墙体掀开，看看下面的东西。", "explanation": "这里应该用〈被子〉。“掀”用于被子等覆盖物，墙体是固定的结构，掀不开。"}, {"text": "他穿上了墙体，准备出门。", "explanation": "这里应该用〈衣服〉。“穿”用于衣服、鞋子等，墙体不能穿。"}, {"text": "他拉开墙体，让阳光照进来。", "explanation": "这里应该用〈窗帘〉。“拉开”用于窗帘等可以拉动的物品，墙体拉不开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edcde3de-1b60-425c-8b32-5d016f279331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26832, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只墙体很结实。", "corrected_sentence": "这段墙体很结实。", "error_description": "量词错误：墙体是一段一段砌成的建筑结构，量词应用“段”，“只”用于动物或小件物品，不能用来计量墙体。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edcde3de-1b60-425c-8b32-5d016f279331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26832, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在白色地墙体上挂了一幅画。", "corrected_sentence": "他在白色的墙体上挂了一幅画。", "error_description": "错误形式：白色地墙体。正确形式：白色的墙体。修饰名词要用“的”，不用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edcde3de-1b60-425c-8b32-5d016f279331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
