INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26836, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西盖住，不让人看到。", "primary_collocate": null, "pronunciation": "yǎn gài", "ipa": "jɛn˨˩ kaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他用布掩盖了桌上的东西。", "target_word": "掩盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "落叶掩盖了地上的小洞。", "target_word": "掩盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厚厚的雪掩盖着草地。", "target_word": "掩盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙子慢慢掩盖了那些脚印。", "target_word": "掩盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把地上的坑用木板掩盖起来。", "target_word": "掩盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白雪掩盖了河边的草地。", "target_word": "掩盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灰尘掩盖了桌子原来的颜色。", "target_word": "掩盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟用树叶掩盖自己的巢。", "target_word": "掩盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一块厚布掩盖着那堆旧家具。", "target_word": "掩盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大水掩盖了路边的石头。", "target_word": "掩盖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "掩盖了", "label": "体标"}, {"form": "掩盖着", "label": "体标"}, {"form": "掩盖过", "label": "体标"}, {"form": "掩蓋", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把具体的东西盖住使人看不见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43373ce-6bf9-462e-a046-f71a4d93129f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26836, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "掩盖", "is_correct": true, "explanation": "正确：“掩盖”表示把东西盖住，符合“用布掩盖桌上的东西”的句意。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指加热烹调，不能说“用布煮东西”。"}, {"text": "增加", "is_correct": false, "explanation": "搭配：“增加”说数量，不能说“用布增加了东西”。"}, {"text": "批评", "is_correct": false, "explanation": "配价：“批评”要求有人作对象，东西不能被批评。"}], "explanations": {"掩盖": "正确：“掩盖”表示把东西盖住，符合“用布掩盖桌上的东西”的句意。", "煮": "语义：“煮”指加热烹调，不能说“用布煮东西”。", "增加": "搭配：“增加”说数量，不能说“用布增加了东西”。", "批评": "配价：“批评”要求有人作对象，东西不能被批评。"}, "sentence_index": 0, "correct_answer": "掩盖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "墙掩盖了风。", "explanation": "这里应该用〈挡〉。掩盖的对象是具体的东西，不能用来指挡住看不见的风。"}, {"text": "他掩盖了一顿饭。", "explanation": "这里应该用〈吃〉。掩盖是把东西盖住不让人看见，不能用来表示吃饭。"}, {"text": "他掩盖了那个晚上。", "explanation": "这里应该用〈度过〉。掩盖的对象是具体的东西，不能用来指时间；经过一个晚上应说“度过”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bac360-2b61-4de4-b4b1-fed4c95583cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26836, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "掩盖", "is_correct": true, "explanation": "正确：“掩盖”表示盖住使人看不见，符合“灰尘掩盖了颜色”的句意。"}, {"text": "打扮", "is_correct": false, "explanation": "语义：“打扮”指修饰人的外表，不能用于灰尘与桌子颜色的关系。"}, {"text": "欣赏", "is_correct": false, "explanation": "配价：“欣赏”需要有人作主语，灰尘不能欣赏颜色。"}, {"text": "撕", "is_correct": false, "explanation": "语义：“撕”指扯开或扯断，不能用于颜色。"}], "explanations": {"掩盖": "正确：“掩盖”表示盖住使人看不见，符合“灰尘掩盖了颜色”的句意。", "打扮": "语义：“打扮”指修饰人的外表，不能用于灰尘与桌子颜色的关系。", "欣赏": "配价：“欣赏”需要有人作主语，灰尘不能欣赏颜色。", "撕": "语义：“撕”指扯开或扯断，不能用于颜色。"}, "sentence_index": 6, "correct_answer": "掩盖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大水掩盖了三个小时。", "explanation": "这里应该用〈持续〉。掩盖的对象是东西，不能是一段时间，时间应说“持续”。"}, {"text": "他掩盖了一场比赛。", "explanation": "这里应该用〈看〉。掩盖不能作用于比赛，观看比赛才是对它的动作。"}, {"text": "他掩盖了一首歌。", "explanation": "这里应该用〈唱〉。掩盖不能作用于歌曲，对歌曲的动作应说“唱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bac360-2b61-4de4-b4b1-fed4c95583cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26836, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用纸板把那个洞掩盖。", "corrected_sentence": "他用纸板把那个洞掩盖住了。", "error_description": "“把”字句中动词后要带补语或“了”等成分，不能只说“掩盖”。应说“把那个洞掩盖住了”，“住”是补语，“了”表示完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bac360-2b61-4de4-b4b1-fed4c95583cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26836, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨水很快掩盖了着那块石头。", "corrected_sentence": "雨水很快掩盖了那块石头。", "error_description": "体标重复：“了”与“着”不能同时用在同一动词后，应只保留“了”，说“雨水很快掩盖了那块石头。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bac360-2b61-4de4-b4b1-fed4c95583cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
