INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26840, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很久以前，人们开始用机器做很多事情，这叫做工业革命。", "primary_collocate": null, "pronunciation": "gōng yè gé mìng", "ipa": "kʊŋ˥ jɛ˥˩ kɤ˧˥ miŋ˥˩", "syllable_count": 4, "sentences": [{"text": "工业革命以后，工厂越来越多。", "target_word": "工业革命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为有了工业革命，人们开始用机器做事。", "target_word": "工业革命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在历史课上学了工业革命。", "target_word": "工业革命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业革命发生在很久以前的欧洲。", "target_word": "工业革命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业革命让衣服变得便宜了。", "target_word": "工业革命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想写一篇关于工业革命的文章。", "target_word": "工业革命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业革命时期，城市里的烟越来越多。", "target_word": "工业革命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业革命的故事我听过很多次。", "target_word": "工业革命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有工业革命，就没有今天的火车。", "target_word": "工业革命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业革命把手工劳动变成了机器生产。", "target_word": "工业革命", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "工業革命", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很久以前人们开始用机器做事的时期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43373ce-6bf9-462e-a046-f71a4d93129f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26840, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工业革命", "is_correct": true, "explanation": "正确：工业革命之后，工厂才越来越多，这是这一时期的历史背景。"}, {"text": "春节", "is_correct": false, "explanation": "语义：春节是节日，不是工厂增多的时间起点，与“以后”引出的历史变化不符。"}, {"text": "童年", "is_correct": false, "explanation": "搭配：“童年以后”指个人成长阶段，与“工厂越来越多”这种社会历史变化搭配不当。"}, {"text": "冬天", "is_correct": false, "explanation": "语义：冬天是季节，不能作为工厂越来越多的时间起点。"}], "explanations": {"工业革命": "正确：工业革命之后，工厂才越来越多，这是这一时期的历史背景。", "春节": "语义：春节是节日，不是工厂增多的时间起点，与“以后”引出的历史变化不符。", "童年": "搭配：“童年以后”指个人成长阶段，与“工厂越来越多”这种社会历史变化搭配不当。", "冬天": "语义：冬天是季节，不能作为工厂越来越多的时间起点。"}, "sentence_index": 0, "correct_answer": "工业革命"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上都吃工业革命。", "explanation": "这里应该用〈面包〉。工业革命是历史事件，不能吃。"}, {"text": "工厂实现了工业革命，生产变得更快了。", "explanation": "这里应该用〈自动化〉。自动化指某个生产环节的机械控制，工业革命指整个时代的大变革，不能说工厂“实现了工业革命”。"}, {"text": "瓦特发明了工业革命。", "explanation": "这里应该用〈蒸汽机〉作宾语。发明的是具体的机器，工业革命是历史事件，不能被发明。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bac360-2b61-4de4-b4b1-fed4c95583cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26840, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工业革命", "is_correct": true, "explanation": "正确：工业革命时期城市里工厂增多，烟也随之增加，这是历史上的因果关系。"}, {"text": "农耕", "is_correct": false, "explanation": "语义：农耕时代城市规模小，没有大量工厂排烟，与“烟越来越多”不符。"}, {"text": "寒假", "is_correct": false, "explanation": "搭配：“寒假”是假期，不是历史阶段，与“城市里的烟越来越多”搭配不当。"}, {"text": "冰河", "is_correct": false, "explanation": "语义：冰河时期还没有城市和工厂，城市里的烟不可能越来越多。"}], "explanations": {"工业革命": "正确：工业革命时期城市里工厂增多，烟也随之增加，这是历史上的因果关系。", "农耕": "语义：农耕时代城市规模小，没有大量工厂排烟，与“烟越来越多”不符。", "寒假": "搭配：“寒假”是假期，不是历史阶段，与“城市里的烟越来越多”搭配不当。", "冰河": "语义：冰河时期还没有城市和工厂，城市里的烟不可能越来越多。"}, "sentence_index": 6, "correct_answer": "工业革命"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的工业革命增加了很多。", "explanation": "这里应该用〈收入〉。“增加了很多”用于数量，工业革命是历史事件，不是数量。"}, {"text": "他们想搞一场工业革命，推翻政府。", "explanation": "这里误用了推翻政权的意思（〈政变〉）。工业革命指生产方式的变革，不指推翻政府。"}, {"text": "我们昨天去了一次工业革命，玩得很开心。", "explanation": "这里应该用〈旅行〉。旅行可以去，工业革命是历史事件，不能“去”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bac360-2b61-4de4-b4b1-fed4c95583cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26840, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条工业革命让城市变得更加繁华了。", "corrected_sentence": "这场工业革命让城市变得更加繁华了。", "error_description": "量词错误：“条”用于细长的东西，不能修饰工业革命这类历史变革，应说“这场工业革命”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bac360-2b61-4de4-b4b1-fed4c95583cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26840, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工业革命发生过在欧洲。", "corrected_sentence": "工业革命发生在欧洲。", "error_description": "体标错误：“发生在”后面直接接地点，不能在“发生”和“在”之间加“过”。应说“工业革命发生在欧洲。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bac360-2b61-4de4-b4b1-fed4c95583cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
