INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26848, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "二十世纪是从1900年到1999年的一百年。", "primary_collocate": null, "pronunciation": "èr shí shì jì", "ipa": "ɚ˥˩ ʂɨ˧˥ ʂɨ˥˩ tɕi˥˩", "syllable_count": 4, "sentences": [{"text": "二十世纪有一百年，从一九零零年开始。", "target_word": "二十世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一九九九年是二十世纪的最后一年。", "target_word": "二十世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我外婆是二十世纪出生的人。", "target_word": "二十世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二十世纪已经过去了，我们现在生活在新世纪。", "target_word": "二十世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，二十世纪人们开始坐飞机旅行。", "target_word": "二十世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二十世纪的中国发生了很大的变化。", "target_word": "二十世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢研究二十世纪的历史。", "target_word": "二十世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些旧车都是二十世纪造的。", "target_word": "二十世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二十世纪初，很多人还没有电话。", "target_word": "二十世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人的一生，几乎跨越了整个二十世纪。", "target_word": "二十世纪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "二十世紀", "label": "繁体"}], "register": "中性", "sense_fingerprint": "从1900年到1999年的一百年", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43373ce-6bf9-462e-a046-f71a4d93129f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26848, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "二十世纪", "is_correct": true, "explanation": "正确：“二十世纪”是一百年的时期，符合“有一百年，从一九零零年开始”的句意。"}, {"text": "星期", "is_correct": false, "explanation": "语义：“星期”只有七天，不能说“星期有一百年”。"}, {"text": "教室", "is_correct": false, "explanation": "语义：“教室”是房间，不能表示一百年的时期。"}, {"text": "白天", "is_correct": false, "explanation": "搭配：“白天”指一天中的时段，不能说“白天有一百年”。"}], "explanations": {"二十世纪": "正确：“二十世纪”是一百年的时期，符合“有一百年，从一九零零年开始”的句意。", "星期": "语义：“星期”只有七天，不能说“星期有一百年”。", "教室": "语义：“教室”是房间，不能表示一百年的时期。", "白天": "搭配：“白天”指一天中的时段，不能说“白天有一百年”。"}, "sentence_index": 0, "correct_answer": "二十世纪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "现在的孩子生活在二十世纪。", "explanation": "这里应该用〈二十一世纪〉。说“现在的孩子”，所处的应是二十一世纪，二十世纪已经过去。"}, {"text": "二十世纪是下午三点。", "explanation": "这里应该用〈现在〉。二十世纪是一百年的时期，不能表示某个钟点。"}, {"text": "这次的二十世纪只有三天。", "explanation": "这里应该用〈假期〉。二十世纪是一百年的时期，不能只有三天。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bac360-2b61-4de4-b4b1-fed4c95583cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26848, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "二十世纪", "is_correct": true, "explanation": "正确：“二十世纪”是一个历史时期，可以作“历史”的修饰语，符合句意。"}, {"text": "五分钟", "is_correct": false, "explanation": "语义：“五分钟”是很短的时长，不能作为研究的历史对象。"}, {"text": "一小时", "is_correct": false, "explanation": "搭配：“一小时”是时长，不能用来限定“历史”。"}, {"text": "十分钟", "is_correct": false, "explanation": "搭配：“十分钟”是时长，不能说“十分钟的历史”。"}], "explanations": {"二十世纪": "正确：“二十世纪”是一个历史时期，可以作“历史”的修饰语，符合句意。", "五分钟": "语义：“五分钟”是很短的时长，不能作为研究的历史对象。", "一小时": "搭配：“一小时”是时长，不能用来限定“历史”。", "十分钟": "搭配：“十分钟”是时长，不能说“十分钟的历史”。"}, "sentence_index": 6, "correct_answer": "二十世纪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈做的二十世纪很好吃。", "explanation": "这里应该用〈菜〉。二十世纪是时期，不是食物，不能说“好吃”。"}, {"text": "这座二十世纪很有意思。", "explanation": "这里应该用〈这个时代〉。二十世纪是时期，不能用“座”计量。"}, {"text": "我工作了二十世纪。", "explanation": "这里应该用〈二十年〉。二十世纪指固定的一百年（1900至1999年），不能用来表示某人工作的时长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bac360-2b61-4de4-b4b1-fed4c95583cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26848, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二十世纪时候，人们很少出国。", "corrected_sentence": "二十世纪的时候，人们很少出国。", "error_description": "“二十世纪”修饰“时候”时中间应加“的”，说“二十世纪的时候”，不能说“二十世纪时候”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bac360-2b61-4de4-b4b1-fed4c95583cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26848, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些老照片是二十世纪拍。", "corrected_sentence": "这些老照片是二十世纪拍的。", "error_description": "“是……的”句中漏掉了句末的“的”，应说“这些老照片是二十世纪拍的”，不能省略“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bac360-2b61-4de4-b4b1-fed4c95583cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
