INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26858, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "硅是一种像石头一样的东西，可以用来做电脑和手机。", "primary_collocate": null, "pronunciation": "guī", "ipa": "kweɪ˥", "syllable_count": 1, "sentences": [{"text": "硅像石头，可以做电脑。", "target_word": "硅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机里面有一点硅。", "target_word": "硅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用硅做手机的芯片。", "target_word": "硅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块硅很小，也很硬。", "target_word": "硅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑的芯片是硅做的。", "target_word": "硅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在书上看到过硅的照片。", "target_word": "硅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "硅不是水，也不是铁。", "target_word": "硅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了一块硅。", "target_word": "硅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有硅，就没有现在的电脑。", "target_word": "硅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂每天买很多硅。", "target_word": "硅", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}], "register": "中性", "sense_fingerprint": "像石头的东西硅，用来做电脑和手机", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea0a212a-0dc6-478f-bf31-657d4bcdaa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26858, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "硅", "is_correct": true, "explanation": "硅，guī（第一声），像石头的材料，可用来做电脑和手机。"}, {"text": "鬼", "is_correct": false, "explanation": "guǐ（第三声）与 guī（第一声）声调不同，意思是鬼。"}, {"text": "贵", "is_correct": false, "explanation": "guì（第四声）与 guī（第一声）声调不同，意思是贵重。"}, {"text": "灰", "is_correct": false, "explanation": "h 与 g 声母不同，huī 意思是灰色。"}, {"text": "亏", "is_correct": false, "explanation": "k 与 g 声母不同，kuī 意思是亏损。"}], "explanations": {"硅": "硅，guī（第一声），像石头的材料，可用来做电脑和手机。", "鬼": "guǐ（第三声）与 guī（第一声）声调不同，意思是鬼。", "贵": "guì（第四声）与 guī（第一声）声调不同，意思是贵重。", "灰": "h 与 g 声母不同，huī 意思是灰色。", "亏": "k 与 g 声母不同，kuī 意思是亏损。"}, "sentence_index": null, "correct_answer": "硅"}, "level_3": {"options": [{"text": "硅", "is_correct": true, "explanation": "硅是像石头的材料，可以用来做电脑的芯片。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不是可以做电脑的材料。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头不能做电脑的芯片材料。"}, {"text": "水", "is_correct": false, "explanation": "语义：水是液体，不能用来做电脑。"}], "explanations": {"硅": "硅是像石头的材料，可以用来做电脑的芯片。", "面包": "语义：面包是食物，不是可以做电脑的材料。", "木头": "语义：木头不能做电脑的芯片材料。", "水": "语义：水是液体，不能用来做电脑。"}, "sentence_index": 0, "correct_answer": "硅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上用硅煮粥。", "explanation": "这里应该用〈水〉。硅不能用来煮东西；“煮粥”要用水和锅。"}, {"text": "这块硅很甜。", "explanation": "这里应该用〈糖〉。“甜”描述的是糖之类的食物，硅不能形容为甜。"}, {"text": "我每天用硅擦脸。", "explanation": "这里应该用〈毛巾〉。硅不是擦脸用的，“擦脸”要用毛巾之类的织物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26858, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "硅", "is_correct": true, "explanation": "硅，guī（第一声），像石头的材料，可用来做电脑和手机。"}, {"text": "轨", "is_correct": false, "explanation": "guǐ（第三声）与 guī（第一声）声调不同，意思是轨道。"}, {"text": "柜", "is_correct": false, "explanation": "guì（第四声）与 guī（第一声）声调不同，意思是柜子。"}, {"text": "挥", "is_correct": false, "explanation": "h 与 g 声母不同，huī 意思是挥动。"}, {"text": "跪", "is_correct": false, "explanation": "guì（第四声）与 guī（第一声）声调不同，意思是下跪。"}], "explanations": {"硅": "硅，guī（第一声），像石头的材料，可用来做电脑和手机。", "轨": "guǐ（第三声）与 guī（第一声）声调不同，意思是轨道。", "柜": "guì（第四声）与 guī（第一声）声调不同，意思是柜子。", "挥": "h 与 g 声母不同，huī 意思是挥动。", "跪": "guì（第四声）与 guī（第一声）声调不同，意思是下跪。"}, "sentence_index": null, "correct_answer": "硅"}, "level_3": {"options": [{"text": "硅", "is_correct": true, "explanation": "硅是一种像石头的东西，与水和铁都不同。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：苹果是水果，不是像石头的材料，句子要说的是一种材料。"}, {"text": "蒸汽", "is_correct": false, "explanation": "语义：蒸汽是水的气态，与“不是水”的说法矛盾。"}, {"text": "铁块", "is_correct": false, "explanation": "语义：铁块就是铁，与“不是铁”的说法矛盾。"}], "explanations": {"硅": "硅是一种像石头的东西，与水和铁都不同。", "苹果": "语义：苹果是水果，不是像石头的材料，句子要说的是一种材料。", "蒸汽": "语义：蒸汽是水的气态，与“不是水”的说法矛盾。", "铁块": "语义：铁块就是铁，与“不是铁”的说法矛盾。"}, "sentence_index": 6, "correct_answer": "硅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂每天养很多硅。", "explanation": "这里应该用〈买〉。“养”的对象是动植物，硅是矿物，不能养。"}, {"text": "这家工厂每天穿很多硅。", "explanation": "这里应该用〈买〉。“穿”的对象是衣物，硅不能穿。"}, {"text": "这家工厂每天喝很多硅。", "explanation": "这里应该用〈买〉。硅是固体，不能喝；“喝”的对象要是液体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26858, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他看过这张硅的照片。", "corrected_sentence": "他看过这块硅的照片。", "error_description": "量词错误。硅是块状固体，量词应用“块”；“张”用于纸、照片等扁平的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26858, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师递给我一条硅。", "corrected_sentence": "老师递给我一块硅。", "error_description": "量词错误。硅是块状固体，量词应用“块”；“条”用于细长的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
