INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26860, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "证明就是告诉大家一件事是真的。", "primary_collocate": null, "pronunciation": "zhèng míng", "ipa": "ʈʂɤŋ˥˩ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "你拿出票来证明你买过它。", "target_word": "证明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事我可以证明，他没说谎。", "target_word": "证明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想证明那只猫是他的。", "target_word": "证明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要证明这个消息是真的。", "target_word": "证明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁能证明你昨天在家？", "target_word": "证明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些照片证明他去过北京。", "target_word": "证明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈可以证明我一直在写作业。", "target_word": "证明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿出本子证明自己说的是真的。", "target_word": "证明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好朋友会证明你说的话不是假的。", "target_word": "证明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间会证明谁是对的。", "target_word": "证明", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "证明了", "label": "体标"}, {"form": "证明过", "label": "体标"}, {"form": "證明", "label": "繁体"}], "register": "中性", "sense_fingerprint": "告诉大家一件事是真的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea0a212a-0dc6-478f-bf31-657d4bcdaa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26860, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "证明", "is_correct": true, "explanation": "证明（zhèng míng）指用证据或理由表明某件事是真的，即本词。"}, {"text": "争鸣", "is_correct": false, "explanation": "zhēng（第一声）与 zhèng（第四声）声调不同，争鸣意思是各抒己见地辩论。"}, {"text": "挣命", "is_correct": false, "explanation": "第二音节 mìng（第四声）与 míng（第二声）声调不同，挣命意思是拼命挣扎求生。"}, {"text": "争名", "is_correct": false, "explanation": "zhēng（第一声）与 zhèng（第四声）声调不同，争名意思是争夺名声，如“争名夺利”。"}], "explanations": {"证明": "证明（zhèng míng）指用证据或理由表明某件事是真的，即本词。", "争鸣": "zhēng（第一声）与 zhèng（第四声）声调不同，争鸣意思是各抒己见地辩论。", "挣命": "第二音节 mìng（第四声）与 míng（第二声）声调不同，挣命意思是拼命挣扎求生。", "争名": "zhēng（第一声）与 zhèng（第四声）声调不同，争名意思是争夺名声，如“争名夺利”。"}, "sentence_index": null, "correct_answer": "证明"}, "level_3": {"options": [{"text": "证明", "is_correct": true, "explanation": "证明：拿出票来表明你买过它，与“拿出票来”的目的相合。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：拿出票是为了提供证据，“忘记”与这个目的相反。"}, {"text": "修理", "is_correct": false, "explanation": "配价：“修理”要求器物作宾语，不能接“你买过它”这样的小句。"}, {"text": "发明", "is_correct": false, "explanation": "搭配：“发明”用于创造新事物，不能说“发明你买过它”。"}], "explanations": {"证明": "证明：拿出票来表明你买过它，与“拿出票来”的目的相合。", "忘记": "语义：拿出票是为了提供证据，“忘记”与这个目的相反。", "修理": "配价：“修理”要求器物作宾语，不能接“你买过它”这样的小句。", "发明": "搭配：“发明”用于创造新事物，不能说“发明你买过它”。"}, "sentence_index": 0, "correct_answer": "证明"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "科学家证明了那座岛。", "explanation": "这里应该用〈考察〉。考察指实地调查，证明的宾语是事实或结论，不能是岛这样的地点。"}, {"text": "她终于证明了这份作业。", "explanation": "这里应该用〈完成〉。完成指做完某件事，证明的宾语只能是事实或结论。"}, {"text": "他证明了这条路。", "explanation": "这里应该用〈选择〉。选择指挑出某个对象，证明不能以路作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26860, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "证明", "is_correct": true, "explanation": "证明：妈妈能为我作证，表明我一直在写作业，与语境相合。"}, {"text": "嫉妒", "is_correct": false, "explanation": "语义：嫉妒是羡慕或不满别人，与“妈妈可以……我一直在写作业”的语境无关。"}, {"text": "收藏", "is_correct": false, "explanation": "配价：“收藏”要求物品作宾语，不能接“我一直在写作业”这样的小句。"}, {"text": "购买", "is_correct": false, "explanation": "配价：“购买”要求商品作宾语，不能接事件小句，句意不通。"}], "explanations": {"证明": "证明：妈妈能为我作证，表明我一直在写作业，与语境相合。", "嫉妒": "语义：嫉妒是羡慕或不满别人，与“妈妈可以……我一直在写作业”的语境无关。", "收藏": "配价：“收藏”要求物品作宾语，不能接“我一直在写作业”这样的小句。", "购买": "配价：“购买”要求商品作宾语，不能接事件小句，句意不通。"}, "sentence_index": 6, "correct_answer": "证明"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "裁判证明了那把哨子。", "explanation": "这里应该用〈吹〉。证明的宾语是事实或结论，哨子不是事实；裁判对哨子的动作应是“吹”。"}, {"text": "他证明了一张票。", "explanation": "这里应该用〈预订〉。预订是提前订下，证明不能以票作宾语。"}, {"text": "商店证明了这些水果。", "explanation": "这里应该用〈出售〉。出售指把商品卖出去，证明的宾语只能是事实或结论。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26860, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他证明了这把椅子是真的。", "corrected_sentence": "他证明了这件事是真的。", "error_description": "宾语错误。“证明”的宾语应是事实，“椅子”不是事实，不能说“证明了这把椅子是真的”；应说“证明了这件事是真的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26860, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份记录能不证明他的说法属实。", "corrected_sentence": "这份记录不能证明他的说法属实。", "error_description": "错误：“能不证明”是直陈句的错误说法；直陈应说“不能证明”。“能不……”只见于反问句，须带“吗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
