INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26862, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26862, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "电能是一种可以点亮灯泡、让电视工作的力量。", "primary_collocate": null, "pronunciation": "diàn néng", "ipa": "tjɛn˥˩ nɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "电能让灯泡亮起来。", "target_word": "电能", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "电视机需要电能才能工作。", "target_word": "电能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机的电能用光了，就开不了机。", "target_word": "电能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电能可以让风扇转起来。", "target_word": "电能", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "电能可以用来烧水，又快又干净。", "target_word": "电能", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这台冰箱一天要用很多电能。", "target_word": "电能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳能板能把阳光变成电能。", "target_word": "电能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "关灯能省下不少电能。", "target_word": "电能", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "电能让我们的生活更方便。", "target_word": "电能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小火车靠电能在轨道上跑。", "target_word": "电能", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "电能表", "label": "复合"}], "register": "通俗", "sense_fingerprint": "能点亮灯泡、让电器工作的力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea0a212a-0dc6-478f-bf31-657d4bcdaa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26862, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感情", "is_correct": false, "explanation": "搭配：“亮起来”说的是灯、光，不搭配“感情”。"}, {"text": "风扇", "is_correct": false, "explanation": "语义：风扇转动，不能使灯泡发光。"}, {"text": "电能", "is_correct": true, "explanation": "正确：电能可以让灯泡发光，与“让灯泡亮起来”相符。"}, {"text": "报纸", "is_correct": false, "explanation": "语义：报纸不能供电，也不能让灯泡亮起来。"}], "explanations": {"感情": "搭配：“亮起来”说的是灯、光，不搭配“感情”。", "风扇": "语义：风扇转动，不能使灯泡发光。", "电能": "正确：电能可以让灯泡发光，与“让灯泡亮起来”相符。", "报纸": "语义：报纸不能供电，也不能让灯泡亮起来。"}, "sentence_index": 0, "correct_answer": "电能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天吃饭，身体里的电能很充足。", "explanation": "这里应该用〈能量〉。电能专指由电产生的能量，人的精力不说“电能”。"}, {"text": "这节电池的电能是一点五伏。", "explanation": "这里应该用〈电压〉。“伏”计量的是电压，电能应以“度”或“千瓦时”计量，不能用伏数来说。"}, {"text": "这台电风扇的电能是六十瓦。", "explanation": "这里应该用〈功率〉。“瓦”计量的是功率，电能应以“度”或“千瓦时”计量，不能用瓦数来说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26862, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "面粉", "is_correct": false, "explanation": "语义：太阳能板不能把阳光变成面粉。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“变成”后接能量或物质，“温度”是量度，不能作为转化结果。"}, {"text": "电能", "is_correct": true, "explanation": "正确：太阳能板把阳光转化后得到的是电能，与“变成”相符。"}, {"text": "木头", "is_correct": false, "explanation": "语义：阳光不会变成木头。"}], "explanations": {"面粉": "语义：太阳能板不能把阳光变成面粉。", "温度": "搭配：“变成”后接能量或物质，“温度”是量度，不能作为转化结果。", "电能": "正确：太阳能板把阳光转化后得到的是电能，与“变成”相符。", "木头": "语义：阳光不会变成木头。"}, "sentence_index": 6, "correct_answer": "电能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块蛋糕的电能有三百大卡。", "explanation": "这里应该用〈热量〉。食物所含的能量要用“大卡”计量，说“热量”；电能指由电产生的能量，不能用来形容食物。"}, {"text": "这艘帆船靠风的电能在海上前进。", "explanation": "这里应该用〈动力〉。帆船借风力前进，要说“动力”，电能是电的能量。"}, {"text": "这根导线里的电能是五安。", "explanation": "这里应该用〈电流〉。“安”计量的是电流，电能应以“度”或“千瓦时”计量，不能用安数来说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26862, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块电池的电能已经耗了完。", "corrected_sentence": "这块电池的电能已经耗完了。", "error_description": "错误：“耗了完”；正确：“耗完了”。结果补语“完”紧跟动词“耗”，“了”放在句末。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26862, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块太阳能板能把阳光转化电能。", "corrected_sentence": "这块太阳能板能把阳光转化成电能。", "error_description": "错误：“转化电能”；正确：“转化成电能”。“转化”后须接“成”引出结果。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26864, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc0c84d7-0962-4ade-b4e4-82cb24de3b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26864, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc0c84d7-0962-4ade-b4e4-82cb24de3b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26864, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "电子是小小的、带负电的东西，在电里跑来跑去。", "primary_collocate": null, "pronunciation": "diàn zǐ", "ipa": "tjɛn˥˩ tsɿ˨˩˦", "syllable_count": 2, "sentences": [{"text": "电子很小，我们用眼睛看不到它。", "target_word": "电子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，电子在电线里跑来跑去。", "target_word": "电子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电子带负电，和正电互相吸引。", "target_word": "电子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电池里的电子一动，灯就亮了。", "target_word": "电子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "课本上画着很多小小的电子。", "target_word": "电子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电子跑得很快，一秒钟能跑很远。", "target_word": "电子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不明白电子为什么总在电线里动。", "target_word": "电子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电子从电池的一头跑到另一头。", "target_word": "电子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明问老师：“电子长什么样子？”", "target_word": "电子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有电子，灯就不会亮。", "target_word": "电子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个电子", "label": "量词（个）"}, {"form": "電子", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很小、带负电、在电中跑来跑去的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bff2398e-8e1d-4c42-88b1-9e5a19e189a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26864, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "电子", "is_correct": true, "explanation": "正确：电子（diàn zǐ），小小的、带负电的东西。"}, {"text": "点子", "is_correct": false, "explanation": "diǎn（第三声）与 diàn（第四声）声调不同，“点子”意思是主意。"}, {"text": "链子", "is_correct": false, "explanation": "liàn 与 diàn 声母不同（l 与 d），“链子”意思是链条。"}, {"text": "辫子", "is_correct": false, "explanation": "biàn 与 diàn 声母不同（b 与 d），“辫子”意思是编起来的头发。"}, {"text": "片子", "is_correct": false, "explanation": "piàn 与 diàn 声母不同（p 与 d），“片子”意思是影片或片状的东西。"}, {"text": "面子", "is_correct": false, "explanation": "miàn 与 diàn 声母不同（m 与 d），“面子”意思是颜面。"}], "explanations": {"电子": "正确：电子（diàn zǐ），小小的、带负电的东西。", "点子": "diǎn（第三声）与 diàn（第四声）声调不同，“点子”意思是主意。", "链子": "liàn 与 diàn 声母不同（l 与 d），“链子”意思是链条。", "辫子": "biàn 与 diàn 声母不同（b 与 d），“辫子”意思是编起来的头发。", "片子": "piàn 与 diàn 声母不同（p 与 d），“片子”意思是影片或片状的东西。", "面子": "miàn 与 diàn 声母不同（m 与 d），“面子”意思是颜面。"}, "sentence_index": null, "correct_answer": "电子"}, "level_3": {"options": [{"text": "电子", "is_correct": true, "explanation": "正确：电子很小，肉眼看不到，与句意相符。"}, {"text": "大象", "is_correct": false, "explanation": "体貌：大象体型庞大，与“很小”和“看不到”矛盾。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：西瓜又大又显眼，用眼睛看得到，与句意不合。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是大型机械，肉眼很容易看到，与句中描述不符。"}], "explanations": {"电子": "正确：电子很小，肉眼看不到，与句意相符。", "大象": "体貌：大象体型庞大，与“很小”和“看不到”矛盾。", "西瓜": "语义：西瓜又大又显眼，用眼睛看得到，与句意不合。", "汽车": "语义：汽车是大型机械，肉眼很容易看到，与句中描述不符。"}, "sentence_index": 0, "correct_answer": "电子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今晚停电子了，屋里一片漆黑。", "explanation": "这里应该用〈电〉。“停”搭配的是电（停电），电子是小小的粒子，不能说停电子。"}, {"text": "电子断了，灯就不亮了。", "explanation": "这里应该用〈电流〉。断的是电流或电路，电子是小小的粒子，不说“断电子”。"}, {"text": "房间里的电子太亮了，我的眼睛很疼。", "explanation": "这里应该用〈灯光〉。亮的是灯光，电子是小小的粒子，看不到，不能说电子太亮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc0c84d7-0962-4ade-b4e4-82cb24de3b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26864, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电子", "is_correct": true, "explanation": "正确：句中的主语是电子，指会运动的微观粒子。"}, {"text": "石碑", "is_correct": false, "explanation": "语义：“石碑”是静止的石刻，不会在电线里运动，与句中的电子语境不合。"}, {"text": "墙壁", "is_correct": false, "explanation": "语义：“墙壁”是建筑构件，不会在电线里运动，与句中的电子语境不合。"}, {"text": "高山", "is_correct": false, "explanation": "体貌：“高山”巨大稳固，不会在电线里运动，与“电子”这一微观粒子的语境不符。"}], "explanations": {"电子": "正确：句中的主语是电子，指会运动的微观粒子。", "石碑": "语义：“石碑”是静止的石刻，不会在电线里运动，与句中的电子语境不合。", "墙壁": "语义：“墙壁”是建筑构件，不会在电线里运动，与句中的电子语境不合。", "高山": "体貌：“高山”巨大稳固，不会在电线里运动，与“电子”这一微观粒子的语境不符。"}, "sentence_index": 6, "correct_answer": "电子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电线外面包着一层电子，不导电。", "explanation": "这里应该用〈橡胶〉。电子不能作为包覆电线的绝缘材料，包电线用橡胶。"}, {"text": "电子太高，灯泡会烧坏。", "explanation": "这里应该用〈电压〉。“高”说的是电压高低，电子是小小的粒子，不说“电子太高”。"}, {"text": "这个月家里用了很多电子，要交一百块钱。", "explanation": "这里应该用〈电〉。交费按用电量算，电子是小小的粒子，不说用了很多电子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc0c84d7-0962-4ade-b4e4-82cb24de3b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26864, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个电池里有三只电子在跑。", "corrected_sentence": "这个电池里有三个电子在跑。", "error_description": "量词错误：电子应用量词“个”，“只”不用于电子。应说“三个电子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc0c84d7-0962-4ade-b4e4-82cb24de3b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26864, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两电子跑得很快。", "corrected_sentence": "这两个电子跑得很快。", "error_description": "量词漏掉：指示代词加数词“这两”后要加量词“个”，应说“这两个电子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc0c84d7-0962-4ade-b4e4-82cb24de3b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
