INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26868, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "晶体是像糖或盐一样，有整齐形状的小块。", "primary_collocate": null, "pronunciation": "jīng tǐ", "ipa": "tɕiŋ˥ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "盐和糖都是白色的晶体。", "target_word": "晶体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把一小块晶体放在手心里。", "target_word": "晶体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杯子底部长出了很多小晶体。", "target_word": "晶体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些晶体在太阳下闪闪发光。", "target_word": "晶体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在课上看着晶体慢慢长大。", "target_word": "晶体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "糖放太久，会变成一块块晶体。", "target_word": "晶体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在海边见过很大的晶体。", "target_word": "晶体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水里放很多盐，会慢慢长出晶体。", "target_word": "晶体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种晶体的形状像一颗小星星。", "target_word": "晶体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用放大镜看桌上的晶体。", "target_word": "晶体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "晶體", "label": "繁体"}, {"form": "小晶体", "label": "复合"}, {"form": "块", "label": "量词"}, {"form": "颗", "label": "量词"}], "register": "中性", "sense_fingerprint": "晶体|糖盐|整齐的小块", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c8e9f36-9d8f-4bd1-976d-30c7aefae07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26868, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "晶体", "is_correct": true, "explanation": "「盐和糖都是白色的晶体」中，晶体指有整齐形状的小块，与盐、糖相符。"}, {"text": "液体", "is_correct": false, "explanation": "语义：盐和糖在常温下是固态，不能说是白色的液体。"}, {"text": "气体", "is_correct": false, "explanation": "语义：盐和糖是固体小块，不是气体。"}, {"text": "木块", "is_correct": false, "explanation": "搭配：盐和糖是食用晶体，不能与木块对应，「白色的木块」与句中的盐和糖不搭。"}], "explanations": {"晶体": "「盐和糖都是白色的晶体」中，晶体指有整齐形状的小块，与盐、糖相符。", "液体": "语义：盐和糖在常温下是固态，不能说是白色的液体。", "气体": "语义：盐和糖是固体小块，不是气体。", "木块": "搭配：盐和糖是食用晶体，不能与木块对应，「白色的木块」与句中的盐和糖不搭。"}, "sentence_index": 0, "correct_answer": "晶体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "糖水是一种晶体。", "explanation": "这里应该用〈液体〉。糖水是液体，晶体指有整齐形状的固体小块，如糖块、盐块。"}, {"text": "这颗晶体每天都会跳舞。", "explanation": "语义：晶体是无生命的固体小块，不会跳舞，这样用说不通。"}, {"text": "他把晶体唱成了一首歌。", "explanation": "语义：晶体是固体小块，不能唱成歌，这样用说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26868, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "晶体", "is_correct": true, "explanation": "「很大的晶体」指较大的晶体小块，在海边见到的是矿物晶体，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "语义：「见过」的对象应是看得见的实物，空气看不见，不能说“见过很大的空气”。"}, {"text": "歌声", "is_correct": false, "explanation": "语义：歌声是听得见的声音，不能说“见过”，句意不通。"}, {"text": "寂静", "is_correct": false, "explanation": "语义：寂静是没有声音的状态，看不见，不能说“见过很大的寂静”。"}], "explanations": {"晶体": "「很大的晶体」指较大的晶体小块，在海边见到的是矿物晶体，符合句意。", "空气": "语义：「见过」的对象应是看得见的实物，空气看不见，不能说“见过很大的空气”。", "歌声": "语义：歌声是听得见的声音，不能说“见过”，句意不通。", "寂静": "语义：寂静是没有声音的状态，看不见，不能说“见过很大的寂静”。"}, "sentence_index": 6, "correct_answer": "晶体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这包面粉是一种晶体。", "explanation": "这里应该用〈粉末〉。面粉是细粉状，没有整齐的形状，不是晶体。"}, {"text": "这块毛巾是一种晶体。", "explanation": "这里应该用〈织物〉。毛巾是织物，不是有整齐形状的小块。"}, {"text": "这股烟是一种晶体。", "explanation": "这里应该用〈烟雾〉。烟雾是细小微粒悬浮在空气中，没有整齐的形状，不是晶体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26868, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只晶体很亮。", "corrected_sentence": "那颗晶体很亮。", "error_description": "量词错误：小块状的晶体应用「颗」，不用「只」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26868, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师把那块晶体拿了走。", "corrected_sentence": "老师把那块晶体拿走了。", "error_description": "补语位置错误：「拿走」是动补结构，「了」应放在「拿走」之后，不能插在「拿」和「走」中间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23c8763-c120-44dc-a771-b4335ab1b603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
