INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26870, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "光能是光带来的能量，能让东西动起来或变热。", "primary_collocate": null, "pronunciation": "guāng néng", "ipa": "kwɑŋ˥ nɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "光能可以让小风车转起来。", "target_word": "光能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "石头晒了一天，吸收了很多光能，摸起来很热。", "target_word": "光能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花草需要光能才能长大。", "target_word": "光能", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个小玩具靠光能就能动。", "target_word": "光能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳照在黑衣服上，光能变成了热。", "target_word": "光能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "放大镜把光能聚在一起，纸就变热了。", "target_word": "光能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计算器不用电池，只用光能。", "target_word": "光能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夜里没有太阳，就没有光能了。", "target_word": "光能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把花放在窗边，它能得到更多光能。", "target_word": "光能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白色的东西会反射很多光能。", "target_word": "光能", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "通俗", "sense_fingerprint": "光带来的能量，能让东西动或变热", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea0a212a-0dc6-478f-bf31-657d4bcdaa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26870, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "光能", "is_correct": true, "explanation": "光能：光带来的能量能推动小风车，与“转起来”的语境相合。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不能推动小风车转动，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不具备让物体转动的能量，与语境矛盾。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“让……转起来”要的是能提供动力的事物，石头不能这样搭配。"}], "explanations": {"光能": "光能：光带来的能量能推动小风车，与“转起来”的语境相合。", "声音": "语义：声音不能推动小风车转动，句意不通。", "颜色": "语义：颜色不具备让物体转动的能量，与语境矛盾。", "石头": "搭配：“让……转起来”要的是能提供动力的事物，石头不能这样搭配。"}, "sentence_index": 0, "correct_answer": "光能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我坐在窗边，在光能下看书。", "explanation": "这里应该用〈阳光〉。在……下看书指的是照明的光，光能是能量，不能说“在光能下”。"}, {"text": "插上光能，灯就亮了。", "explanation": "这里应该用〈电〉。电可以接通线路，光能是能量形式，不能像电那样插上使用。"}, {"text": "光能吹得小风车转。", "explanation": "这里应该用〈风〉。风会吹动物体，光能是能量，不能吹动东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26870, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "光能", "is_correct": true, "explanation": "光能：计算器靠光照工作，与“不用电池”的语境相合。"}, {"text": "风", "is_correct": false, "explanation": "语义：计算器不靠风力工作，“只用风”与句意不合。"}, {"text": "柴火", "is_correct": false, "explanation": "搭配：计算器不能“用柴火”，柴火搭配的是燃烧加热的场合。"}, {"text": "电池", "is_correct": false, "explanation": "语义：前句已说“不用电池”，后句再说“只用电池”，前后矛盾。"}], "explanations": {"光能": "光能：计算器靠光照工作，与“不用电池”的语境相合。", "风": "语义：计算器不靠风力工作，“只用风”与句意不合。", "柴火": "搭配：计算器不能“用柴火”，柴火搭配的是燃烧加热的场合。", "电池": "语义：前句已说“不用电池”，后句再说“只用电池”，前后矛盾。"}, "sentence_index": 6, "correct_answer": "光能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "暖气放出很多光能，屋里很暖和。", "explanation": "这里应该用〈热量〉。暖气放出的是热，光能是光辐射的能量，不能由暖气放出。"}, {"text": "黑板太暗了，我们需要更多的光能才能看清字。", "explanation": "这里应该用〈光线〉。看清字需要的是亮光，光能指能量形式，不指照明的光线。"}, {"text": "音箱放出很大的光能。", "explanation": "这里应该用〈声音〉。音箱发出的是声波，光能不是声音，不能由音箱放出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26870, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小风车靠一只光能就能转起来。", "corrected_sentence": "这个小风车靠一点光能就能转起来。", "error_description": "错误：“一只光能”；正确：“一点光能”。光能是不可数的能量，不能用“只”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26870, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋顶上的电池板能收集一把光能。", "corrected_sentence": "屋顶上的电池板能收集一点光能。", "error_description": "错误：“一把光能”；正确：“一点光能”。“把”多用于有柄之物或“一把力气”之类的固定说法，光能是抽象的能量，不能用“把”计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
