INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26874, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "光通过三棱镜后分出的彩色带子，像彩虹一样。", "primary_collocate": null, "pronunciation": "guāng pǔ", "ipa": "kwɑŋ˥ pʰu˨˩˦", "syllable_count": 2, "sentences": [{"text": "光穿过三棱镜，就出现了彩色的光谱。", "target_word": "光谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光谱像彩虹一样，有很多颜色。", "target_word": "光谱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "墙上出现了一条漂亮的光谱。", "target_word": "光谱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明用三棱镜在桌上做出了光谱。", "target_word": "光谱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "光谱里有红、橙、黄、绿、蓝、紫。", "target_word": "光谱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "阳光穿过水珠，会形成光谱。", "target_word": "光谱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们观察光谱的颜色。", "target_word": "光谱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "光谱的一边是红色，另一边是紫色。", "target_word": "光谱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水晶挂件在墙上留下一道光谱。", "target_word": "光谱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们看到光谱里没有黑色。", "target_word": "光谱", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "光谱仪", "label": "复合"}], "register": "通俗", "sense_fingerprint": "光穿过三棱镜后分出的彩虹般的彩色带", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea0a212a-0dc6-478f-bf31-657d4bcdaa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26874, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花朵", "is_correct": false, "explanation": "语义：光穿过三棱镜，不会出现花朵。"}, {"text": "光谱", "is_correct": true, "explanation": "正确：三棱镜分出的彩色带就是光谱，与“彩色的光谱”相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：光穿过三棱镜，不会出现石头。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“彩色”修饰可见之物，不能修饰声音。"}], "explanations": {"花朵": "语义：光穿过三棱镜，不会出现花朵。", "光谱": "正确：三棱镜分出的彩色带就是光谱，与“彩色的光谱”相符。", "石头": "语义：光穿过三棱镜，不会出现石头。", "声音": "搭配：“彩色”修饰可见之物，不能修饰声音。"}, "sentence_index": 0, "correct_answer": "光谱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首曲子的光谱很优美。", "explanation": "这里应该用〈旋律〉。光谱是光分出的彩色带，描述乐曲的美感要用“旋律”。"}, {"text": "这件衣服的光谱很漂亮。", "explanation": "这里应该用〈花纹〉。衣服上的图案要说“花纹”，光谱是光分出的色带，不指织物图案。"}, {"text": "小明在纸上涂了很多光谱。", "explanation": "这里应该用〈颜料〉。光谱是光分出的色带，不是可以涂抹的颜料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26874, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "旋律", "is_correct": false, "explanation": "语义：旋律是声音，不能用来观察颜色。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“颜色”的承载者应是有形之物，“时间”不能作为颜色的载体。"}, {"text": "光谱", "is_correct": true, "explanation": "正确：光谱是有颜色的彩色带，老师让学生观察的正是它的颜色。"}, {"text": "气味", "is_correct": false, "explanation": "语义：气味没有颜色，不能用来观察颜色。"}], "explanations": {"旋律": "语义：旋律是声音，不能用来观察颜色。", "时间": "搭配：“颜色”的承载者应是有形之物，“时间”不能作为颜色的载体。", "光谱": "正确：光谱是有颜色的彩色带，老师让学生观察的正是它的颜色。", "气味": "语义：气味没有颜色，不能用来观察颜色。"}, "sentence_index": 6, "correct_answer": "光谱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "画家在画布上调配了丰富的光谱。", "explanation": "这里应该用〈色彩〉。光谱是光分出的色带，不是可以调配的颜料或色彩。"}, {"text": "墙上映出一个小孩的光谱。", "explanation": "这里应该用〈影子〉。人被光照后投在墙上的是影子，光谱是色带。"}, {"text": "他用光谱在纸上写了字。", "explanation": "这里应该用〈墨水〉。写字要用墨水，光谱是光分出的色带，不能用来书写。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26874, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "阳光穿过玻璃杯，墙上映出了一滴光谱。", "corrected_sentence": "阳光穿过玻璃杯，墙上映出了一道光谱。", "error_description": "错误：“一滴光谱”；正确：“一道光谱”。“滴”是液体的量词，光谱是一条彩色的光带，用“道”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26874, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一颗很漂亮的光谱。", "corrected_sentence": "这是一道很漂亮的光谱。", "error_description": "错误：“一颗光谱”；正确：“一道光谱”。“颗”用于圆粒状之物，光谱是一条彩色的带，用“道”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
