INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26876, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "像绳子绕在一起打成的疙瘩。", "primary_collocate": null, "pronunciation": "jié", "ipa": "tɕjɛ˧˥", "syllable_count": 1, "sentences": [{"text": "线团里有一个结，很难拆开。", "target_word": "结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "项链的链子缠成了一个结。", "target_word": "结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔线上有好几个结，钓鱼时容易断。", "target_word": "结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "耳机线乱成一团，中间还有个结。", "target_word": "结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩的头绳上有个结。", "target_word": "结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毛线打了结，织不下去了。", "target_word": "结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手指慢慢拉开线上的结。", "target_word": "结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这根绳子上的结解开。", "target_word": "结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风筝线上有个结，飞起来容易断。", "target_word": "结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风筝线缠在树枝上，打成了一个结。", "target_word": "结", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "結", "label": "繁体"}], "register": "中性", "sense_fingerprint": "绳线缠绕打成的疙瘩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '851baa46-0c4d-405d-9c2e-d5933994bbc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26876, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "结", "is_correct": true, "explanation": "jié（第二声），指线绳缠绕打成的疙瘩，即正确答案。"}, {"text": "解", "is_correct": false, "explanation": "jiě（第三声）与 jié（第二声）声调不同，意思是解开。"}, {"text": "借", "is_correct": false, "explanation": "jiè（第四声）与 jié（第二声）声调不同，意思是借用。"}, {"text": "街", "is_correct": false, "explanation": "jiē（第一声）与 jié（第二声）声调不同，意思是街道。"}, {"text": "斜", "is_correct": false, "explanation": "xié 与 jié 声母不同（x 与 j），意思是斜的。"}], "explanations": {"结": "jié（第二声），指线绳缠绕打成的疙瘩，即正确答案。", "解": "jiě（第三声）与 jié（第二声）声调不同，意思是解开。", "借": "jiè（第四声）与 jié（第二声）声调不同，意思是借用。", "街": "jiē（第一声）与 jié（第二声）声调不同，意思是街道。", "斜": "xié 与 jié 声母不同（x 与 j），意思是斜的。"}, "sentence_index": null, "correct_answer": "结"}, "level_3": {"options": [{"text": "结", "is_correct": true, "explanation": "正确：线团里缠成的疙瘩叫“结”，符合“很难拆开”。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：线团里不会有西瓜，句意不通。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：线团里放不下花瓶，与线团的描述相矛盾。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“拆开”不能用于窗户，与“很难拆开”搭配不当。"}], "explanations": {"结": "正确：线团里缠成的疙瘩叫“结”，符合“很难拆开”。", "西瓜": "语义：线团里不会有西瓜，句意不通。", "花瓶": "语义：线团里放不下花瓶，与线团的描述相矛盾。", "窗户": "搭配：“拆开”不能用于窗户，与“很难拆开”搭配不当。"}, "sentence_index": 0, "correct_answer": "结"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这棵树今年结了很多果子。", "explanation": "这里的“结”是动词，指植物长出果实，是另一个意思，不是线绳缠成的疙瘩。"}, {"text": "两家邻居因为一块地结了仇。", "explanation": "这里的“结”是动词“结仇”，指结下仇怨，是另一个意思，不是线绳缠成的疙瘩。"}, {"text": "这锅肉汤凉了，表面结了一层厚厚的油。", "explanation": "这里的“结”是动词，指液体冷却后凝成油膜，是另一个意思，不是线绳缠成的疙瘩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b8024f-b22b-4953-93e5-eab38a007145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26876, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "结", "is_correct": true, "explanation": "jié（第二声），指线绳缠绕打成的疙瘩，即正确答案。"}, {"text": "姐", "is_correct": false, "explanation": "jiě（第三声）与 jié（第二声）声调不同，意思是姐姐。"}, {"text": "界", "is_correct": false, "explanation": "jiè（第四声）与 jié（第二声）声调不同，意思是界限。"}, {"text": "接", "is_correct": false, "explanation": "jiē（第一声）与 jié（第二声）声调不同，意思是接住。"}, {"text": "鞋", "is_correct": false, "explanation": "xié 与 jié 声母不同（x 与 j），意思是鞋子。"}], "explanations": {"结": "jié（第二声），指线绳缠绕打成的疙瘩，即正确答案。", "姐": "jiě（第三声）与 jié（第二声）声调不同，意思是姐姐。", "界": "jiè（第四声）与 jié（第二声）声调不同，意思是界限。", "接": "jiē（第一声）与 jié（第二声）声调不同，意思是接住。", "鞋": "xié 与 jié 声母不同（x 与 j），意思是鞋子。"}, "sentence_index": null, "correct_answer": "结"}, "level_3": {"options": [{"text": "结", "is_correct": true, "explanation": "正确：线上缠成的结可以用手指慢慢拉开，句意通顺。"}, {"text": "螺丝", "is_correct": false, "explanation": "语义：螺丝不是线上的东西，句中的“线上的”无法指螺丝。"}, {"text": "水泥", "is_correct": false, "explanation": "搭配：“拉开”不能用于水泥，与“用手指慢慢拉开”搭配不当。"}, {"text": "锅", "is_correct": false, "explanation": "语义：线上不会有锅，句意不通。"}], "explanations": {"结": "正确：线上缠成的结可以用手指慢慢拉开，句意通顺。", "螺丝": "语义：螺丝不是线上的东西，句中的“线上的”无法指螺丝。", "水泥": "搭配：“拉开”不能用于水泥，与“用手指慢慢拉开”搭配不当。", "锅": "语义：线上不会有锅，句意不通。"}, "sentence_index": 6, "correct_answer": "结"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的胳膊上留下了一个结。", "explanation": "这里应该用〈疤〉。疤是伤口愈合后留下的痕迹，“结”指线绳缠成的疙瘩，不能指皮肤上的伤痕。"}, {"text": "冬天的湖面很快就结冰了。", "explanation": "这里的“结”是动词，指水遇冷凝成冰，是另一个意思，不是线绳缠成的疙瘩。"}, {"text": "他和那位老师结了缘，后来成了忘年交。", "explanation": "这里的“结”是动词“结缘”，指建立起缘分，是另一个意思，不是线绳缠成的疙瘩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b8024f-b22b-4953-93e5-eab38a007145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26876, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "耳机线缠成了一个结大。", "corrected_sentence": "耳机线缠成了一个大结。", "error_description": "语序错误：形容词“大”修饰“结”时应放在名词前，说“一个大结”，不能说“一个结大”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b8024f-b22b-4953-93e5-eab38a007145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26876, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把绳子在树枝上绕了一条结。", "corrected_sentence": "他把绳子在树枝上绕了一个结。", "error_description": "量词错误：“结”应搭配量词“个”，“条”用于细长的东西，不能修饰“结”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b8024f-b22b-4953-93e5-eab38a007145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
