INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26878, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "电池能让玩具动起来。", "primary_collocate": null, "pronunciation": "diàn chí", "ipa": "tjɛn˥˩ ʈʂʰʅ˧˥", "syllable_count": 2, "sentences": [{"text": "弟弟的玩具车里有电池。", "target_word": "电池", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把电池装进去，小车就跑了。", "target_word": "电池", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玩具不动了，可能是电池坏了。", "target_word": "电池", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我买了新电池。", "target_word": "电池", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小狗玩具要用两节电池。", "target_word": "电池", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开玩具，你会看到电池。", "target_word": "电池", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电池放对了，机器人就会走路。", "target_word": "电池", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有电池，玩具不能动。", "target_word": "电池", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从桌子上拿起一节电池。", "target_word": "电池", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电池用完了，玩具车停下来了。", "target_word": "电池", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "节", "label": "量词"}, {"form": "電池", "label": "繁体"}], "register": "中性", "sense_fingerprint": "让玩具动起来的电池", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea0a212a-0dc6-478f-bf31-657d4bcdaa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26878, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "电池", "is_correct": true, "explanation": "电池，diàn chí，让玩具动起来的装置。"}, {"text": "电磁", "is_correct": false, "explanation": "c 与 ch 声母不同，diàn cí 意思是电磁。"}, {"text": "电石", "is_correct": false, "explanation": "sh 与 ch 声母不同，diàn shí 意思是电石，一种化工原料。"}, {"text": "滇池", "is_correct": false, "explanation": "声调混淆：滇池 diān chí，首音节 diān 与 diàn 仅声调不同；滇池是云南湖名。"}], "explanations": {"电池": "电池，diàn chí，让玩具动起来的装置。", "电磁": "c 与 ch 声母不同，diàn cí 意思是电磁。", "电石": "sh 与 ch 声母不同，diàn shí 意思是电石，一种化工原料。", "滇池": "声调混淆：滇池 diān chí，首音节 diān 与 diàn 仅声调不同；滇池是云南湖名。"}, "sentence_index": null, "correct_answer": "电池"}, "level_3": {"options": [{"text": "电池", "is_correct": true, "explanation": "玩具车里装的是电池，才能让小车动起来。"}, {"text": "面条", "is_correct": false, "explanation": "语义：面条是食物，不会装在玩具车里让它动起来。"}, {"text": "白菜", "is_correct": false, "explanation": "语义：白菜是蔬菜，与玩具车的动力无关。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是挡雨的，不会装在玩具车里让它动起来。"}], "explanations": {"电池": "玩具车里装的是电池，才能让小车动起来。", "面条": "语义：面条是食物，不会装在玩具车里让它动起来。", "白菜": "语义：白菜是蔬菜，与玩具车的动力无关。", "雨伞": "语义：雨伞是挡雨的，不会装在玩具车里让它动起来。"}, "sentence_index": 0, "correct_answer": "电池"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天早上用电池煮面条。", "explanation": "这里应该用〈锅〉。煮面条要用锅，电池不能用来煮东西。"}, {"text": "我每天晚上用电池刷牙。", "explanation": "这里应该用〈牙刷〉。电池不能刷牙，“刷牙”要用牙刷。"}, {"text": "我每天早上用电池梳头。", "explanation": "这里应该用〈梳子〉。“梳头”要用梳子，电池不能梳头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26878, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电池", "is_correct": true, "explanation": "电池放对了，机器人才会走路，句中的“电池”指让机器运转的装置。"}, {"text": "衣服", "is_correct": false, "explanation": "语义：衣服不能让机器人走路，与“放对了”的语境不符。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食物，不能为机器人提供动力。"}, {"text": "铅笔", "is_correct": false, "explanation": "搭配：“放对了”指装置的安装，铅笔不能让机器人走路。"}], "explanations": {"电池": "电池放对了，机器人才会走路，句中的“电池”指让机器运转的装置。", "衣服": "语义：衣服不能让机器人走路，与“放对了”的语境不符。", "饼干": "语义：饼干是食物，不能为机器人提供动力。", "铅笔": "搭配：“放对了”指装置的安装，铅笔不能让机器人走路。"}, "sentence_index": 6, "correct_answer": "电池"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在河边钓了一条电池。", "explanation": "这里应该用〈鱼〉。“钓”的对象是鱼，电池不能钓。"}, {"text": "我吃了一个电池。", "explanation": "这里应该用〈苹果〉。“吃”的对象是食物，电池不能吃。"}, {"text": "爸爸在院子里种了一棵电池。", "explanation": "这里应该用〈树〉。“种”的对象是植物，电池不能种。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26878, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把电池装了好，玩具车就能跑了。", "corrected_sentence": "他把电池装好了，玩具车就能跑了。", "error_description": "补语位置错误。结果补语“好”要紧跟动词，应说“装好了”，不能说“装了好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4725c4d2-db26-4ab1-9195-72641fba2ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
