INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26880, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "柔软，可以弯一弯。", "primary_collocate": null, "pronunciation": "róu xìng", "ipa": "ɻou̯˧˥ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这是一块柔性屏幕，可以弯一弯。", "target_word": "柔性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "柔性塑料不怕弯，也不容易断。", "target_word": "柔性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把柔性尺子量腰围很方便。", "target_word": "柔性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种柔性电池可以弯着用。", "target_word": "柔性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把柔性电路板装进手表里。", "target_word": "柔性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种柔性管道比硬管道好装。", "target_word": "柔性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用柔性内窥镜检查胃。", "target_word": "柔性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张柔性桌垫可以卷起来。", "target_word": "柔性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条柔性灯带可以绕着杆子弯。", "target_word": "柔性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "柔性手环戴着很舒服。", "target_word": "柔性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "柔性材料", "label": "复合"}, {"form": "柔性屏", "label": "复合"}], "register": "书面", "sense_fingerprint": "柔性|形容词|柔软可弯折，作定语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45a9c2e1-e793-492c-857c-afaaaa0fdb5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26880, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "柔性", "is_correct": true, "explanation": "柔性是形容词，修饰屏幕，指柔软可弯折，与“可以弯一弯”相符。"}, {"text": "坚硬", "is_correct": false, "explanation": "语义：坚硬的屏幕不能弯，与“可以弯一弯”矛盾。"}, {"text": "僵硬", "is_correct": false, "explanation": "语义：僵硬指不能弯曲，与“可以弯一弯”矛盾。"}, {"text": "黑暗", "is_correct": false, "explanation": "搭配：“黑暗”形容光线或环境，不能用来描述屏幕，句子不通。"}], "explanations": {"柔性": "柔性是形容词，修饰屏幕，指柔软可弯折，与“可以弯一弯”相符。", "坚硬": "语义：坚硬的屏幕不能弯，与“可以弯一弯”矛盾。", "僵硬": "语义：僵硬指不能弯曲，与“可以弯一弯”矛盾。", "黑暗": "搭配：“黑暗”形容光线或环境，不能用来描述屏幕，句子不通。"}, "sentence_index": 0, "correct_answer": "柔性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的语气很柔性，让人听着很舒服。", "explanation": "这里应该用〈柔和〉。形容语气、声音要用柔和，柔性指物体柔软、可弯折。"}, {"text": "她的性格很柔性，朋友都喜欢她。", "explanation": "这里应该用〈温柔〉。形容人的性格要用温柔，柔性只用于物体。"}, {"text": "今天的天气很柔性，适合去公园。", "explanation": "这里应该用〈温和〉。形容天气的舒适要用温和，柔性指物体可弯曲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd58b4158-fc4d-43e1-a537-f329b4639f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26880, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "柔性", "is_correct": true, "explanation": "柔性修饰内窥镜，指可弯曲，符合医学检查的场景。"}, {"text": "脆弱", "is_correct": false, "explanation": "语义：脆弱的器械容易折断，与插入胃部的要求矛盾。"}, {"text": "辛苦", "is_correct": false, "explanation": "搭配：“辛苦”形容人或劳动，不用来修饰器械。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：清脆形容声音，不能修饰检查器械。"}], "explanations": {"柔性": "柔性修饰内窥镜，指可弯曲，符合医学检查的场景。", "脆弱": "语义：脆弱的器械容易折断，与插入胃部的要求矛盾。", "辛苦": "搭配：“辛苦”形容人或劳动，不用来修饰器械。", "清脆": "语义：清脆形容声音，不能修饰检查器械。"}, "sentence_index": 6, "correct_answer": "柔性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只小猫很柔性，见了人就亲。", "explanation": "这里应该用〈温顺〉。形容动物或人的脾气要用温顺，柔性指物体的可弯折。"}, {"text": "体操运动员的身体很柔性，能做很多动作。", "explanation": "这里应该用〈柔韧〉。形容人的身体能弯折、伸展要用柔韧，柔性只用于物体。"}, {"text": "这个句子很柔性，意思很清楚。", "explanation": "这里应该用〈通顺〉。形容句子表达流畅要用通顺，柔性只用于物体的柔软或可弯曲，不能形容句子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd58b4158-fc4d-43e1-a537-f329b4639f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26880, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块很柔性屏幕能卷起来。", "corrected_sentence": "这块柔性屏幕能卷起来。", "error_description": "程度副词“很”不能直接修饰作定语的“柔性”，“很柔性屏幕”不成立；应去掉“很”，说“柔性屏幕”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd58b4158-fc4d-43e1-a537-f329b4639f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26880, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条灯带是柔性，可以绕着杆子弯。", "corrected_sentence": "这条灯带是柔性的，可以绕着杆子弯。", "error_description": "“柔性”是区别词，不能直接放在“是”后面作宾语；要用“是……的”，句末缺“的”，应说“灯带是柔性的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd58b4158-fc4d-43e1-a537-f329b4639f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
