INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26890, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "风吹动时产生的能量，可以用来发电。", "primary_collocate": null, "pronunciation": "fēng néng", "ipa": "fɤŋ˥ nɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "风能可以用来发电。", "target_word": "风能", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "风越大，风能就越多。", "target_word": "风能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风车靠风能转动。", "target_word": "风能", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "太阳能和风能都是干净的能源。", "target_word": "风能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海边风大，人们用风能点灯。", "target_word": "风能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你知道风能是怎么发电的吗？", "target_word": "风能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用风能不用买煤。", "target_word": "风能", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个国家的风能很多，电很便宜。", "target_word": "风能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大风车靠风能一直转个不停。", "target_word": "风能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校的灯是用风能发的电。", "target_word": "风能", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "風能", "label": "繁体"}, {"form": "风能发电", "label": "复合"}], "register": "书面", "sense_fingerprint": "风吹动时产生的力量，可以用来发电", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45a9c2e1-e793-492c-857c-afaaaa0fdb5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26890, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "风能", "is_correct": true, "explanation": "风能是风吹动时产生的力量，可以用来发电，与句意相符。"}, {"text": "风景", "is_correct": false, "explanation": "语义：风景是景致，不能用来发电，句子不成立。"}, {"text": "风险", "is_correct": false, "explanation": "搭配：“风险”说的是危害，不与“用来发电”搭配。"}, {"text": "风气", "is_correct": false, "explanation": "语义：风气指社会风尚，不是能源，“风气可以用来发电”说不通。"}], "explanations": {"风能": "风能是风吹动时产生的力量，可以用来发电，与句意相符。", "风景": "语义：风景是景致，不能用来发电，句子不成立。", "风险": "搭配：“风险”说的是危害，不与“用来发电”搭配。", "风气": "语义：风气指社会风尚，不是能源，“风气可以用来发电”说不通。"}, "sentence_index": 0, "correct_answer": "风能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座海边电站的风能场很大。", "explanation": "这里应该用〈风电场〉。风能指能量，成片的发电设施叫风电场，不说“风能场”。"}, {"text": "今天的风能每小时有六十公里，很危险。", "explanation": "这里应该用〈风速〉。描述风每小时多少公里要用风速；风能是能量，不用速度计量。"}, {"text": "这台风能很重，搬不动。", "explanation": "这里应该用〈风力发电机〉。风能是能量，不是可以搬动的设备，说“很重、搬不动”要用设备名称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd58b4158-fc4d-43e1-a537-f329b4639f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26890, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "风能", "is_correct": true, "explanation": "风能是风的能量，可以代替煤，句意是“用风能不用买煤”。"}, {"text": "风度", "is_correct": false, "explanation": "语义：风度指举止气质，不能代替煤作能源，句子说不通。"}, {"text": "风俗", "is_correct": false, "explanation": "语义：风俗是社会习惯，不是燃料，无法替代煤。"}, {"text": "风雨", "is_correct": false, "explanation": "搭配：“用……不用买煤”要求能源类词作宾语，“风雨”不能与“用”搭配。"}], "explanations": {"风能": "风能是风的能量，可以代替煤，句意是“用风能不用买煤”。", "风度": "语义：风度指举止气质，不能代替煤作能源，句子说不通。", "风俗": "语义：风俗是社会习惯，不是燃料，无法替代煤。", "风雨": "搭配：“用……不用买煤”要求能源类词作宾语，“风雨”不能与“用”搭配。"}, "sentence_index": 6, "correct_answer": "风能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "田野里有一排白色的风能，很好看。", "explanation": "这里应该用〈风车〉。风车是看得见的设备，风能是能量，看不见。"}, {"text": "海上起了很大的风能，船都回港了。", "explanation": "这里应该用〈风浪〉。海上的大风大浪叫风浪，风能是能量，不说“起了风能”。"}, {"text": "天气预报说，明天的风能是北风。", "explanation": "这里应该用〈风向〉。北风说的是风吹来的方向，风能是能量，没有方向。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd58b4158-fc4d-43e1-a537-f329b4639f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26890, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小站用的是一只风能。", "corrected_sentence": "这个小站用的是一种风能。", "error_description": "“风能”是能源类名词，量词应用“种”；“只”多用于动物或单个物品，用在能源上不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd58b4158-fc4d-43e1-a537-f329b4639f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26890, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "渔村的人们用风能的点灯。", "corrected_sentence": "渔村的人们用风能点灯。", "error_description": "“用风能点灯”中“风能”后不能加“的”，“的”不能接在名词与动词之间；“用……点灯”直接连接，应去掉“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd58b4158-fc4d-43e1-a537-f329b4639f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
