INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26892, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "半导体是一种材料，它有时候导电，有时候不导电。", "primary_collocate": null, "pronunciation": "bàn dǎo tǐ", "ipa": "pan˥˩ taʊ˨˩˦ tʰi˨˩˦", "syllable_count": 3, "sentences": [{"text": "半导体有时候导电，有时候不导电。", "target_word": "半导体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师拿出一块半导体给我们看。", "target_word": "半导体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "半导体可以用来做电脑。", "target_word": "半导体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块半导体是什么颜色的？", "target_word": "半导体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为什么半导体不是普通的材料？", "target_word": "半导体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太热的时候，半导体会更容易导电。", "target_word": "半导体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在书里研究了半导体的导电原理。", "target_word": "半导体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室里有一块小的半导体。", "target_word": "半导体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "半导体不是金属，也不是塑料。", "target_word": "半导体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多电器里面都有半导体。", "target_word": "半导体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "半導體", "label": "繁体"}, {"form": "半导体材料", "label": "复合"}, {"form": "半导体行业", "label": "复合"}], "register": "中性", "sense_fingerprint": "一种有时导电、有时不导电的材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bff2398e-8e1d-4c42-88b1-9e5a19e189a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26892, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "绝缘体", "is_correct": false, "explanation": "语义：绝缘体从不导电，与“有时候导电”相矛盾。"}, {"text": "半导体", "is_correct": true, "explanation": "半导体：导电性随条件变化，有时导电，有时不导电，符合句子描述。"}, {"text": "电池", "is_correct": false, "explanation": "搭配：“导电”描述材料的属性，“电池”是电器部件，不能说“电池有时候导电”。"}, {"text": "金属", "is_correct": false, "explanation": "语义：金属通常一直导电，与“有时候不导电”相矛盾。"}], "explanations": {"绝缘体": "语义：绝缘体从不导电，与“有时候导电”相矛盾。", "半导体": "半导体：导电性随条件变化，有时导电，有时不导电，符合句子描述。", "电池": "搭配：“导电”描述材料的属性，“电池”是电器部件，不能说“电池有时候导电”。", "金属": "语义：金属通常一直导电，与“有时候不导电”相矛盾。"}, "sentence_index": 0, "correct_answer": "半导体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "为了让电流顺利通过，电线的芯子应该用半导体。", "explanation": "这里应该用〈导体〉。电线芯子需要导电能力稳定的材料，半导体有时不导电，不能用作芯子。"}, {"text": "为了防止漏电，我们在电线外面包了一层导电的半导体。", "explanation": "这里应该用〈绝缘体〉。防漏电的外皮需要不导电的绝缘体，会导电的半导体不能用。"}, {"text": "这个门把手是用半导体做的，因为它很结实，不容易变形。", "explanation": "这里应该用〈金属〉。门把手需要结实、不易变形的材料，半导体（如硅）质地脆，不是这类用途的常用材料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc0c84d7-0962-4ade-b4e4-82cb24de3b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26892, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "八卦", "is_correct": false, "explanation": "语义：“八卦”是闲话，与讲导电原理的科学内容不合。"}, {"text": "小说", "is_correct": false, "explanation": "语义：“小说”是文体，不能被研究出导电原理，与句意不合。"}, {"text": "半导体", "is_correct": true, "explanation": "半导体：书中研究的是半导体的导电原理，符合句子语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”没有可研究的“导电原理”，与句意不合。"}], "explanations": {"八卦": "语义：“八卦”是闲话，与讲导电原理的科学内容不合。", "小说": "语义：“小说”是文体，不能被研究出导电原理，与句意不合。", "半导体": "半导体：书中研究的是半导体的导电原理，符合句子语境。", "天气": "语义：“天气”没有可研究的“导电原理”，与句意不合。"}, "sentence_index": 6, "correct_answer": "半导体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天冷了，妈妈给我买了一件半导体做的毛衣。", "explanation": "这里应该用〈羊毛〉。毛衣用羊毛等纤维做，半导体是做电器的材料，不能织衣服。"}, {"text": "我饿了，想吃一块半导体。", "explanation": "这里应该用〈面包〉。半导体是一种材料，不能吃。"}, {"text": "这条河里的半导体很清，可以看到鱼。", "explanation": "这里应该用〈水〉。河里流的是水，半导体是固体材料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc0c84d7-0962-4ade-b4e4-82cb24de3b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26892, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "半导体了很特别，有时导电，有时不导电。", "corrected_sentence": "半导体很特别，有时导电，有时不导电。", "error_description": "错误形式是在名词“半导体”后多加了“了”，写作“半导体了很特别”；正确形式是“半导体很特别”。形容词作谓语时，“了”不能紧跟在作主语的名词后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc0c84d7-0962-4ade-b4e4-82cb24de3b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26892, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师递给我一只半导体，说它很特别。", "corrected_sentence": "老师递给我一块半导体，说它很特别。", "error_description": "“只”是动物量词，不能用来计量“半导体”；应为“块”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc0c84d7-0962-4ade-b4e4-82cb24de3b17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
