INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26896, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "轴是轮子中间穿过的棍子。", "primary_collocate": null, "pronunciation": "zhóu", "ipa": "ʈʂou˧˥", "syllable_count": 1, "sentences": [{"text": "小车的轮子中间有一根轴。", "target_word": "轴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们把木棍当成轴，做了一辆小车。", "target_word": "轴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆玩具车的轴弯了。", "target_word": "轴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "轮子绕着轴转个不停。", "target_word": "轴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸给自行车的轴加了点油。", "target_word": "轴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根轴穿过轮子的中间。", "target_word": "轴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给小车重新换了一根轴，车子又能跑了。", "target_word": "轴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车轮掉了，是因为轴断了。", "target_word": "轴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "轴要直，车才跑得稳。", "target_word": "轴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用一根铁棍做了车上的轴。", "target_word": "轴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "根", "label": "量词"}, {"form": "车轴", "label": "复合"}, {"form": "轴承", "label": "复合"}, {"form": "軸", "label": "繁体"}], "register": "中性", "sense_fingerprint": "从轮子中间穿过、让轮子转动的棍状东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757ee6c7-0919-4ea7-a065-58cc869d02b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26896, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "轴", "is_correct": true, "explanation": "正确。zhóu（第二声）指从轮子中间穿过、让轮子转动的棍状东西。"}, {"text": "周", "is_correct": false, "explanation": "zhōu（第一声）与 zhóu（第二声）声调不同，意思是周围、周期。"}, {"text": "肘", "is_correct": false, "explanation": "zhǒu（第三声）与 zhóu（第二声）声调不同，意思是手臂中间的关节。"}, {"text": "愁", "is_correct": false, "explanation": "chóu 与 zhóu 声母不同（ch 与 zh），意思是忧愁。"}, {"text": "皱", "is_correct": false, "explanation": "zhòu（第四声）与 zhóu（第二声）声调不同，意思是衣物或皮肤上的褶痕。"}], "explanations": {"轴": "正确。zhóu（第二声）指从轮子中间穿过、让轮子转动的棍状东西。", "周": "zhōu（第一声）与 zhóu（第二声）声调不同，意思是周围、周期。", "肘": "zhǒu（第三声）与 zhóu（第二声）声调不同，意思是手臂中间的关节。", "愁": "chóu 与 zhóu 声母不同（ch 与 zh），意思是忧愁。", "皱": "zhòu（第四声）与 zhóu（第二声）声调不同，意思是衣物或皮肤上的褶痕。"}, "sentence_index": null, "correct_answer": "轴"}, "level_3": {"options": [{"text": "轴", "is_correct": true, "explanation": "正确。「轴」指从轮子中间穿过的棍状东西，符合句意。"}, {"text": "烟囱", "is_correct": false, "explanation": "语义：烟囱是排烟的管道，不装在车轮中间，与句意不符。"}, {"text": "电线", "is_correct": false, "explanation": "语义：电线用于输送电流，不能穿在车轮中间起支撑作用。"}, {"text": "绳子", "is_correct": false, "explanation": "体貌：绳子柔软，不是棍状的硬质构件，与轴的形状不符。"}], "explanations": {"轴": "正确。「轴」指从轮子中间穿过的棍状东西，符合句意。", "烟囱": "语义：烟囱是排烟的管道，不装在车轮中间，与句意不符。", "电线": "语义：电线用于输送电流，不能穿在车轮中间起支撑作用。", "绳子": "体貌：绳子柔软，不是棍状的硬质构件，与轴的形状不符。"}, "sentence_index": 0, "correct_answer": "轴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把一根木轴插进花瓶里。", "explanation": "这里应该用〈花枝〉。轴是穿过轮子中间的棍子，插进花瓶要用「花枝」。"}, {"text": "门口的台阶旁立着一根石轴。", "explanation": "这里应该用〈石柱〉。轴是穿过轮子中间的棍子，立在地上的支柱要用「柱」。"}, {"text": "他拿着一根木轴在地上画线。", "explanation": "这里应该用〈木棍〉。轴是穿过轮子中间的棍子，拿在手里画线的棍子要用「棍」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c941484-a894-4f87-99ac-3fcd636edfd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26896, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "轴", "is_correct": true, "explanation": "正确。zhóu（第二声）指从轮子中间穿过、让轮子转动的棍状东西。"}, {"text": "粥", "is_correct": false, "explanation": "zhōu（第一声）与 zhóu（第二声）声调不同，意思是稀饭。"}, {"text": "昼", "is_correct": false, "explanation": "zhòu（第四声）与 zhóu（第二声）声调不同，意思是白天。"}, {"text": "筹", "is_correct": false, "explanation": "chóu 与 zhóu 声母不同（ch 与 zh），意思是筹划、筹集。"}, {"text": "州", "is_correct": false, "explanation": "zhōu（第一声）与 zhóu（第二声）声调不同，意思是行政区划。"}], "explanations": {"轴": "正确。zhóu（第二声）指从轮子中间穿过、让轮子转动的棍状东西。", "粥": "zhōu（第一声）与 zhóu（第二声）声调不同，意思是稀饭。", "昼": "zhòu（第四声）与 zhóu（第二声）声调不同，意思是白天。", "筹": "chóu 与 zhóu 声母不同（ch 与 zh），意思是筹划、筹集。", "州": "zhōu（第一声）与 zhóu（第二声）声调不同，意思是行政区划。"}, "sentence_index": null, "correct_answer": "轴"}, "level_3": {"options": [{"text": "轴", "is_correct": true, "explanation": "正确。「轴」指轮子中间的棍状东西，「车子又能跑」与其作用相合。"}, {"text": "香肠", "is_correct": false, "explanation": "语义：香肠是食物，装不到车上，不能让车子重新跑起来。"}, {"text": "栏杆", "is_correct": false, "explanation": "语义：栏杆是围护用的构件，不是车子的传动部件。"}, {"text": "灯管", "is_correct": false, "explanation": "搭配：灯管是照明器材，不能与车子的行驶搭配。"}], "explanations": {"轴": "正确。「轴」指轮子中间的棍状东西，「车子又能跑」与其作用相合。", "香肠": "语义：香肠是食物，装不到车上，不能让车子重新跑起来。", "栏杆": "语义：栏杆是围护用的构件，不是车子的传动部件。", "灯管": "搭配：灯管是照明器材，不能与车子的行驶搭配。"}, "sentence_index": 6, "correct_answer": "轴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用一根细轴拴住了小车。", "explanation": "这里应该用〈细绳〉。轴是穿过轮子中间的棍子，拴东西要用「绳」。"}, {"text": "工人用两根木轴搭了一座小桥。", "explanation": "这里应该用〈木板〉。轴是穿过轮子中间的棍子，搭桥要用「木板」。"}, {"text": "墙上钉着一根铁轴。", "explanation": "这里应该用〈铁钉〉。轴是穿过轮子中间的棍子，钉在墙上的要用「铁钉」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c941484-a894-4f87-99ac-3fcd636edfd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26896, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这辆玩具车装上了一只新轴。", "corrected_sentence": "这辆玩具车装上了一根新轴。", "error_description": "量词错误：轴是棍状东西，应用「根」，「只」多用于动物。「一只新轴」应改为「一根新轴」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c941484-a894-4f87-99ac-3fcd636edfd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26896, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "修车的师傅给小车换了一块轴。", "corrected_sentence": "修车的师傅给小车换了一根轴。", "error_description": "量词错误：轴是棍状东西，应用「根」，「块」多用于块状物。「一块轴」应改为「一根轴」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c941484-a894-4f87-99ac-3fcd636edfd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
