INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26900, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "抓住或捉到，比如小猫捉到老鼠。", "primary_collocate": null, "pronunciation": "bǔ huò", "ipa": "pu˨˩˦ xwɔ˥˩", "syllable_count": 2, "sentences": [{"text": "小猫捕获了一只老鼠。", "target_word": "捕获", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷在河边捕获了几条鱼。", "target_word": "捕获", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜘蛛用网捕获小虫。", "target_word": "捕获", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小熊在河里捕获了一条鱼。", "target_word": "捕获", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老鹰捕获了一只兔子。", "target_word": "捕获", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子用网捕获了一只蝴蝶。", "target_word": "捕获", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "渔夫在河边坐了一整天，什么也没捕获。", "target_word": "捕获", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "青蛙一下子捕获了飞虫。", "target_word": "捕获", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夜里，猫头鹰捕获了老鼠。", "target_word": "捕获", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想捕获一只萤火虫。", "target_word": "捕获", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "捕获了", "label": "体标"}, {"form": "捕获过", "label": "体标"}], "register": "中性", "sense_fingerprint": "抓住或捉到动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757ee6c7-0919-4ea7-a065-58cc869d02b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26900, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "捕获", "is_correct": true, "explanation": "正确。「捕获」指抓住或捉到动物，这里指小猫捉到了老鼠。"}, {"text": "打碎", "is_correct": false, "explanation": "语义：「打碎」指使物体破裂，不能用于老鼠，与句意不符。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：「修理」多用于器物，不说修理老鼠。"}, {"text": "缝补", "is_correct": false, "explanation": "搭配：「缝补」用于衣物，不能用于老鼠。"}], "explanations": {"捕获": "正确。「捕获」指抓住或捉到动物，这里指小猫捉到了老鼠。", "打碎": "语义：「打碎」指使物体破裂，不能用于老鼠，与句意不符。", "修理": "搭配：「修理」多用于器物，不说修理老鼠。", "缝补": "搭配：「缝补」用于衣物，不能用于老鼠。"}, "sentence_index": 0, "correct_answer": "捕获"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在比赛中捕获了第一名。", "explanation": "这里应该用〈获得〉。捕获指捉住动物等有形目标，名次要用「获得」。"}, {"text": "农民秋天捕获了一大片麦子。", "explanation": "这里应该用〈收割〉。捕获针对要捉住的动物，庄稼要用「收割」。"}, {"text": "他用皮尺捕获了桌子的长度。", "explanation": "这里应该用〈测量〉。捕获指捉住目标，长度要用「测量」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c941484-a894-4f87-99ac-3fcd636edfd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26900, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "捕获", "is_correct": true, "explanation": "正确。「捕获」指抓住或捉到动物，这里指渔夫今天没有捉到任何东西。"}, {"text": "耕种", "is_correct": false, "explanation": "语义：「耕种」指耕地种植，渔夫的工作不涉及耕种，与句意不符。"}, {"text": "缝制", "is_correct": false, "explanation": "搭配：「缝制」的对象多是布料、衣物，不能与渔夫的工作搭配。"}, {"text": "雕刻", "is_correct": false, "explanation": "语义：「雕刻」指在木头、石头上刻东西，渔夫在河边等的是鱼，不是雕刻，与句意不符。"}], "explanations": {"捕获": "正确。「捕获」指抓住或捉到动物，这里指渔夫今天没有捉到任何东西。", "耕种": "语义：「耕种」指耕地种植，渔夫的工作不涉及耕种，与句意不符。", "缝制": "搭配：「缝制」的对象多是布料、衣物，不能与渔夫的工作搭配。", "雕刻": "语义：「雕刻」指在木头、石头上刻东西，渔夫在河边等的是鱼，不是雕刻，与句意不符。"}, "sentence_index": 6, "correct_answer": "捕获"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很快捕获了那道数学题。", "explanation": "这里应该用〈解答〉。捕获针对要捉住的目标，题目要用「解答」。"}, {"text": "他在草地上捕获了一朵花。", "explanation": "这里应该用〈采〉。捕获指捉住逃跑的目标，花朵要用「采」。"}, {"text": "他在厨房里捕获了一锅汤。", "explanation": "这里应该用〈盛〉。捕获指捉住目标，汤要用「盛」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c941484-a894-4f87-99ac-3fcd636edfd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26900, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小猫昨天捕获着一只老鼠。", "corrected_sentence": "小猫昨天捕获了一只老鼠。", "error_description": "体标误用：「捕获」是一下子完成的动作，不能带持续体「着」；表示已经捉到要用「了」，应改为「捕获了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c941484-a894-4f87-99ac-3fcd636edfd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26900, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天他要捕获了一只鸟。", "corrected_sentence": "明天他要捕获一只鸟。", "error_description": "「了」用错：「明天」「要」表示将来，将来的动作不能带「了」，「要捕获了」应改为「要捕获」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c941484-a894-4f87-99ac-3fcd636edfd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
