INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26902, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "扫风就是空调让风吹来吹去。", "primary_collocate": null, "pronunciation": "sǎo fēng", "ipa": "sɑʊ˨˩˦ fɤŋ˥", "syllable_count": 2, "sentences": [{"text": "扫风就是让空调的风左右吹。", "target_word": "扫风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家空调的扫风很安静。", "target_word": "扫风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按这个键就能开启扫风。", "target_word": "扫风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公室里开着扫风，大家都不冷。", "target_word": "扫风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喜欢扫风，说风吹来吹去很烦。", "target_word": "扫风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把扫风关了，我有点冷。", "target_word": "扫风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新买的空调扫风范围很大。", "target_word": "扫风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个扫风模式适合大房间。", "target_word": "扫风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热的时候，我会先开扫风。", "target_word": "扫风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说扫风比直吹舒服。", "target_word": "扫风", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "空调让风左右吹来吹去的功能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bc6cb3f-8b0d-40c9-96c0-695a89fc73a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26902, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扫风", "is_correct": true, "explanation": "正确：“扫风”指空调的风左右吹来吹去的功能，与句子的解释相符。"}, {"text": "直吹", "is_correct": false, "explanation": "语义：“直吹”指风直直地吹，与“左右吹”的方向相矛盾。"}, {"text": "制冷", "is_correct": false, "explanation": "语义：“制冷”指降低温度，不是风左右吹的方式。"}, {"text": "定时", "is_correct": false, "explanation": "搭配：“定时”指设定时间，不能用来解释风的吹动方式。"}], "explanations": {"扫风": "正确：“扫风”指空调的风左右吹来吹去的功能，与句子的解释相符。", "直吹": "语义：“直吹”指风直直地吹，与“左右吹”的方向相矛盾。", "制冷": "语义：“制冷”指降低温度，不是风左右吹的方式。", "定时": "搭配：“定时”指设定时间，不能用来解释风的吹动方式。"}, "sentence_index": 0, "correct_answer": "扫风"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用扫风把地扫干净了。", "explanation": "错用：“扫风”是空调的功能，不是清扫地面的工具或动作。"}, {"text": "扫风的颜色很红。", "explanation": "错用：“扫风”是功能，不能用来描述颜色。"}, {"text": "我把扫风放进了冰箱。", "explanation": "错用：“扫风”是功能，不是可以放进冰箱的物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cfefa4b-113e-42b5-a138-9b8d03182658') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26902, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "扫风", "is_correct": true, "explanation": "正确：“新买的空调扫风范围很大”指空调风向摆动覆盖的范围，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”没有范围大小的说法，与“范围”的搭配不符。"}, {"text": "花纹", "is_correct": false, "explanation": "语义：“花纹”描述外观图案，不能用来说明范围大小。"}, {"text": "手感", "is_correct": false, "explanation": "搭配：“手感”指触摸时的感觉，不能与“范围”搭配。"}], "explanations": {"扫风": "正确：“新买的空调扫风范围很大”指空调风向摆动覆盖的范围，符合句意。", "颜色": "语义：“颜色”没有范围大小的说法，与“范围”的搭配不符。", "花纹": "语义：“花纹”描述外观图案，不能用来说明范围大小。", "手感": "搭配：“手感”指触摸时的感觉，不能与“范围”搭配。"}, "sentence_index": 6, "correct_answer": "扫风"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈说扫风是拿来扫地的。", "explanation": "错用：“扫风”指空调的风向摆动功能，不是扫地的工具。"}, {"text": "妈妈说扫风很甜。", "explanation": "错用：“扫风”是功能，不能用来描述味道。"}, {"text": "我家煮饭用的就是扫风。", "explanation": "错用：“扫风”指空调让风左右吹的功能，不是煮饭用的器具，这句把它当成了厨房器具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cfefa4b-113e-42b5-a138-9b8d03182658') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26902, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台空调有一只扫风模式。", "corrected_sentence": "这台空调有一种扫风模式。", "error_description": "“扫风模式”的量词应用“种”，不能用“只”（“只”多用于动物或成对的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cfefa4b-113e-42b5-a138-9b8d03182658') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26902, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请把扫风打，我有点热。", "corrected_sentence": "请把扫风打开，我有点热。", "error_description": "错误形式：“请把扫风打”。正确形式：“请把扫风打开”。“打”单独使用时不能表示开启空调，要补上结果补语“开”，构成“打开”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cfefa4b-113e-42b5-a138-9b8d03182658') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
