INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26906, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "风电场是很多大风车一起发电的地方。", "primary_collocate": null, "pronunciation": "fēng diàn chǎng", "ipa": "fɤŋ˥ tjɛn˥˩ ʈʂʰaŋ˨˩˦", "syllable_count": 3, "sentences": [{"text": "风电场里有很多大风车。", "target_word": "风电场", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "风吹过风电场，风车就转起来。", "target_word": "风电场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天我们去山上的风电场玩。", "target_word": "风电场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风电场发的电可以给城市用。", "target_word": "风电场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风电场一般建在风大的地方。", "target_word": "风电场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们站在风电场旁看风车。", "target_word": "风电场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个风电场离我们学校不远。", "target_word": "风电场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有风的时候，风电场就不发电。", "target_word": "风电场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸的工作是照看风电场。", "target_word": "风电场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那片草地上新建了一座风电场。", "target_word": "风电场", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "海上风电场", "label": "复合"}, {"form": "風電場", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很多大风车一起发电的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65bf7ffb-9382-49a3-a249-55e085870a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26906, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "风电场", "is_correct": true, "explanation": "正确：“风电场”是很多大风车一起发电的地方，与“有很多大风车”相符。"}, {"text": "停车场", "is_correct": false, "explanation": "语义：“停车场”是停放车辆的地方，与“大风车”不相干。"}, {"text": "操场", "is_correct": false, "explanation": "语义：“操场”是供体育活动的场地，不会成排摆放大风车，句子不通。"}, {"text": "加油站", "is_correct": false, "explanation": "语义：“加油站”是给车辆加油的地方，与句中的大风车不符。"}], "explanations": {"风电场": "正确：“风电场”是很多大风车一起发电的地方，与“有很多大风车”相符。", "停车场": "语义：“停车场”是停放车辆的地方，与“大风车”不相干。", "操场": "语义：“操场”是供体育活动的场地，不会成排摆放大风车，句子不通。", "加油站": "语义：“加油站”是给车辆加油的地方，与句中的大风车不符。"}, "sentence_index": 0, "correct_answer": "风电场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "山顶上的风电场是一座小屋，里面住着一家人。", "explanation": "这里应该用〈住宅〉。风电场是发电的场所，不供人居住；供一家人住的要用“住宅”。"}, {"text": "这个风电场靠阳光发电。", "explanation": "这里应该用〈太阳能电站〉。风电场靠风力发电，不靠阳光；靠阳光发电的是太阳能电站。"}, {"text": "路边有座风电场，正在卖水果。", "explanation": "这里应该用〈水果摊〉。风电场是发电的场所，不卖水果；卖水果要用“水果摊”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26906, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "风电场", "is_correct": true, "explanation": "正确：“风电场”是一个场所，可以说它离学校远近，句子通顺。"}, {"text": "电视", "is_correct": false, "explanation": "语义：“电视”不是地点，不能说“离我们学校不远”。"}, {"text": "食品", "is_correct": false, "explanation": "搭配：“离……不远”通常用于人或场所作主语，“食品”不能这样搭配。"}, {"text": "空调", "is_correct": false, "explanation": "语义：“空调”是电器，不是可以说远近的场所，句子说不通。"}], "explanations": {"风电场": "正确：“风电场”是一个场所，可以说它离学校远近，句子通顺。", "电视": "语义：“电视”不是地点，不能说“离我们学校不远”。", "食品": "搭配：“离……不远”通常用于人或场所作主语，“食品”不能这样搭配。", "空调": "语义：“空调”是电器，不是可以说远近的场所，句子说不通。"}, "sentence_index": 6, "correct_answer": "风电场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们每天在风电场里做饭。", "explanation": "这里应该用〈厨房〉。风电场是发电的场所，不是做饭的地方；做饭要在厨房。"}, {"text": "孩子们在风电场玩滑梯。", "explanation": "这里应该用〈游乐场〉。风电场不是供孩子玩耍的地方，玩滑梯要用“游乐场”。"}, {"text": "风电场里住着一家人，他们每天在一起吃饭。", "explanation": "这里应该用〈民居〉。风电场是发电的场所，不供人居住；住人的地方要用“民居”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26906, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末我们风电场玩。", "corrected_sentence": "周末我们去风电场玩。", "error_description": "错误形式：周末我们风电场玩；正确形式：周末我们去风电场玩。引出地点“风电场”的动词“去”不能省略，缺少它则不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26906, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台风电场的电供应给附近的城市。", "corrected_sentence": "这个风电场的电供应给附近的城市。", "error_description": "量词误用：“风电场”是场所，应用“座”或“个”，“台”多用于机器，不能说“这台风电场”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26908, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "乏力", "is_correct": true, "explanation": "正确：“乏力”指力量不足，与“强劲”相反；进攻“乏力”与进攻“强劲”正相对。"}, {"text": "稳健", "is_correct": false, "explanation": "“稳健”指稳当可靠，不表示力量弱，与“强劲”不构成反义。"}, {"text": "鲜艳", "is_correct": false, "explanation": "“鲜艳”指颜色明亮好看，与力量强弱无关，不构成反义。"}, {"text": "平淡", "is_correct": false, "explanation": "“平淡”指没有特色或波澜，与进攻的力量强弱不构成反义。"}], "correct_answer": "乏力", "explanations": {"乏力": "正确：“乏力”指力量不足，与“强劲”相反；进攻“乏力”与进攻“强劲”正相对。", "稳健": "“稳健”指稳当可靠，不表示力量弱，与“强劲”不构成反义。", "鲜艳": "“鲜艳”指颜色明亮好看，与力量强弱无关，不构成反义。", "平淡": "“平淡”指没有特色或波澜，与进攻的力量强弱不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd58b4158-fc4d-43e1-a537-f329b4639f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26908, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "疲软", "is_correct": true, "explanation": "正确：“疲软”指需求不旺，与需求“强劲”相反。"}, {"text": "平稳", "is_correct": false, "explanation": "“平稳”指稳定、没有大起大落，不表示强弱对立，不构成反义。"}, {"text": "活跃", "is_correct": false, "explanation": "“活跃”指热烈、有生气，与“强劲”相近，不构成反义。"}, {"text": "迅猛", "is_correct": false, "explanation": "“迅猛”指速度快、力量大，与“强劲”接近，不构成反义。"}], "correct_answer": "疲软", "explanations": {"疲软": "正确：“疲软”指需求不旺，与需求“强劲”相反。", "平稳": "“平稳”指稳定、没有大起大落，不表示强弱对立，不构成反义。", "活跃": "“活跃”指热烈、有生气，与“强劲”相近，不构成反义。", "迅猛": "“迅猛”指速度快、力量大，与“强劲”接近，不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd58b4158-fc4d-43e1-a537-f329b4639f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26908, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "非常有力。", "primary_collocate": null, "pronunciation": "qiáng jìn", "ipa": "tɕʰiɑŋ˧˥ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "这位歌手的声音很强劲。", "target_word": "强劲", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他有一个强劲的对手。", "target_word": "强劲", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今年经济增长很强劲。", "target_word": "强劲", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这支球队的进攻非常强劲。", "target_word": "强劲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的右脚很强劲，一脚就把球踢进了门。", "target_word": "强劲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐的节奏强劲，大家都跳起舞来。", "target_word": "强劲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司的销售一直很强劲。", "target_word": "强劲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说他的实力很强劲，一定能赢。", "target_word": "强劲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "强劲的鼓声让人心跳得更快。", "target_word": "强劲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个月房子的需求强劲，价格也涨了。", "target_word": "强劲", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "強勁", "label": "繁体"}], "register": "书面", "sense_fingerprint": "声音、对手、增长、需求等表现得非常有力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45a9c2e1-e793-492c-857c-afaaaa0fdb5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26908, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "强劲", "is_correct": true, "explanation": "正确：强劲，表示非常有力。"}, {"text": "前进", "is_correct": false, "explanation": "qián（第二声）与 qiáng 韵尾不同（-n 与 -ng），前进意思是向前移动。"}, {"text": "穷尽", "is_correct": false, "explanation": "jìn 相同，qióng 与 qiáng 主要元音不同（o 与 a），穷尽意思是用到没有剩余。"}, {"text": "详尽", "is_correct": false, "explanation": "xiáng 与 qiáng 声母不同（x 与 q），详尽意思是周密完整。"}], "explanations": {"强劲": "正确：强劲，表示非常有力。", "前进": "qián（第二声）与 qiáng 韵尾不同（-n 与 -ng），前进意思是向前移动。", "穷尽": "jìn 相同，qióng 与 qiáng 主要元音不同（o 与 a），穷尽意思是用到没有剩余。", "详尽": "xiáng 与 qiáng 声母不同（x 与 q），详尽意思是周密完整。"}, "sentence_index": null, "correct_answer": "强劲"}, "level_3": {"options": [{"text": "强劲", "is_correct": true, "explanation": "正确：强劲形容声音有力，与“声音很”搭配。"}, {"text": "陡峭", "is_correct": false, "explanation": "搭配：“陡峭”形容山坡等地势，不能用来形容声音。"}, {"text": "昂贵", "is_correct": false, "explanation": "搭配：“昂贵”说价格高，不用来形容声音。"}, {"text": "寂静", "is_correct": false, "explanation": "语义：“寂静”指没有声音，与“声音很”的描述矛盾。"}], "explanations": {"强劲": "正确：强劲形容声音有力，与“声音很”搭配。", "陡峭": "搭配：“陡峭”形容山坡等地势，不能用来形容声音。", "昂贵": "搭配：“昂贵”说价格高，不用来形容声音。", "寂静": "语义：“寂静”指没有声音，与“声音很”的描述矛盾。"}, "sentence_index": 0, "correct_answer": "强劲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电视的画面非常强劲。", "explanation": "这里应该用〈清晰〉。强劲形容有力的声音、进攻等；画面的清楚程度要说“清晰”。"}, {"text": "同学们对数学有强劲的兴趣。", "explanation": "这里应该用〈浓厚〉。强劲说力量有力，兴趣的程度要说“浓厚”。"}, {"text": "这次考试他的成绩很强劲，全班第一。", "explanation": "这里应该用〈好〉。强劲说力量有力，成绩的好坏要说“好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd58b4158-fc4d-43e1-a537-f329b4639f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26908, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "强劲", "is_correct": true, "explanation": "正确：强劲形容销售势头强，与“一直很”搭配。"}, {"text": "湿润", "is_correct": false, "explanation": "搭配：“湿润”形容空气、土地等，不用来形容销售。"}, {"text": "雪白", "is_correct": false, "explanation": "搭配：“雪白”形容颜色，不能用来形容销售情况。"}, {"text": "沉默", "is_correct": false, "explanation": "语义：“沉默”形容人或气氛不说话，与销售业绩的描述矛盾。"}], "explanations": {"强劲": "正确：强劲形容销售势头强，与“一直很”搭配。", "湿润": "搭配：“湿润”形容空气、土地等，不用来形容销售。", "雪白": "搭配：“雪白”形容颜色，不能用来形容销售情况。", "沉默": "语义：“沉默”形容人或气氛不说话，与销售业绩的描述矛盾。"}, "sentence_index": 6, "correct_answer": "强劲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的立场很强劲，从来不肯改变。", "explanation": "这里应该用〈坚定〉。强劲形容力量、势头；立场的坚定程度要说“坚定”。"}, {"text": "这份报告的解释很强劲，大家都听懂了。", "explanation": "这里应该用〈清晰〉。强劲不用来形容解释；说明讲得清楚要用“清晰”。"}, {"text": "会议的气氛很强劲，大家都不敢说话。", "explanation": "这里应该用〈严肃〉。强劲不用来形容气氛；气氛庄重要说“严肃”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd58b4158-fc4d-43e1-a537-f329b4639f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26908, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这支球队的防守有强劲。", "corrected_sentence": "这支球队的防守很强劲。", "error_description": "“强劲”前要用程度副词“很”，说“很强劲”；“有”不能直接修饰形容词作谓语，“有强劲”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd58b4158-fc4d-43e1-a537-f329b4639f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26908, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司的业绩一直了强劲。", "corrected_sentence": "公司的业绩一直很强劲。", "error_description": "“一直”与形容词之间要用程度副词“很”，不能用“了”；“一直了强劲”不成立，应说“一直很强劲”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd58b4158-fc4d-43e1-a537-f329b4639f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
