INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26910, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个数能被另一个数整除，这个数就是另一个数的倍数。", "primary_collocate": null, "pronunciation": "bèi shù", "ipa": "pei˥˩ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "十八是六的倍数，也是九的倍数。", "target_word": "倍数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你写出四的前五个倍数。", "target_word": "倍数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "二十一不是四的倍数，因为不能整除。", "target_word": "倍数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "六十是十的倍数，也是十二的倍数。", "target_word": "倍数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "个位是零或五的数都是五的倍数。", "target_word": "倍数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "三的倍数中，哪一个最接近一百？", "target_word": "倍数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个偶数的和还是二的倍数。", "target_word": "倍数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小红发现，七十二是八的倍数。", "target_word": "倍数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个班的人数是六的倍数，可以分成六组。", "target_word": "倍数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在纸上写了一些四的倍数。", "target_word": "倍数", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "公倍数", "label": "复合"}, {"form": "最小公倍数", "label": "复合"}, {"form": "倍數", "label": "繁体"}], "register": "中性", "sense_fingerprint": "倍数：能被另一个数整除的数，小学数学概念", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65bf7ffb-9382-49a3-a249-55e085870a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
